//! Layer Unit — Per-layer compute unit
//!
//! Consolidates all per-layer state (LoroDoc, dirty flag, authorization config,
//! per-subscriber state, observer subscription) into a single struct. Makes Scribe
//! a thin router over LayerUnit instances.
//!
//! ## Authorization model
//!
//! Each LayerUnit owns its subscribers and their capabilities. Authorization is
//! checked at broadcast time using per-subscriber state, not an eagerly-populated
//! HashSet. The `subscribers` map is `Arc<RwLock<...>>` so the observer async task
//! can read it for broadcast decisions.
//!
//! Also contains dynamic layer management (schema validation, permit preparation).

mod dynamic;

pub use dynamic::{
    handle_create_dynamic_layer, find_matching_dynamic_schema,
    handle_add_layer_access, handle_remove_layer_access,
};

use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

use tokio::sync::mpsc;

use domains::Layer;

use crate::BroadcastPayload;

// === Capability types ===

/// Cached capabilities from a layer permit
///
/// **Context**: Parsed from layer permit at subscription time.
/// Each field maps to a specific authorization check.
#[derive(Debug, Clone, Default)]
pub struct Capabilities {
    /// Can read layer data (receive broadcasts)
    pub read: bool,
    /// Can write to layer (send updates)
    pub write: bool,
    /// Can sync (bidirectional replication)
    pub sync: bool,
}

/// Layer-level configuration derived from permit
///
/// **Context**: Set once at layer creation, describes our own capabilities
/// for this layer (viewer side) or default capabilities (node side).
#[derive(Debug, Clone)]
pub struct LayerConfig {
    /// Our capabilities for this layer
    pub capabilities: Capabilities,
    /// sync: false — never broadcast to peers
    pub is_local_only: bool,
}

impl Default for LayerConfig {
    fn default() -> Self {
        Self {
            capabilities: Capabilities { read: true, write: true, sync: true },
            is_local_only: false,
        }
    }
}

/// Per-subscriber state within a LayerUnit
///
/// **Context**: Tracks what each subscriber can do with this specific layer.
/// Created when a peer subscribes and presents a layer permit.
pub struct LayerSubscriber {
    /// What this subscriber can do (from the layer permit we issued)
    pub capabilities: Capabilities,
    /// Their consent token (authorizes us to push updates to them)
    /// None until they send LayerConsent back
    pub consent_token: Option<String>,
    /// Their last known version vector for incremental sync
    pub version_vector: Vec<u8>,
    /// Channel to send broadcasts to this subscriber
    pub broadcast_tx: mpsc::Sender<BroadcastPayload>,
}

/// Per-layer compute unit — owns all state for a single layer
///
/// **Design**: Self-contained authorization and broadcast. Scribe routes
/// messages to LayerUnits; each unit knows its subscribers and their capabilities.
pub struct LayerUnit {
    // === CRDT ===
    /// The CRDT document
    layer: Layer,
    /// Needs flush to storage?
    dirty: bool,
    /// Loro observer subscription (dropped = unsubscribed)
    loro_sub: Option<loro::Subscription>,

    // === Authorization (from permit) ===
    /// Cached layer configuration (our capabilities, local-only flag)
    config: LayerConfig,
    /// Raw permit token (viewer side — the permit node gave us)
    permit_token: Option<String>,
    /// Created via dynamic_layer_schema (not static template)
    pub is_dynamic: bool,

    // === Subscriber state ===
    /// Per-subscriber state (did → subscriber)
    /// Arc<RwLock> because the observer async task needs shared read access
    subscribers: Arc<RwLock<HashMap<String, LayerSubscriber>>>,

    // === Lifecycle ===
    /// Last time this layer was accessed (for cold/warm eviction)
    last_accessed: Instant,
}

impl LayerUnit {
    /// Create a LayerUnit wrapping an existing layer
    pub fn new(layer: Layer) -> Self {
        Self {
            layer,
            dirty: false,
            loro_sub: None,
            config: LayerConfig::default(),
            permit_token: None,
            is_dynamic: false,
            subscribers: Arc::new(RwLock::new(HashMap::new())),
            last_accessed: Instant::now(),
        }
    }

    /// Create a LayerUnit with an empty LoroDoc
    pub fn new_empty() -> Self {
        Self::new(Layer::new())
    }

    /// Create a LayerUnit with specific config
    pub fn with_config(layer: Layer, config: LayerConfig) -> Self {
        let is_local_only = config.is_local_only;
        let mut unit = Self::new(layer);
        unit.config = config;
        // Keep is_local_only in sync for backward compat during migration
        unit.config.is_local_only = is_local_only;
        unit
    }

    // === Layer access ===

    /// Get a reference to the inner Layer
    pub fn layer(&self) -> &Layer {
        &self.layer
    }

    /// Get a mutable reference to the inner Layer
    pub fn layer_mut(&mut self) -> &mut Layer {
        &mut self.layer
    }

    /// Replace the inner layer (e.g. snapshot restore)
    pub fn replace_layer(&mut self, layer: Layer) {
        self.layer = layer;
        self.touch();
    }

    // === Config ===

    /// Get the layer configuration
    pub fn config(&self) -> &LayerConfig {
        &self.config
    }

    /// Set the layer configuration
    pub fn set_config(&mut self, config: LayerConfig) {
        self.config = config;
    }

    /// Get the raw permit token (viewer side)
    pub fn permit_token(&self) -> Option<&str> {
        self.permit_token.as_deref()
    }

    /// Set the raw permit token (viewer side)
    pub fn set_permit_token(&mut self, token: String) {
        self.permit_token = Some(token);
    }

    // === Dirty tracking ===

    /// Mark this layer as needing persistence
    pub fn mark_dirty(&mut self) {
        self.dirty = true;
    }

    /// Check if this layer needs persistence
    pub fn is_dirty(&self) -> bool {
        self.dirty
    }

    /// Clear the dirty flag without exporting
    pub fn clear_dirty(&mut self) {
        self.dirty = false;
    }

    /// Export snapshot if dirty, clear flag. Returns None if clean.
    pub fn take_dirty_snapshot(&mut self) -> Option<Vec<u8>> {
        if self.dirty {
            self.dirty = false;
            Some(self.layer.export_snapshot())
        } else {
            None
        }
    }

    // === Metadata ===

    /// Check if this layer is local-only (sync: false)
    pub fn is_local_only(&self) -> bool {
        self.config.is_local_only
    }

    /// Set the local-only flag
    pub fn set_local_only(&mut self, val: bool) {
        self.config.is_local_only = val;
    }

    /// Check if this layer was created dynamically
    pub fn is_dynamic(&self) -> bool {
        self.is_dynamic
    }

    // === Observer lifecycle ===

    /// Check if this layer has an active Loro observer
    pub fn has_observer(&self) -> bool {
        self.loro_sub.is_some()
    }

    /// Set the Loro observer subscription
    pub fn set_observer(&mut self, sub: loro::Subscription) {
        self.loro_sub = Some(sub);
    }

    /// Drop the observer (unsubscribes from Loro)
    pub fn clear_observer(&mut self) {
        self.loro_sub = None;
    }

    // === Subscriber management ===

    /// Get shared reference to subscribers (for observer to clone the Arc)
    pub fn subscribers(&self) -> &Arc<RwLock<HashMap<String, LayerSubscriber>>> {
        &self.subscribers
    }

    /// Add a subscriber with their capabilities and broadcast channel
    pub fn add_subscriber(
        &self,
        did: String,
        capabilities: Capabilities,
        broadcast_tx: mpsc::Sender<BroadcastPayload>,
    ) {
        if let Ok(mut subs) = self.subscribers.write() {
            subs.insert(did, LayerSubscriber {
                capabilities,
                consent_token: None,
                version_vector: Vec::new(),
                broadcast_tx,
            });
        }
    }

    /// Remove a subscriber, returning their state if present
    pub fn remove_subscriber(&self, did: &str) -> Option<LayerSubscriber> {
        if let Ok(mut subs) = self.subscribers.write() {
            subs.remove(did)
        } else {
            None
        }
    }

    /// Set consent token for a subscriber (authorizes us to push to them)
    ///
    /// **Context**: Viewer sent LayerConsent back after receiving LayerSync.
    pub fn set_consent(&self, did: &str, consent_token: String) {
        if let Ok(mut subs) = self.subscribers.write() {
            if let Some(sub) = subs.get_mut(did) {
                sub.consent_token = Some(consent_token);
            }
        }
    }

    /// Update a subscriber's version vector after successful broadcast
    pub fn update_subscriber_vector(&self, did: &str, vector: Vec<u8>) {
        if let Ok(mut subs) = self.subscribers.write() {
            if let Some(sub) = subs.get_mut(did) {
                sub.version_vector = vector;
            }
        }
    }

    /// Check if any subscribers are connected
    pub fn has_subscribers(&self) -> bool {
        self.subscribers.read()
            .map(|subs| !subs.is_empty())
            .unwrap_or(false)
    }

    // === Authorization checks ===

    /// Can we accept a write from this DID?
    ///
    /// **Context**: Node checks this when receiving an update from a peer.
    /// The peer must be a subscriber with write capability.
    pub fn can_accept_write_from(&self, did: &str) -> bool {
        self.subscribers.read()
            .map(|subs| {
                subs.get(did)
                    .map(|s| s.capabilities.write)
                    .unwrap_or(false)
            })
            .unwrap_or(false)
    }

    /// Can we push updates to this DID?
    ///
    /// **Context**: Checked at broadcast time. Subscriber must have read
    /// capability and have given consent.
    pub fn can_push_to(&self, did: &str) -> bool {
        self.subscribers.read()
            .map(|subs| {
                subs.get(did)
                    .map(|s| s.capabilities.read)
                    .unwrap_or(false)
            })
            .unwrap_or(false)
    }

    /// Can WE write to this layer locally? (viewer side check)
    pub fn can_local_write(&self) -> bool {
        self.config.capabilities.write
    }

    // === CRDT operations ===

    /// Export an incremental update for a specific subscriber
    ///
    /// **Context**: Uses the subscriber's last known version vector.
    /// Falls back to full snapshot if no vector cached or export fails.
    pub fn export_update_for(&self, did: &str) -> Vec<u8> {
        let their_vector = self.subscribers.read().ok().and_then(|subs| {
            subs.get(did).and_then(|s| {
                if s.version_vector.is_empty() { None } else { Some(s.version_vector.clone()) }
            })
        });

        if let Some(vector) = their_vector {
            self.layer.export_updates(&vector)
                .unwrap_or_else(|_| self.layer.export_snapshot())
        } else {
            self.layer.export_snapshot()
        }
    }

    // === Lifecycle ===

    /// Update last_accessed timestamp
    pub fn touch(&mut self) {
        self.last_accessed = Instant::now();
    }

    /// Check if this layer is cold (no access for `threshold` duration)
    pub fn is_cold(&self, threshold: Duration) -> bool {
        self.last_accessed.elapsed() > threshold
    }

}

#[cfg(test)]
mod tests {
    use super::*;
    use domains::Layer;

    #[test]
    fn test_new_empty() {
        let unit = LayerUnit::new_empty();
        assert!(!unit.is_dirty());
        assert!(!unit.is_local_only());
        assert!(!unit.is_dynamic());
        assert!(!unit.has_observer());
        assert!(!unit.has_subscribers());
    }

    #[test]
    fn test_new_with_layer() {
        let layer = Layer::new();
        let map = layer.loro().get_map("test");
        map.insert("key", "value").unwrap();
        layer.commit();

        let unit = LayerUnit::new(layer);
        let content = unit.layer().to_json();
        assert!(content.get("test").is_some());
    }

    #[test]
    fn test_with_config() {
        let config = LayerConfig {
            capabilities: Capabilities { read: true, write: false, sync: true },
            is_local_only: true,
        };
        let unit = LayerUnit::with_config(Layer::new(), config);
        assert!(unit.is_local_only());
        assert!(!unit.can_local_write());
        assert!(unit.config().capabilities.read);
    }

    #[test]
    fn test_dirty_tracking() {
        let mut unit = LayerUnit::new_empty();
        assert!(!unit.is_dirty());
        assert!(unit.take_dirty_snapshot().is_none());

        unit.mark_dirty();
        assert!(unit.is_dirty());

        let snapshot = unit.take_dirty_snapshot();
        assert!(snapshot.is_some());
        // Flag cleared after take
        assert!(!unit.is_dirty());
        assert!(unit.take_dirty_snapshot().is_none());
    }

    #[test]
    fn test_dirty_snapshot_contains_data() {
        let mut unit = LayerUnit::new_empty();
        let list = unit.layer().loro().get_list("items");
        list.push("hello").unwrap();
        unit.layer().commit();
        unit.mark_dirty();

        let snapshot = unit.take_dirty_snapshot().unwrap();
        let restored = Layer::from_snapshot(&snapshot).unwrap();
        let content = restored.to_json();
        assert!(content.get("items").is_some());
    }

    #[test]
    fn test_local_only_flag() {
        let mut unit = LayerUnit::new_empty();
        assert!(!unit.is_local_only());

        unit.set_local_only(true);
        assert!(unit.is_local_only());

        unit.set_local_only(false);
        assert!(!unit.is_local_only());
    }

    #[test]
    fn test_dynamic_flag() {
        let mut unit = LayerUnit::new_empty();
        assert!(!unit.is_dynamic());

        unit.is_dynamic = true;
        assert!(unit.is_dynamic());
    }

    #[test]
    fn test_observer_lifecycle() {
        let mut unit = LayerUnit::new_empty();
        assert!(!unit.has_observer());

        let sub = unit.layer().subscribe_root(|_| {});
        unit.set_observer(sub);
        assert!(unit.has_observer());

        unit.clear_observer();
        assert!(!unit.has_observer());
    }

    #[test]
    fn test_clear_dirty() {
        let mut unit = LayerUnit::new_empty();
        unit.mark_dirty();
        assert!(unit.is_dirty());

        unit.clear_dirty();
        assert!(!unit.is_dirty());
    }

    #[test]
    fn test_replace_layer() {
        let mut unit = LayerUnit::new_empty();
        let map = unit.layer().loro().get_map("old");
        map.insert("key", "val").unwrap();
        unit.layer().commit();

        let new_layer = Layer::new();
        let map2 = new_layer.loro().get_map("new");
        map2.insert("k", "v").unwrap();
        new_layer.commit();

        unit.replace_layer(new_layer);
        let content = unit.layer().to_json();
        assert!(content.get("new").is_some());
        assert!(content.get("old").is_none());
    }

    // === Subscriber tests ===

    fn make_tx() -> mpsc::Sender<BroadcastPayload> {
        let (tx, _rx) = mpsc::channel(16);
        tx
    }

    #[test]
    fn test_add_and_remove_subscriber() {
        let unit = LayerUnit::new_empty();
        assert!(!unit.has_subscribers());

        let caps = Capabilities { read: true, write: true, sync: true };
        unit.add_subscriber("did:key:alice".to_string(), caps, make_tx());
        assert!(unit.has_subscribers());
        assert!(unit.can_push_to("did:key:alice"));

        let removed = unit.remove_subscriber("did:key:alice");
        assert!(removed.is_some());
        assert!(!unit.has_subscribers());
        assert!(!unit.can_push_to("did:key:alice"));
    }

    #[test]
    fn test_can_accept_write_from() {
        let unit = LayerUnit::new_empty();

        // Not a subscriber
        assert!(!unit.can_accept_write_from("did:key:alice"));

        // Subscriber with write
        let caps = Capabilities { read: true, write: true, sync: true };
        unit.add_subscriber("did:key:alice".to_string(), caps, make_tx());
        assert!(unit.can_accept_write_from("did:key:alice"));

        // Subscriber without write
        let read_only = Capabilities { read: true, write: false, sync: true };
        unit.add_subscriber("did:key:bob".to_string(), read_only, make_tx());
        assert!(!unit.can_accept_write_from("did:key:bob"));
    }

    #[test]
    fn test_can_push_to() {
        let unit = LayerUnit::new_empty();

        // Not a subscriber
        assert!(!unit.can_push_to("did:key:alice"));

        // Subscriber with read
        let caps = Capabilities { read: true, write: false, sync: true };
        unit.add_subscriber("did:key:alice".to_string(), caps, make_tx());
        assert!(unit.can_push_to("did:key:alice"));

        // Subscriber without read
        let no_read = Capabilities { read: false, write: true, sync: false };
        unit.add_subscriber("did:key:bob".to_string(), no_read, make_tx());
        assert!(!unit.can_push_to("did:key:bob"));
    }

    #[test]
    fn test_set_consent() {
        let unit = LayerUnit::new_empty();
        let caps = Capabilities { read: true, write: true, sync: true };
        unit.add_subscriber("did:key:alice".to_string(), caps, make_tx());

        // Initially no consent
        {
            let subs = unit.subscribers().read().unwrap();
            assert!(subs.get("did:key:alice").unwrap().consent_token.is_none());
        }

        unit.set_consent("did:key:alice", "consent_token_123".to_string());
        {
            let subs = unit.subscribers().read().unwrap();
            assert_eq!(
                subs.get("did:key:alice").unwrap().consent_token.as_deref(),
                Some("consent_token_123")
            );
        }
    }

    #[test]
    fn test_update_subscriber_vector() {
        let unit = LayerUnit::new_empty();
        let caps = Capabilities { read: true, write: true, sync: true };
        unit.add_subscriber("did:key:alice".to_string(), caps, make_tx());

        // Initially empty
        {
            let subs = unit.subscribers().read().unwrap();
            assert!(subs.get("did:key:alice").unwrap().version_vector.is_empty());
        }

        let vv = vec![1, 2, 3, 4];
        unit.update_subscriber_vector("did:key:alice", vv.clone());
        {
            let subs = unit.subscribers().read().unwrap();
            assert_eq!(subs.get("did:key:alice").unwrap().version_vector, vv);
        }
    }

    #[test]
    fn test_export_update_for() {
        let mut unit = LayerUnit::new_empty();
        let list = unit.layer().loro().get_list("items");
        list.push("hello").unwrap();
        unit.layer().commit();

        // No subscriber → full snapshot
        let snapshot = unit.export_update_for("did:key:alice");
        assert!(!snapshot.is_empty());

        // Add subscriber with empty VV → full snapshot
        let caps = Capabilities { read: true, write: true, sync: true };
        unit.add_subscriber("did:key:alice".to_string(), caps, make_tx());
        let snapshot2 = unit.export_update_for("did:key:alice");
        assert!(!snapshot2.is_empty());

        // Set a VV → incremental export
        let current_vv = unit.layer().version_vector();
        unit.update_subscriber_vector("did:key:alice", current_vv);

        // Add more data
        let list = unit.layer().loro().get_list("items");
        list.push("world").unwrap();
        unit.layer().commit();

        let incremental = unit.export_update_for("did:key:alice");
        // Incremental should be smaller than full snapshot
        let full = unit.layer().export_snapshot();
        assert!(incremental.len() < full.len());
    }

    #[test]
    fn test_lifecycle() {
        let mut unit = LayerUnit::new_empty();

        // Just created — not cold
        assert!(!unit.is_cold(Duration::from_secs(60)));

        // Touch resets the timer
        unit.touch();
        assert!(!unit.is_cold(Duration::from_secs(60)));

        // Zero threshold → always cold
        assert!(unit.is_cold(Duration::from_secs(0)));
    }

    #[test]
    fn test_can_local_write() {
        let unit = LayerUnit::new_empty();
        // Default config has write: true
        assert!(unit.can_local_write());

        let read_only_config = LayerConfig {
            capabilities: Capabilities { read: true, write: false, sync: true },
            is_local_only: false,
        };
        let unit2 = LayerUnit::with_config(Layer::new(), read_only_config);
        assert!(!unit2.can_local_write());
    }

    #[test]
    fn test_permit_token() {
        let mut unit = LayerUnit::new_empty();
        assert!(unit.permit_token().is_none());

        unit.set_permit_token("token_abc".to_string());
        assert_eq!(unit.permit_token(), Some("token_abc"));
    }
}

//! Scribe actor state and configuration types
//!
//! Contains all state structs, type aliases, and configuration for the Scribe actor.

use std::collections::HashMap;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex, RwLock};

use tokio::sync::{broadcast, mpsc};

use domains::{Layer, QueryDelta, QueryResult, QuerySpec};

use crate::layer_unit::LayerUnit;
use crate::{
    BroadcastPayload, EphemeralOutbound, LayerStorageRef, PageUpdate, PeerResolverRef,
    PeerVectorStorageRef, PermitIssuerRef, SyncEvent,
};

// Layer Name Normalization

/// Normalize a layer name by stripping `{page_id}/` prefix if present
///
/// **Context**: Lua apps and wire protocol use prefixed names (`{page_id}/messages`)
/// but Scribe stores layers with bare names (`messages`). This strips the prefix
/// at the Scribe boundary so all internal lookups use consistent bare names.
pub fn normalize_layer_name(name: &str, page_id: &str) -> String {
    let prefix = format!("{}/", page_id);
    if let Some(bare) = name.strip_prefix(&prefix) {
        bare.to_string()
    } else {
        name.to_string()
    }
}

// Capture Helpers

/// Shorten a DID to its last 12 characters for compact logging
pub fn short_did(did: &str) -> &str {
    let start = did.len().saturating_sub(12);
    &did[start..]
}

/// Shorten a layer name by collapsing `did:key:...` segments to `...`
pub fn layer_short(name: &str) -> String {
    name.split('/')
        .map(|seg| {
            if seg.starts_with("did:key:") {
                "..."
            } else {
                seg
            }
        })
        .collect::<Vec<_>>()
        .join("/")
}

// Sync Configuration

/// Sync mode derived from permit capabilities
///
/// **Design**: Capability-based, not role-based
/// - Mode is derived from permit's sync configuration
/// - No hardcoded role names in decision logic
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SyncMode {
    /// Sync to a specific source node (users sync to their node)
    ToSource,
    /// Broadcast to all authorized peers (node mode)
    Broadcast,
}

impl Default for SyncMode {
    fn default() -> Self {
        SyncMode::Broadcast
    }
}

/// Sync configuration derived from permit
///
/// **Context**: Determines how this Scribe syncs based on permit capabilities
/// - ToSource: Sync to a specific source node (owner/viewer/customer)
/// - Broadcast: Broadcast to all authorized peers (node)
#[derive(Debug, Clone)]
pub struct SyncConfig {
    /// Sync mode derived from permit (capability-based)
    pub mode: SyncMode,
    /// For ToSource: node_id to sync to
    /// For Broadcast: None (uses list_authorized_users callback)
    pub sync_target: Option<String>,
}

// Subscriber Types

/// Information about a subscribed peer
///
/// **Design**: Stores the parsed permit directly instead of extracted fields.
/// All access checks delegate to gurkha::Permit methods, ensuring consistency.
pub struct SubscriberInfo {
    /// Parsed page permit for all access checks (static layers)
    /// Stores the full permit so we can use its methods directly
    pub permit: gurkha::Permit,
    /// Subscriber's DID (for pattern expansion with {aud})
    /// Extracted from permit audience and normalized to DID format
    pub subscriber_did: String,
    /// Whether this subscriber is visible (from permit presence config)
    /// Visible peers have their entry written to the presence layer
    pub is_visible: bool,
    /// Whether this subscriber can see others' presence
    /// Gates whether the presence layer is synced to this peer
    pub can_see_others: bool,
    /// Display name for this subscriber (from permit presence config)
    pub display_name: Option<String>,
    /// Channel to send CRDT broadcasts
    pub broadcast_tx: mpsc::Sender<BroadcastPayload>,
    /// Channel to send ephemeral broadcasts (cursor, typing)
    /// PeerActor creates this, spawns listener that sends datagrams
    pub ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
    /// Their last known state vectors (layer_name → version_vector)
    pub vectors: HashMap<String, Vec<u8>>,
}

impl SubscriberInfo {
    /// Check if subscriber can receive updates for layer via page permit
    pub fn can_receive_layer(&self, layer_name: &str, page_id: &str) -> bool {
        // Block presence layer for peers who can't see others
        if (layer_name == "presence" || layer_name.ends_with("/presence")) && !self.can_see_others {
            return false;
        }
        // Check if layer is in no_incoming_updates (sync facts)
        if self
            .permit
            .sync_facts()
            .no_incoming_updates
            .contains(&layer_name.to_string())
        {
            return false;
        }
        self.permit
            .can_read_layer(layer_name, page_id, &self.subscriber_did)
    }

    /// Check if subscriber can write to layer
    ///
    /// **Context**: Used during incoming update validation
    /// **Note**: Write auth stays subscriber-centric for now. For dynamic layer writes,
    /// the node trusts sync_target (path 2 in Permissions::can_write).
    pub fn can_write_layer(&self, layer_name: &str, page_id: &str) -> bool {
        self.permit
            .can_write_layer(layer_name, page_id, &self.subscriber_did)
    }
}

/// Query subscription info
pub struct QuerySubscriberInfo {
    /// Query specification
    pub spec: QuerySpec,
    /// Channel to send deltas
    pub delta_tx: mpsc::Sender<QueryDelta>,
    /// Current version (monotonically increasing)
    pub version: u64,
    /// Last known result (for computing deltas)
    pub last_result: Option<QueryResult>,
}

// Actor State

/// Scribe actor state
pub struct ScribeState {
    /// Page identifier
    pub page_id: String,
    /// Per-layer compute units (layer_name → LayerUnit)
    pub units: HashMap<String, LayerUnit>,
    /// Peer subscribers (user_did, device_id) → SubscriberInfo
    /// Arc<RwLock> allows Loro observer callback to send directly to peers
    pub subscribers: Arc<RwLock<HashMap<(String, String), SubscriberInfo>>>,
    /// Query subscribers (query_id → QuerySubscriberInfo)
    pub query_subscribers: HashMap<String, QuerySubscriberInfo>,

    /// Layer persistence (saves layer snapshots)
    pub layer_storage: LayerStorageRef,
    /// Peer vector persistence (saves/loads peer state vectors)
    pub vector_storage: PeerVectorStorageRef,
    /// Peer resolver (node mode only) - lists authorized users, loads permits
    pub peer_resolver: Option<PeerResolverRef>,
    /// Permit issuer (node mode only) - issues layer permits for dynamic layers
    pub permit_issuer: Option<PermitIssuerRef>,

    /// Sync configuration derived from permit (mode + sync_target)
    pub sync_config: Option<SyncConfig>,
    /// Channel to emit sync events (EnsureSync) - consumed by Coordinator
    pub sync_event_tx: Option<mpsc::Sender<SyncEvent>>,

    /// Broadcast channel for capture system (pre-serialized JSON lines)
    pub capture_tx: Option<broadcast::Sender<String>>,
    /// Monotonic counter for capture event ordering (disambiguates same-millisecond events)
    pub capture_seq: AtomicU64,

    /// Unified page update channel - all events flow through here
    /// **Consumers**: UI/Lua callbacks, Broadcast to peers, Derivation engine
    /// **Design**: Single channel for layer changes, ephemeral data, peer presence
    /// **Arc<RwLock>**: Shared with observer tasks so new subscribers are visible
    pub page_update_subscribers: Arc<RwLock<Vec<mpsc::Sender<PageUpdate>>>>,

    /// Pending update source for observer context
    /// **Context**: Set before import() so observer knows who caused the change
    /// **Usage**: Observer reads this to populate `from_peer` in PageEvent
    /// **Cleared**: After import() completes
    pub pending_update_source: Arc<Mutex<Option<(String, String)>>>,

    // Note: ephemeral events now go through page_update_subscribers (PageUpdate::Ephemeral)
    // outbound ephemeral goes directly via SubscriberInfo.ephemeral_tx (Scribe → PeerActor channels)
    /// Validation handle (for kunki node mode validation)
    /// If provided, Scribe delegates validation to external ValidationService
    /// This enables validation.lua to access presence_lib from LuaRuntime
    /// Falls back to local validation if not available (though we're removing ScribeLuaRuntime)
    pub validation_handle: Option<crate::validation_handle::ValidationHandle>,

    /// Parsed permit - provides should_sync_layer, can_write_layer etc.
    /// Uses gurkha::Permit directly with page_id/did passed to methods
    pub our_permit: Option<gurkha::Permit>,
    /// Our DID (for pattern expansion with {aud})
    pub our_did: String,

    /// Shutdown sender for node script tick loop (if running)
    /// **Context**: Set when is_node=true and entry_node found in manifest
    /// **Usage**: Send () to shutdown the tick loop
    pub node_script_shutdown: Option<mpsc::Sender<()>>,

}

/// Arguments for spawning Scribe
pub struct ScribeArgs {
    pub page_id: String,
    pub layers: HashMap<String, Layer>,

    /// Layer persistence (saves layer snapshots)
    pub layer_storage: LayerStorageRef,
    /// Peer vector persistence (saves/loads peer state vectors)
    pub vector_storage: PeerVectorStorageRef,
    /// Peer resolver (node mode only) - lists authorized users, loads permits
    pub peer_resolver: Option<PeerResolverRef>,
    /// Permit issuer (node mode only) - issues layer permits for dynamic layers
    pub permit_issuer: Option<PermitIssuerRef>,

    /// Optional: Sync configuration derived from permit (relationship + sync_target)
    /// - Owner: sync to sovereign node
    /// - Node: broadcast only (no outbound sync)
    /// - Viewer: sync to source node
    pub sync_config: Option<SyncConfig>,
    /// Channel to emit sync events (EnsureSync) - consumed by Coordinator
    pub sync_event_tx: Option<mpsc::Sender<SyncEvent>>,
    /// Broadcast channel for capture system (pre-serialized JSON lines)
    pub capture_tx: Option<broadcast::Sender<String>>,
    /// Validation handle (for kunki node mode validation)
    /// If provided, Scribe delegates validation to external ValidationService
    pub validation_handle: Option<crate::validation_handle::ValidationHandle>,
    /// Our permit for this page (local write authorization)
    /// Used to check if we can write to a layer before committing
    pub our_permit: Option<String>,
    /// Our DID (for pattern expansion and validation)
    pub our_did: String,
    /// Our username (for node script permit bindings)
    pub our_username: String,
    /// Whether this Scribe runs on a node (enables derivation engine and node scripts)
    pub is_node: bool,
    // Note: ephemeral_broadcast_tx removed - outbound ephemeral now goes directly via
    // SubscriberInfo.ephemeral_tx (Scribe → PeerActor channels)
}

impl ScribeState {
    /// Get the next capture sequence number (monotonically increasing)
    fn next_capture_seq(&self) -> u64 {
        self.capture_seq.fetch_add(1, Ordering::Relaxed)
    }

    /// Check if a layer should sync based on permit configuration
    ///
    /// **Context**: Used to filter out local-only layers (sync: false) before broadcasting
    /// **Returns**: true if layer should sync, false if local-only
    pub fn should_sync_layer(&self, layer_name: &str) -> bool {
        self.our_permit
            .as_ref()
            .map(|permit| permit.should_sync_layer(layer_name, &self.page_id, &self.our_did))
            .unwrap_or(true) // No permit means sync everything
    }

    /// Check if we can write to a layer
    pub fn can_write_layer(&self, layer_name: &str) -> bool {
        self.our_permit
            .as_ref()
            .map(|permit| permit.can_write_layer(layer_name, &self.page_id, &self.our_did))
            .unwrap_or(true) // No permit means full access
    }

    /// Emit a sync event to the capture channel (pre-serialized JSON line)
    ///
    /// **Context**: Called before sync_event_tx.send() to capture SyncEvent for observability
    pub fn emit_sync_event_capture(&self, event: &SyncEvent) {
        if let Some(ref tx) = self.capture_tx {
            let ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_millis())
                .unwrap_or(0);
            if let Ok(json) = serde_json::to_string(&serde_json::json!({
                "type": "sync_event",
                "ts": ts,
                "seq": self.next_capture_seq(),
                "page_id": &self.page_id,
                "data": event,
            })) {
                let _ = tx.send(json);
            }

            match event {
                SyncEvent::EnsureSync { .. } => {}
            }
        }
    }

    /// Emit a layer authorization event to the capture channel
    ///
    /// **Context**: Called when a DID is authorized/pending for a layer, for observability
    pub fn emit_layer_auth_capture(&self, layer: &str, did: &str, action: &str) {
        if let Some(ref tx) = self.capture_tx {
            let ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_millis())
                .unwrap_or(0);
            if let Ok(json) = serde_json::to_string(&serde_json::json!({
                "type": "layer_auth",
                "ts": ts,
                "seq": self.next_capture_seq(),
                "page_id": &self.page_id,
                "layer": layer,
                "layer_short": layer_short(layer),
                "did": did,
                "short_did": short_did(did),
                "action": action,
            })) {
                let _ = tx.send(json);
            }
        }
    }

    /// Emit a write permission check result to the capture channel
    ///
    /// **Context**: Called from Permissions::can_write to trace authorization decisions
    pub fn emit_permission_check_capture(
        &self,
        layer: &str,
        peer_did: &str,
        result: &str,
        granted_by: &str,
    ) {
        if let Some(ref tx) = self.capture_tx {
            let ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_millis())
                .unwrap_or(0);
            if let Ok(json) = serde_json::to_string(&serde_json::json!({
                "type": "permission_check",
                "ts": ts,
                "seq": self.next_capture_seq(),
                "page_id": &self.page_id,
                "layer": layer,
                "layer_short": layer_short(layer),
                "peer_did": peer_did,
                "short_did": short_did(peer_did),
                "operation": "write",
                "result": result,
                "granted_by": granted_by,
            })) {
                let _ = tx.send(json);
            }
        }
    }

    /// Emit an apply update outcome to the capture channel
    ///
    /// **Context**: Called from handle_apply_update to trace update application results
    pub fn emit_apply_update_capture(
        &self,
        layer: &str,
        from_peer: Option<&str>,
        result: &str,
        reason: Option<&str>,
    ) {
        if let Some(ref tx) = self.capture_tx {
            let ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_millis())
                .unwrap_or(0);
            if let Ok(json) = serde_json::to_string(&serde_json::json!({
                "type": "apply_update",
                "ts": ts,
                "seq": self.next_capture_seq(),
                "page_id": &self.page_id,
                "layer": layer,
                "layer_short": layer_short(layer),
                "from_peer": from_peer,
                "short_did": from_peer.map(short_did),
                "result": result,
                "reason": reason,
            })) {
                let _ = tx.send(json);
            }
        }
    }

    /// Emit a page update to the capture channel (pre-serialized JSON line)
    ///
    /// **Context**: Called alongside page_update_subscribers fanout for observability
    pub fn emit_page_update_capture(&self, update: &PageUpdate) {
        if let Some(ref tx) = self.capture_tx {
            let ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_millis())
                .unwrap_or(0);
            if let Ok(json) = serde_json::to_string(&serde_json::json!({
                "type": "page_update",
                "ts": ts,
                "seq": self.next_capture_seq(),
                "page_id": &self.page_id,
                "data": update,
            })) {
                let _ = tx.send(json);
            }
        }
    }

    /// Emit a subscriber state snapshot to the capture channel
    ///
    /// **Context**: Called after handle_subscribe() completes to show what layers a peer can access
    pub fn emit_subscriber_state_capture(
        &self,
        peer_did: &str,
        authorized_layers: &[String],
        total_layers: usize,
        can_see_others: bool,
        is_visible: bool,
    ) {
        if let Some(ref tx) = self.capture_tx {
            let ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_millis())
                .unwrap_or(0);
            let short_layers: Vec<String> =
                authorized_layers.iter().map(|l| layer_short(l)).collect();
            if let Ok(json) = serde_json::to_string(&serde_json::json!({
                "type": "subscriber_state",
                "ts": ts,
                "seq": self.next_capture_seq(),
                "page_id": &self.page_id,
                "peer_did": peer_did,
                "short_did": short_did(peer_did),
                "authorized_layers": authorized_layers,
                "authorized_layers_short": short_layers,
                "total_layers": total_layers,
                "can_see_others": can_see_others,
                "is_visible": is_visible,
            })) {
                let _ = tx.send(json);
            }
        }
    }

    /// Emit a broadcast decision skip event to the capture channel
    ///
    /// **Context**: Called when a subscriber is skipped during broadcast, for observability
    pub fn emit_broadcast_decision_capture(&self, layer: &str, peer_did: &str, reason: &str) {
        if let Some(ref tx) = self.capture_tx {
            let ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_millis())
                .unwrap_or(0);
            if let Ok(json) = serde_json::to_string(&serde_json::json!({
                "type": "broadcast_decision",
                "ts": ts,
                "seq": self.next_capture_seq(),
                "page_id": &self.page_id,
                "layer": layer,
                "layer_short": layer_short(layer),
                "peer_did": peer_did,
                "short_did": short_did(peer_did),
                "decision": "skip",
                "reason": reason,
            })) {
                let _ = tx.send(json);
            }
        }
    }
}

