 660→                if let Err(ref e) = result {
 661→                    warn!(
 662→                        page_id = %state.page_id,
 663→                        layer = %layer_name,
 664→                        did = %did,
 665→                        error = %e,
 666→                        "AddLayerAccess failed"
 667→                    );
 668→                }
 669→                let _ = reply.send(result);
 670→            }
 671→
 672→            ScribeMessage::RemoveLayerAccess { layer_name, did, reply } => {
 673→                let result = crate::layer_unit::handle_remove_layer_access(state, &layer_name, &did);
 674→                let _ = reply.send(result);
 675→            }
 676→
 677→            ScribeMessage::ExportLayerSnapshot { layer_name, reply } => {
 678→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 679→                let result = if let Some(unit) = state.units.get(&layer_name) {
 680→                    let snapshot = unit.layer().export_snapshot();
 681→                    let state_vector = unit.layer().version_vector();
 682→                    Ok((snapshot, state_vector))
 683→                } else {
 684→                    Err(format!("Layer '{}' not found", layer_name))
 685→                };
 686→                let _ = reply.send(result);
 687→            }
 688→
 689→            ScribeMessage::AuthorizeLayerSubscriber { layer_name, subscriber_did } => {
 690→                let bare = normalize_layer_name(&layer_name, &state.page_id);
 691→                if let Some(unit) = state.units.get(&bare) {
 692→                    // Look up broadcast_tx from ScribeState.subscribers
 693→                    let broadcast_tx = state.subscribers.read().ok().and_then(|subs| {
 694→                        subs.iter()
 695→                            .find(|((d, _), _)| d == &subscriber_did)
 696→                            .map(|(_, info)| info.broadcast_tx.clone())
 697→                    });
 698→                    if let Some(tx) = broadcast_tx {
 699→                        let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
 700→                        unit.add_subscriber(subscriber_did.clone(), caps, tx);
 701→                        state.emit_layer_auth_capture(&bare, &subscriber_did, "subscriber_added");
 702→                        info!(layer = %bare, did = %subscriber_did, "Added subscriber for layer");
 703→                    } else {
 704→                        warn!(layer = %bare, did = %subscriber_did, "AuthorizeLayerSubscriber: DID not connected, skipping");
 705→                    }
 706→                } else {
 707→                    info!(layer = %bare, did = %subscriber_did, "AuthorizeLayerSubscriber: layer not found, skipping");
 708→                }
 709→            }
 710→
 711→            ScribeMessage::GetUnsyncedSyncMeta { reply } => {
 712→                let entries = sync::sync_meta::read_unsynced_entries(state, &state.our_did.clone());
 713→                let _ = reply.send(entries);
 714→            }
 715→
 716→            ScribeMessage::HandleLayerSubscribe { layer_name, peer_did, reply } => {
 717→                let bare = crate::state::normalize_layer_name(&layer_name, &state.page_id);
 718→
 719→                // If layer doesn't exist but matches a dynamic schema, create it empty.
 720→                //
 721→                // **Context**: Timing race — __sync_meta broadcasts immediately (node is
 722→                // subscriber), but creator's dynamic layer data may not have synced yet.
 723→                // Peer discovers the entry in __sync_meta and sends LayerSubscribe before
 724→                // the layer exists on node. We create an empty layer; creator's data will
 725→                // arrive later via normal SyncOffer and broadcast to the now-subscribed peer.
 726→                if !state.units.contains_key(&bare) {
 727→                    if let Some(ref permit) = state.our_permit {
 728→                        if crate::layer_unit::find_matching_dynamic_schema(permit, &bare, &state.page_id).is_some() {
 729→                            info!(layer = %bare, "Creating empty dynamic layer for early LayerSubscribe");
 730→                            let mut unit = crate::layer_unit::LayerUnit::new_empty();
 731→                            unit.set_local_only(false);
 732→                            unit.is_dynamic = true;
 733→                            state.units.insert(bare.clone(), unit);
 734→                            crate::loro_observer::setup_layer_observer(state, &bare);
 735→                        }
 736→                    }
 737→                }
 738→
 739→                let result = (|| -> std::result::Result<(Vec<u8>, Vec<u8>, String), String> {
 740→                    let unit = state.units.get(&bare)
 741→                        .ok_or_else(|| format!("Layer '{}' not found", bare))?;
 742→
 743→                    // Issue permit via PermitIssuer
 744→                    let full_name = format!("{}/{}", state.page_id, bare);
 745→                    let permit_token = issue_layer_permit_for_subscribe(
 746→                        state, &peer_did, &bare, &full_name,
 747→                    )?;
 748→
 749→                    // Add peer as subscriber so they receive future broadcasts
 750→                    if let Ok(subs) = state.subscribers.read() {
 751→                        if let Some(sub_info) = subs.iter()
 752→                            .find(|((did, _), _)| did == &peer_did)
 753→                            .map(|(_, info)| info)
 754→                        {
 755→                            let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
 756→                            unit.add_subscriber(peer_did.clone(), caps, sub_info.broadcast_tx.clone());
 757→                        }
 758→                    }
 759→
 760→                    let snapshot = unit.layer().export_snapshot();
 761→                    let state_vector = unit.layer().version_vector();
 762→                    Ok((snapshot, state_vector, permit_token))
 763→                })();
 764→                let _ = reply.send(result);
 765→            }
 766→
 767→            ScribeMessage::MarkSyncMetaSynced { layer_name } => {
 768→                let our_did = state.our_did.clone();
 769→                sync::sync_meta::mark_entry_synced(state, &our_did, &layer_name);
 770→            }
 771→
 772→            ScribeMessage::Shutdown => {
 773→                info!(page_id = %state.page_id, "Scribe shutting down");
 774→                sync::handle_flush(state).await;
 775→                myself.stop(Some("shutdown".to_string()));
 776→            }
 777→
 778→            // Ephemeral events (from datagrams via PeerActor)
 779→            ScribeMessage::RemoteEphemeral { user_did, device_id, payload } => {
 780→                // Log payload content for debugging
 781→                let payload_str = std::str::from_utf8(&payload).unwrap_or("<binary>");
 782→                debug!(
 783→                    page_id = %state.page_id,
 784→                    user_did = ?user_did,
 785→                    device_id = ?device_id,
 786→                    payload_len = payload.len(),
 787→                    payload = %payload_str,
 788→                    our_did = %state.our_did,
 789→                    "Scribe received RemoteEphemeral"
 790→                );
 791→                // 1. Forward to local app layer (if we have sender info)
 792→                if let Some(ref did) = user_did {
 793→                    let handled = route_remote_ephemeral(state, did, &payload);
 794→                    debug!(page_id = %state.page_id, handled = handled, our_did = %state.our_did, "route_remote_ephemeral returned");
 795→                    if !handled {
 796→                        let dev_id = device_id.as_deref().unwrap_or_default();
 797→                        emit_raw_ephemeral(state, did, dev_id, &payload);
 798→                    }
 799→                } else {
 800→                    debug!(page_id = %state.page_id, "RemoteEphemeral without user_did - not emitting to local app");
 801→                }
 802→
 803→                // 2. Relay to other subscribers (node mode relay) - exclude sender
 804→                let exclude = match (&user_did, &device_id) {
 805→                    (Some(d), Some(dev)) => Some((d.as_str(), dev.as_str())),
 806→                    _ => None,
 807→                };
 808→                broadcast_ephemeral_to_subscribers(state, &payload, exclude);
 809→            }
 810→
 811→            ScribeMessage::SendEphemeral { payload } => {
 812→                // Broadcast ephemeral data directly to all subscribed PeerActors
 813→                // No exclusion - this is local user action, send to everyone
 814→                debug!(page_id = %state.page_id, payload_len = payload.len(), "Broadcasting ephemeral to all subscribers");
 815→                broadcast_ephemeral_to_subscribers(state, &payload, None);
 816→            }
 817→
 818→            ScribeMessage::SendStructuredEphemeral { func, args } => {
 819→                // Log the incoming request
 820→                let has_permit = state.our_permit.is_some();
 821→                let ephemeral_funcs = state.our_permit
 822→                    .as_ref()
 823→                    .map(|p| p.ephemeral_funcs().to_vec())
 824→                    .unwrap_or_default();
 825→                debug!(
 826→                    page_id = %state.page_id,
 827→                    func = %func,
 828→                    has_permit = has_permit,
 829→                    ephemeral_funcs = ?ephemeral_funcs,
 830→                    our_did = %state.our_did,
 831→                    "SendStructuredEphemeral received"
 832→                );
 833→
 834→                // Validate func against our permit's ephemeral_funcs (if set)
 835→                // Empty ephemeral_funcs list means all funcs allowed
 836→                let can_send = state.our_permit
 837→                    .as_ref()
 838→                    .map(|p| p.can_send_ephemeral(&func))
 839→                    .unwrap_or(true); // No permit = allow (local mode)
 840→
 841→                if !can_send {
 842→                    warn!(page_id = %state.page_id, func = %func, "Structured ephemeral func not allowed by permit");
 843→                    return Ok(());
 844→                }
 845→
 846→                // Broadcast as StructuredEphemeral to app subscribers (local UI)
 847→                let our_did = state.our_did.clone();
 848→                emit_structured_ephemeral(state, &our_did, &func, &args);
 849→
 850→                // Also broadcast via ephemeral channel for remote peers
 851→                // PeerActor should be subscribed to this Scribe with ephemeral_tx
 852→                // Include from_did so relayed messages preserve original sender identity
 853→                let payload = serde_json::json!({
 854→                    "type": "structured",
 855→                    "from_did": our_did,
 856→                    "func": func,
 857→                    "args": args
 858→                });
 859→                if let Ok(bytes) = serde_json::to_vec(&payload) {
 860→                    debug!(
 861→                        page_id = %state.page_id,
 862→                        func = %func,
 863→                        "Broadcasting structured ephemeral to PeerActor subscribers"
 864→                    );
 865→                    broadcast_ephemeral_to_subscribers(state, &bytes, None);
 866→                }
 867→            }
 868→
 869→            ScribeMessage::RemoteStructuredEphemeral { from_did, device_id, func, args } => {
 870→                // Validate func against sender's permit
 871→                let can_send = {
 872→                    let subs = state.subscribers.read().ok();
 873→                    subs.and_then(|s| {
 874→                        s.get(&(from_did.clone(), device_id.clone()))
 875→                            .map(|info| info.permit.can_send_ephemeral(&func))
 876→                    }).unwrap_or(false) // Unknown sender = reject
 877→                };
 878→
 879→                if !can_send {
 880→                    warn!(
 881→                        page_id = %state.page_id,
 882→                        from_did = %from_did,
 883→                        func = %func,
 884→                        "Remote structured ephemeral rejected - func not allowed"
 885→                    );
 886→                    return Ok(());
 887→                }
 888→
 889→                // Emit to local app subscribers
 890→                emit_structured_ephemeral(state, &from_did, &func, &args);
 891→
 892→                debug!(
 893→                    page_id = %state.page_id,
 894→                    from_did = %from_did,
 895→                    func = %func,
 896→                    "Processed remote structured ephemeral"
 897→                );
 898→            }
 899→
 900→            // Note: Ephemeral events now go through SubscribeToPageUpdates (PageUpdate::Ephemeral)
 901→
 902→            // Derivation operations (now handled by kunki/LuaRuntime externally)
 903→            ScribeMessage::RebuildDerived { target: _, reply } => {
 904→                // Derivation is now handled by kunki, not Scribe
 905→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
 906→            }
 907→
 908→            ScribeMessage::RebuildAllDerived { reply } => {
 909→                // Derivation is now handled by kunki, not Scribe
 910→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
 911→            }
 912→
 913→            ScribeMessage::IsDerivationEnabled { reply } => {
 914→                // Derivation is now external, Scribe always returns false
 915→                let _ = reply.send(false);
 916→            }
 917→
 918→            ScribeMessage::CreateDerivedLayer { target_layer } => {
 919→                let target_layer = normalize_layer_name(&target_layer, &state.page_id);
 920→                // Create the derived layer (empty) so it exists for subscribers
 921→                if !state.units.contains_key(&target_layer) {
 922→                    let unit = LayerUnit::new_empty();
 923→                    let _ = unit.layer().loro().get_map(target_layer.clone());
 924→                    unit.layer().commit();
 925→                    state.units.insert(target_layer.clone(), unit);
 926→                    info!(target = %target_layer, "Created empty derived layer");
 927→
 928→                    // Set up observer for the new layer
 929→                    loro_observer::setup_layer_observer(state, &target_layer);
 930→                }
 931→            }
 932→
 933→            ScribeMessage::GetAppFiles { app_name, reply } => {
 934→                // Use bare layer name (Scribe uses bare names, no page_id/ prefix)
 935→                let layer_name = format!("app:{}", app_name);
 936→                let result = if let Some(unit) = state.units.get(&layer_name) {
 937→                    Ok(unit.layer().get_all_files())
 938→                } else {
 939→                    Err(format!("App layer '{}' not found", layer_name))
 940→                };
 941→                let _ = reply.send(result);
 942→            }
 943→
 944→            ScribeMessage::GetSubscriberCount { reply } => {
 945→                let count = state.subscribers.read()
 946→                    .map(|s| s.len())
 947→                    .unwrap_or(0);
 948→                let _ = reply.send(count);
 949→            }
 950→
 951→            ScribeMessage::RefreshApp { app_name: _, app_dir: _, reply } => {
 952→                // RefreshApp requires filesystem access which is handled by butler's refresh service
 953→                // This stub returns an error - callers should use butler's refresh functionality instead
 954→                let _ = reply.send(Err("RefreshApp not supported in base Scribe - use butler's refresh service".to_string()));
 955→            }
 956→        }
 957→
 958→        Ok(())
 959→    }
 960→
 961→    #[instrument(skip_all, fields(page_id = %state.page_id))]
 962→    async fn post_stop(
 963→        &self,
 964→        _myself: ActorRef<Self::Msg>,
 965→        state: &mut Self::State,
 966→    ) -> std::result::Result<(), ActorProcessingErr> {
 967→        // Flush any dirty layers before stopping
 968→        let has_dirty = state.units.values().any(|u| u.is_dirty());
 969→        if has_dirty {
 970→            let dirty_count = state.units.values().filter(|u| u.is_dirty()).count();
 971→            info!(page_id = %state.page_id, dirty_count = dirty_count, "Flushing dirty layers on shutdown");
 972→            sync::handle_flush(state).await;
 973→        }
 974→
 975→        // Stop node script if running
 976→        if let Some(tx) = state.node_script_shutdown.take() {
 977→            info!(page_id = %state.page_id, "Stopping node script tick loop");
 978→            let _ = tx.send(()).await;
 979→        }
 980→
 981→        info!(page_id = %state.page_id, "Scribe stopped");
 982→        Ok(())
 983→    }
 984→}
