 986→// Helper Methods
 987→
 988→impl Scribe {
 989→    /// Handle JSON update from UI (CEL commit())
 990→    ///
 991→    /// **Broadcast**: Handled automatically by Loro observer after commit()
 992→    #[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
 993→    async fn handle_update_from_json(
 994→        &self,
 995→        state: &mut ScribeState,
 996→        layer_name: &str,
 997→        path: &str,
 998→        value: serde_json::Value,
 999→    ) -> Result<()> {
1000→        info!(layer = %layer_name, path = %path, "Updating layer from JSON");
1001→
1002→        // Get or create the layer unit
1003→        let unit = state
1004→            .units
1005→            .entry(layer_name.to_string())
1006→            .or_insert_with(LayerUnit::new_empty);
1007→
1008→        // Convert JSON to Loro and update
1009→        unit.layer()
1010→            .set_from_json(path, &value)
1011→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
1012→
1013→        // Commit to trigger Loro observer (which broadcasts to peers + notifies UI)
1014→        unit.layer().commit();
1015→
1016→        // Mark as dirty for persistence
1017→        unit.mark_dirty();
1018→
1019→        debug!("Layer update from JSON complete, observer will broadcast");
1020→        Ok(())
1021→    }
1022→}
