  1→//! Dynamic Layer Management
  2→//!
  3→//! Schema validation, path generation, and permit preparation for dynamic layers.
  4→//! Uses PermitIssuer trait — never touches signing keys directly.
  5→
  6→use tracing::{info, warn};
  7→
  8→use crate::state::ScribeState;
  9→use crate::loro_observer;
 10→
 11→use super::LayerUnit;
 12→
 13→/// Handle CreateDynamicLayer message
 14→///
 15→/// **Context**: Lua app calls scribe:create_layer("channels/{id}/messages", "general")
 16→/// **We do**: Validate schema exists in permit, generate full path with our DID, create layer
 17→/// **Returns**: Full layer name (bare, without page_id prefix)
 18→pub fn handle_create_dynamic_layer(
 19→    state: &mut ScribeState,
 20→    schema_key: &str,
 21→    layer_id: &str,
 22→) -> Result<String, String> {
 23→    let permit = state.our_permit.as_ref()
 24→        .ok_or_else(|| "No permit available".to_string())?;
 25→
 26→    // Validate schema exists in our permit's dynamic_layer_schemas
 27→    let schemas = permit.dynamic_layer_schemas();
 28→    let _schema = schemas
 29→        .get(schema_key)
 30→        .cloned()
 31→        .ok_or_else(|| format!("Schema '{}' not found in permit", schema_key))?;
 32→
 33→    // Generate full layer path with our DID
 34→    // Schema: "channels/{id}/messages" → Path: "channels/{our_did}/{layer_id}/messages"
 35→    let bare_path = generate_dynamic_path(schema_key, &state.our_did, layer_id);
 36→    let full_name = format!("{}/{}", state.page_id, bare_path);
 37→
 38→    // Check if layer already exists
 39→    if state.units.contains_key(&bare_path) {
 40→        info!(layer = %bare_path, "Dynamic layer already exists");
 41→        return Ok(full_name);
 42→    }
 43→
 44→    // Create the layer
 45→    info!(
 46→        page_id = %state.page_id,
 47→        schema = %schema_key,
 48→        layer = %bare_path,
 49→        "Creating dynamic layer"
 50→    );
 51→    let mut unit = LayerUnit::new_empty();
 52→    unit.set_local_only(!state.should_sync_layer(&bare_path));
 53→    unit.is_dynamic = true;
 54→    state.units.insert(bare_path.clone(), unit);
 55→
 56→    // Add all connected subscribers to the new layer
 57→    if let Ok(subs) = state.subscribers.read() {
 58→        for ((did, _), info) in subs.iter() {
 59→            if let Some(unit) = state.units.get(&bare_path) {
 60→                let caps = super::Capabilities { read: true, write: true, sync: true };
 61→                unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
 62→                state.emit_layer_auth_capture(&bare_path, did, "subscriber_added_on_create");
 63→            }
 64→        }
 65→    }
 66→
 67→    // Set up observer for the new layer
 68→    loro_observer::setup_layer_observer(state, &bare_path);
 69→
 70→    // Write entry to creator's __sync_meta for node discovery
 71→    {
 72→        use crate::sync::sync_meta;
 73→        let our_did = state.our_did.clone();
 74→        let meta_layer = sync_meta::sync_meta_layer_name(&our_did);
 75→        if state.units.contains_key(&meta_layer) {
 76→            sync_meta::write_sync_meta_entry(state, &our_did, &bare_path, false);
 77→            info!(layer = %bare_path, "Wrote dynamic layer entry to creator's __sync_meta");
 78→        }
 79→    }
 80→
 81→    Ok(full_name)
 82→}
 83→
 84→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
 85→///
 86→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
 87→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
 88→///
 89→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
 90→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
 91→    let parts: Vec<&str> = schema_key.split('/').collect();
 92→    let mut result = Vec::new();
 93→
 94→    if parts.is_empty() {
 95→        return format!("{}/{}", our_did, layer_id);
 96→    }
 97→
 98→    // First segment: literal
 99→    result.push(parts[0].to_string());
100→
101→    // Insert our DID as the second segment (namespace)
102→    result.push(our_did.to_string());
103→
104→    // Remaining segments: replace {id} with layer_id, keep literals
105→    for part in &parts[1..] {
106→        if *part == "{id}" {
107→            result.push(layer_id.to_string());
108→        } else {
109→            result.push(part.to_string());
110→        }
111→    }
112→
113→    result.join("/")
114→}
115→
116→/// Find matching dynamic schema for a layer received from a peer
117→///
118→/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
119→/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
120→pub fn find_matching_dynamic_schema<'a>(
121→    permit: &'a gurkha::Permit,
122→    layer_name: &str,
123→    page_id: &str,
124→) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
125→    let schemas = permit.dynamic_layer_schemas();
126→    if schemas.is_empty() {
127→        return None;
128→    }
129→
130→    // Strip page_id prefix to get bare layer path
131→    let page_prefix = format!("{}/", page_id);
132→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
133→
134→    let path_parts: Vec<&str> = bare_path.split('/').collect();
135→
136→    // Path must have at least 3 segments: prefix/did/id[/suffix]
137→    if path_parts.len() < 3 {
138→        return None;
139→    }
140→
141→    // Second segment should be a DID (the creator)
142→    let potential_creator = path_parts[1];
143→    if !potential_creator.starts_with("did:") {
144→        return None;
145→    }
146→
147→    // Try each schema pattern
148→    for (schema_key, schema) in schemas {
149→        let pattern_parts: Vec<&str> = schema_key.split('/').collect();
150→
151→        // Dynamic path has one extra segment (DID) compared to pattern
152→        if path_parts.len() != pattern_parts.len() + 1 {
153→            continue;
154→        }
155→
156→        // First segment must match literally
157→        if path_parts[0] != pattern_parts[0] {
158→            continue;
159→        }
160→
161→        // path[2..] must match pattern[1..] (with {id} as wildcard)
162→        let mut matched = true;
163→        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
164→            if *pat_seg != "{id}" && path_seg != pat_seg {
165→                matched = false;
166→                break;
167→            }
168→        }
169→
170→        if matched {
171→            return Some((schema_key, schema, potential_creator.to_string()));
172→        }
173→    }
174→
175→    None
176→}
177→
178→/// Handle AddLayerAccess message
179→///
180→/// **Context**: Lua app calls scribe:add_layer_access(layer_name, did)
181→/// **We do**: Validate capability, issue authority permit (intent), write to target's __sync_meta.
182→/// **Flow**: Node stores authority permit → writes to target's __sync_meta →
183→///   target discovers entry → sends LayerSubscribe → node issues access permit + data.
184→pub fn handle_add_layer_access(
185→    state: &mut ScribeState,
186→    layer_name: &str,
187→    did: &str,
188→) -> Result<(), String> {
189→    // 1. Check our permit has manage_layer_access capability
190→    let permit = state.our_permit.as_ref().ok_or_else(|| {
191→        warn!(page_id = %state.page_id, layer = %layer_name, audience = %did, "AddLayerAccess rejected: missing our_permit");
192→        "No permit".to_string()
193→    })?;
194→    if !permit.can_manage_layer_access() {
195→        warn!(
196→            page_id = %state.page_id,
197→            layer = %layer_name,
198→            audience = %did,
199→            "AddLayerAccess rejected: missing manage_layer_access capability"
200→        );
201→        return Err("No manage_layer_access capability".into());
202→    }
203→
204→    // 2. Validate schema match + explicit grant
205→    let (_schema_key, schema, _creator) = find_matching_dynamic_schema(permit, layer_name, &state.page_id)
206→        .ok_or_else(|| {
207→            warn!(
208→                page_id = %state.page_id,
209→                layer = %layer_name,
210→                audience = %did,
211→                "AddLayerAccess rejected: layer does not match dynamic schema"
212→            );
213→            "Layer does not match any dynamic schema".to_string()
214→        })?;
215→    if schema.grant != gurkha::GrantType::Explicit {
216→        warn!(
217→            page_id = %state.page_id,
218→            layer = %layer_name,
219→            audience = %did,
220→            "AddLayerAccess rejected: schema grant is not explicit"
221→        );
222→        return Err("AddLayerAccess only applies to explicit dynamic schemas".into());
223→    }
224→
225→    // 3. Issue authority permit (intent) — stored by PermitIssuer for later retrieval
226→    let issuer = state.permit_issuer.as_ref().ok_or_else(|| {
227→        warn!(
228→            page_id = %state.page_id,
229→            layer = %layer_name,
230→            audience = %did,
231→            "AddLayerAccess rejected: no permit issuer"
232→        );
233→        "No permit issuer".to_string()
234→    })?;
235→    let config = schema.permissions.clone();
236→    issuer.issue_layer_authority_permit(did, layer_name, config, None, 1)
237→        .map_err(|e| format!("Failed to issue authority permit: {}", e))?;
238→
239→    info!(
240→        page_id = %state.page_id,
241→        layer = %layer_name,
242→        audience = %did,
243→        "Stored authority intent for explicit layer access"
244→    );
245→
246→    // 4. Write entry to target's __sync_meta (if it exists)
247→    let bare_name = crate::state::normalize_layer_name(layer_name, &state.page_id);
248→    {
249→        use crate::sync::sync_meta;
250→        let meta_layer = sync_meta::sync_meta_layer_name(did);
251→        if state.units.contains_key(&meta_layer) {
252→            sync_meta::write_sync_meta_entry(state, did, &bare_name, false);
253→            info!(
254→                layer = %bare_name,
255→                audience = %did,
256→                "Wrote explicit-grant entry to target's __sync_meta"
257→            );
258→        }
259→    }
260→
261→    Ok(())
262→}
263→
264→/// Handle RemoveLayerAccess message
265→///
266→/// **Context**: Lua app calls scribe:remove_layer_access(layer_name, did)
267→/// **We do**: Validate capability, reject metadata-era revoke path
268→pub fn handle_remove_layer_access(
269→    state: &ScribeState,
270→    layer_name: &str,
271→    did: &str,
272→) -> Result<(), String> {
273→    let permit = state.our_permit.as_ref().ok_or("No permit")?;
274→    if !permit.can_manage_layer_access() {
275→        return Err("No manage_layer_access capability".into());
276→    }
277→
278→    let _ = layer_name;
279→    let _ = did;
280→    Err("RemoveLayerAccess is deprecated; rotate/revoke layer authority permits instead".to_string())
281→}
