  1→//! Base control server implementation
  2→//!
  3→//! Provides a Unix socket server that handles JSON-RPC style requests.
  4→//! Implementors provide a CommandHandler to process application-specific commands.
  5→
  6→use std::path::PathBuf;
  7→use std::sync::Arc;
  8→
  9→use async_trait::async_trait;
 10→use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
 11→use tokio::net::{UnixListener, UnixStream};
 12→use tracing::{debug, error, info, warn};
 13→
 14→use crate::types::{Request, Response, error_codes};
 15→
 16→/// Trait for handling commands
 17→///
 18→/// Implement this trait to add application-specific commands to the control server.
 19→#[async_trait]
 20→pub trait CommandHandler: Send + Sync {
 21→    /// Handle a command request
 22→    ///
 23→    /// Returns Some(Response) if the command was handled, None if not recognized.
 24→    /// The base server handles common commands (ping) automatically.
 25→    async fn handle(&self, method: &str, params: Option<serde_json::Value>, id: u64) -> Option<Response>;
 26→
 27→    /// Get the connection string for this instance (if applicable)
 28→    async fn get_connection_string(&self) -> Option<String> {
 29→        None
 30→    }
 31→}
 32→
 33→/// Base control server
 34→pub struct ControlServer<H: CommandHandler> {
 35→    socket_path: PathBuf,
 36→    instance_name: String,
 37→    handler: Arc<H>,
 38→}
 39→
 40→impl<H: CommandHandler + 'static> ControlServer<H> {
 41→    /// Create a new control server
 42→    pub fn new(socket_path: PathBuf, instance_name: String, handler: H) -> Self {
 43→        Self {
 44→            socket_path,
 45→            instance_name,
 46→            handler: Arc::new(handler),
 47→        }
 48→    }
 49→
 50→    /// Get the socket path
 51→    pub fn socket_path(&self) -> &PathBuf {
 52→        &self.socket_path
 53→    }
 54→
 55→    /// Start the control server
 56→    ///
 57→    /// This runs the server loop, accepting connections and handling requests.
 58→    pub async fn start(&self) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
 59→        // Remove existing socket file
 60→        let _ = std::fs::remove_file(&self.socket_path);
 61→
 62→        // Ensure parent directory exists
 63→        if let Some(parent) = self.socket_path.parent() {
 64→            std::fs::create_dir_all(parent)?;
 65→        }
 66→
 67→        let listener = UnixListener::bind(&self.socket_path)?;
 68→        info!(
 69→            socket = %self.socket_path.display(),
 70→            instance = %self.instance_name,
 71→            "Control server listening"
 72→        );
 73→
 74→        loop {
 75→            match listener.accept().await {
 76→                Ok((stream, _)) => {
 77→                    let handler = self.handler.clone();
 78→                    let instance_name = self.instance_name.clone();
 79→
 80→                    tokio::spawn(async move {
 81→                        if let Err(e) = handle_connection(
 82→                            stream,
 83→                            handler,
 84→                            instance_name,
 85→                        ).await {
 86→                            debug!(error = %e, "Connection handler error");
 87→                        }
 88→                    });
 89→                }
 90→                Err(e) => {
 91→                    error!(error = %e, "Failed to accept connection");
 92→                }
 93→            }
 94→        }
 95→    }
 96→}
 97→
 98→/// Handle a single client connection
 99→async fn handle_connection<H: CommandHandler>(
100→    stream: UnixStream,
101→    handler: Arc<H>,
102→    instance_name: String,
103→) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
104→    let (reader, mut writer) = stream.into_split();
105→    let mut reader = BufReader::new(reader);
106→    let mut line = String::new();
107→
108→    while reader.read_line(&mut line).await? > 0 {
109→        let trimmed = line.trim();
110→        if trimmed.is_empty() {
111→            line.clear();
112→            continue;
113→        }
114→
115→        debug!(request = %trimmed, "Received request");
116→
117→        // Parse request
118→        let response = match serde_json::from_str::<Request>(trimmed) {
119→            Ok(request) => {
120→                process_request(
121→                    &request,
122→                    &handler,
123→                    &instance_name,
124→                ).await
125→            }
126→            Err(e) => {
127→                warn!(error = %e, "Failed to parse request");
128→                Response::err(0, error_codes::PARSE_ERROR, format!("Parse error: {}", e))
129→            }
130→        };
131→
132→        // Send response
133→        let response_json = serde_json::to_string(&response)?;
134→        debug!(response = %response_json, "Sending response");
135→        writer.write_all(response_json.as_bytes()).await?;
136→        writer.write_all(b"\n").await?;
137→        writer.flush().await?;
138→
139→        line.clear();
140→    }
141→
142→    Ok(())
143→}
144→
145→/// Process a parsed request
146→async fn process_request<H: CommandHandler>(
147→    request: &Request,
148→    handler: &Arc<H>,
149→    instance_name: &str,
150→) -> Response {
151→    let id = request.id;
152→    let method = request.method.as_str();
153→
154→    // Handle common commands first
155→    match method {
156→        "ping" => {
157→            return Response::ok(id, serde_json::json!({
158→                "status": "ok",
159→                "instance": instance_name
160→            }));
161→        }
162→        "get_connection_string" => {
163→            if let Some(conn_str) = handler.get_connection_string().await {
164→                return Response::ok(id, serde_json::json!({"connection_string": conn_str}));
165→            } else {
166→                return Response::err(id, error_codes::NOT_FOUND, "Connection string not available");
167→            }
168→        }
169→        _ => {}
170→    }
171→
172→    // Try application-specific handler
173→    if let Some(response) = handler.handle(method, request.params.clone(), id).await {
174→        return response;
175→    }
176→
177→    // Method not found
178→    Response::err(id, error_codes::METHOD_NOT_FOUND, format!("Unknown method: {}", method))
179→}
180→

 1→//! Common types for control server protocol
 2→
 3→use serde::{Deserialize, Serialize};
 4→
 5→/// JSON-RPC style request
 6→#[derive(Debug, Clone, Deserialize)]
 7→pub struct Request {
 8→    /// Method name (e.g., "ping", "eval", "login")
 9→    pub method: String,
10→    /// Optional parameters
11→    #[serde(default)]
12→    pub params: Option<serde_json::Value>,
13→    /// Request ID for correlation
14→    pub id: u64,
15→}
16→
17→/// JSON-RPC style response
18→#[derive(Debug, Clone, Serialize)]
19→pub struct Response {
20→    /// Result on success
21→    #[serde(skip_serializing_if = "Option::is_none")]
22→    pub result: Option<serde_json::Value>,
23→    /// Error on failure
24→    #[serde(skip_serializing_if = "Option::is_none")]
25→    pub error: Option<ErrorResponse>,
26→    /// Request ID for correlation
27→    pub id: u64,
28→}
29→
30→impl Response {
31→    /// Create a success response
32→    pub fn ok<T: Serialize>(id: u64, result: T) -> Self {
33→        Self {
34→            result: Some(serde_json::to_value(result).unwrap_or(serde_json::Value::Null)),
35→            error: None,
36→            id,
37→        }
38→    }
39→
40→    /// Create an error response
41→    pub fn err(id: u64, code: i32, message: impl Into<String>) -> Self {
42→        Self {
43→            result: None,
44→            error: Some(ErrorResponse {
45→                code,
46→                message: message.into(),
47→            }),
48→            id,
49→        }
50→    }
51→
52→    /// Create a simple success response with status: "ok"
53→    pub fn ok_status(id: u64) -> Self {
54→        Self::ok(id, serde_json::json!({"status": "ok"}))
55→    }
56→}
57→
58→/// Error response structure
59→#[derive(Debug, Clone, Serialize)]
60→pub struct ErrorResponse {
61→    /// Error code
62→    pub code: i32,
63→    /// Error message
64→    pub message: String,
65→}
66→
67→/// Common error codes
68→pub mod error_codes {
69→    pub const PARSE_ERROR: i32 = -32700;
70→    pub const INVALID_REQUEST: i32 = -32600;
71→    pub const METHOD_NOT_FOUND: i32 = -32601;
72→    pub const INVALID_PARAMS: i32 = -32602;
73→    pub const INTERNAL_ERROR: i32 = -32603;
74→
75→    // Application-specific errors (-32000 to -32099)
76→    pub const NOT_AUTHENTICATED: i32 = -32001;
77→    pub const NOT_FOUND: i32 = -32002;
78→    pub const PERMISSION_DENIED: i32 = -32003;
79→    pub const OPERATION_FAILED: i32 = -32004;
80→}
