 36→/// Kunki-specific command handler
 37→pub struct KunkiHandler {
 38→    state: Arc<RwLock<Option<NodeState>>>,
 39→    butler: Option<Arc<Butler>>,
 40→    validation_handle: Arc<RwLock<Option<ValidationHandle>>>,
 41→    capture_handle: Arc<RwLock<Option<CaptureHandle>>>,
 42→}
 43→
 44→impl KunkiHandler {
 45→    pub fn new(butler: Option<Arc<Butler>>) -> Self {
 46→        Self {
 47→            state: Arc::new(RwLock::new(None)),
 48→            butler,
 49→            validation_handle: Arc::new(RwLock::new(None)),
 50→            capture_handle: Arc::new(RwLock::new(None)),
 51→        }
 52→    }
 53→
 54→    /// Set capture handle (for event capture)
 55→    pub async fn set_capture_handle(&self, handle: CaptureHandle) {
 56→        *self.capture_handle.write().await = Some(handle);
 57→    }
 58→
 59→    /// Handle capture_start command
 60→    async fn handle_capture_start(&self, params: Option<serde_json::Value>, id: u64) -> Response {
 61→        let handle_guard = self.capture_handle.read().await;
 62→        let Some(ref handle) = *handle_guard else {
 63→            return Response::err(id, error_codes::INTERNAL_ERROR, "CaptureHandle not available");
 64→        };
 65→
 66→        let Some(params_obj) = params.as_ref().and_then(|p| p.as_object()) else {
 67→            return Response::err(id, error_codes::INVALID_PARAMS, "Invalid params object");
 68→        };
 69→
 70→        let Some(file_path) = params_obj.get("file_path").and_then(|v| v.as_str()) else {
 71→            return Response::err(id, error_codes::INVALID_PARAMS, "Missing file_path");
 72→        };
 73→
 74→        let include_logs = params_obj.get("include_logs").and_then(|v| v.as_bool()).unwrap_or(false);
 75→
 76→        match handle.start_capture(PathBuf::from(file_path), include_logs).await {
 77→            Ok(()) => Response::ok(id, serde_json::json!({"status": "capturing", "file_path": file_path})),
 78→            Err(e) => Response::err(id, error_codes::INTERNAL_ERROR, &e),
 79→        }
 80→    }
 81→
 82→    /// Handle capture_end command
 83→    async fn handle_capture_end(&self, id: u64) -> Response {
 84→        let handle_guard = self.capture_handle.read().await;
 85→        let Some(ref handle) = *handle_guard else {
 86→            return Response::err(id, error_codes::INTERNAL_ERROR, "CaptureHandle not available");
 87→        };
 88→
 89→        match handle.stop_capture().await {
 90→            Ok(()) => Response::ok(id, serde_json::json!({"status": "stopped"})),
 91→            Err(e) => Response::err(id, error_codes::INTERNAL_ERROR, &e),
 92→        }
 93→    }
 94→
 95→    /// Set validation handle (for testing validation RPC)
 96→    pub async fn set_validation_handle(&self, handle: ValidationHandle) {
 97→        *self.validation_handle.write().await = Some(handle);
 98→    }
 99→
100→    /// Update node state
101→    pub async fn set_state(&self, state: NodeState) {
102→        *self.state.write().await = Some(state);
103→    }
104→
105→    /// Get the state reference for external updates
106→    pub fn state(&self) -> Arc<RwLock<Option<NodeState>>> {
107→        self.state.clone()
108→    }
109→
110→    async fn handle_state(&self, id: u64) -> Response {
111→        let state_guard = self.state.read().await;
112→        match &*state_guard {
113→            Some(s) => Response::ok(id, s),
114→            None => Response::ok(id, serde_json::json!({"status": "not_initialized"})),
115→        }
116→    }
117→
118→    /// Handle validate_ops command (for testing validation RPC)
119→    ///
120→    /// **Params**: page_id, layer_name, ops (array of JsonOp), from_did, role
121→    /// **Returns**: {passed: bool, error?: string}
122→    async fn handle_validate_ops(&self, params: Option<serde_json::Value>, id: u64) -> Response {
123→        let handle_guard = self.validation_handle.read().await;
124→        let Some(ref handle) = *handle_guard else {
125→            return Response::err(id, error_codes::INTERNAL_ERROR, "ValidationHandle not available");
126→        };
127→
128→        // Extract parameters
129→        let Some(params_obj) = params.as_ref().and_then(|p| p.as_object()) else {
130→            return Response::err(id, error_codes::INVALID_PARAMS, "Invalid params object");
131→        };
132→
133→        let Some(page_id) = params_obj.get("page_id").and_then(|v| v.as_str()) else {
134→            return Response::err(id, error_codes::INVALID_PARAMS, "Missing page_id");
135→        };
136→
137→        let Some(layer_name) = params_obj.get("layer_name").and_then(|v| v.as_str()) else {
138→            return Response::err(id, error_codes::INVALID_PARAMS, "Missing layer_name");
139→        };
140→
141→        let Some(from_did) = params_obj.get("from_did").and_then(|v| v.as_str()) else {
142→            return Response::err(id, error_codes::INVALID_PARAMS, "Missing from_did");
143→        };
144→
145→        let Some(role) = params_obj.get("role").and_then(|v| v.as_str()) else {
146→            return Response::err(id, error_codes::INVALID_PARAMS, "Missing role");
147→        };
148→
149→        let Some(ops_array) = params_obj.get("ops").and_then(|v| v.as_array()) else {
150→            return Response::err(id, error_codes::INVALID_PARAMS, "Missing ops array");
151→        };
152→
153→        // Parse ops
154→        let ops: Vec<JsonOp> = match ops_array.iter().map(|v| serde_json::from_value(v.clone())).collect() {
155→            Ok(ops) => ops,
156→            Err(e) => return Response::err(id, error_codes::INVALID_PARAMS, &format!("Failed to parse ops: {}", e)),
157→        };
158→
159→        // Call validation
160→        match handle.validate_ops(page_id, layer_name, &ops, from_did, role).await {
161→            Ok((passed, error_msg)) => {
162→                let result = if passed {
163→                    serde_json::json!({
164→                        "passed": true
165→                    })
166→                } else {
167→                    serde_json::json!({
168→                        "passed": false,
169→                        "error": error_msg.unwrap_or_else(|| "Validation failed".to_string())
170→                    })
171→                };
172→                Response::ok(id, result)
173→            }
174→            Err(e) => Response::err(id, error_codes::INTERNAL_ERROR, &format!("Validation error: {}", e)),
175→        }
176→    }
177→}
