179→#[async_trait]
180→impl CommandHandler for KunkiHandler {
181→    async fn handle(&self, method: &str, params: Option<serde_json::Value>, id: u64) -> Option<Response> {
182→        match method {
183→            "state" => Some(self.handle_state(id).await),
184→
185→            "validate_ops" => Some(self.handle_validate_ops(params, id).await),
186→
187→            "capture_start" => Some(self.handle_capture_start(params, id).await),
188→            "capture_end" => Some(self.handle_capture_end(id).await),
189→
190→            // Butler commands - delegate to shared implementations
191→            "list_spaces" => {
192→                if let Some(ref butler) = self.butler {
193→                    Some(butler_cmds::list_spaces(butler, id).await)
194→                } else {
195→                    Some(Response::err(id, error_codes::NOT_AUTHENTICATED, "Butler not available"))
196→                }
197→            }
198→
199→            "list_pages" => {
200→                let space_id = butler_cmds::get_string_param(&params, "space_id");
201→                match (self.butler.as_ref(), space_id) {
202→                    (Some(butler), Some(sid)) => Some(butler_cmds::list_pages(butler, &sid, id).await),
203→                    (None, _) => Some(Response::err(id, error_codes::NOT_AUTHENTICATED, "Butler not available")),
204→                    (_, None) => Some(Response::err(id, error_codes::INVALID_PARAMS, "Missing space_id parameter")),
205→                }
206→            }
207→
208→            "list_layers" => {
209→                let page_id = butler_cmds::get_string_param(&params, "page_id");
210→                match (self.butler.as_ref(), page_id) {
211→                    (Some(butler), Some(pid)) => Some(butler_cmds::list_layers(butler, &pid, id).await),
212→                    (None, _) => Some(Response::err(id, error_codes::NOT_AUTHENTICATED, "Butler not available")),
213→                    (_, None) => Some(Response::err(id, error_codes::INVALID_PARAMS, "Missing page_id parameter")),
214→                }
215→            }
216→
217→            _ => None, // Let base server handle or return method not found
218→        }
219→    }
220→
221→    async fn get_connection_string(&self) -> Option<String> {
222→        let state_guard = self.state.read().await;
223→        state_guard.as_ref().and_then(|s| s.connection_string.clone())
224→    }
225→}
