132→#[async_trait]
133→impl CommandHandler for ShellHandler {
134→    async fn handle(&self, method: &str, params: Option<serde_json::Value>, id: u64) -> Option<Response> {
135→        match method {
136→            // Lua Eval
137→            "eval" => {
138→                let code = get_param(&params, "code")?;
139→                let eval_tx = self.eval_tx.read().await;
140→                let Some(tx) = eval_tx.as_ref() else {
141→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Lua eval not available - no app is open"));
142→                };
143→                let (response_tx, response_rx) = oneshot::channel();
144→                if tx.send(DebugEvalRequest { code, response_tx }).await.is_err() {
145→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Failed to send eval request"));
146→                }
147→                match response_rx.await {
148→                    Ok(Ok(value)) => Some(Response::ok(id, value)),
149→                    Ok(Err(e)) => Some(Response::err(id, error_codes::OPERATION_FAILED, e)),
150→                    Err(_) => Some(Response::err(id, error_codes::INTERNAL_ERROR, "Eval request dropped")),
151→                }
152→            }
153→
154→            // Butler Commands (shared)
155→            "list_spaces" => {
156→                let butler = self.butler.read().await;
157→                match butler.as_ref() {
158→                    Some(b) => Some(butler_cmds::list_spaces(b, id).await),
159→                    None => Some(Response::err(id, error_codes::NOT_AUTHENTICATED, "Butler not available")),
160→                }
161→            }
162→
163→            "list_pages" => {
164→                let space_id = get_param(&params, "space_id")?;
165→                let butler = self.butler.read().await;
166→                match butler.as_ref() {
167→                    Some(b) => Some(butler_cmds::list_pages(b, &space_id, id).await),
