  8→// ID Shortening Utilities
  9→
 10→/// Wrapper for shortening long IDs in logs
 11→///
 12→/// Turns `00c02ee56d990e0a0a1ce0f12f963df121efb6efc51096ae324f5b9bf4bfa4c9`
 13→/// into `00c02e..a4c9` for cleaner log output.
 14→///
 15→/// # Example
 16→/// ```rust
 17→/// use tracing::info;
 18→/// use logging_utils::Short;
 19→///
 20→/// let node_id = "00c02ee56d990e0a0a1ce0f12f963df121efb6efc51096ae324f5b9bf4bfa4c9";
 21→/// info!(node = %Short(node_id), "Connected");
 22→/// // Output: node=00c02e..a4c9 Connected
 23→/// ```
 24→pub struct Short<'a>(pub &'a str);
 25→
 26→impl Display for Short<'_> {
 27→    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
 28→        let s = self.0;
 29→        if s.len() > 16 {
 30→            // Show first 6 and last 4 characters
 31→            write!(f, "{}..{}", &s[..6], &s[s.len()-4..])
 32→        } else {
 33→            write!(f, "{}", s)
 34→        }
 35→    }
 36→}
