 38→/// Shorten a DID for logging
 39→///
 40→/// Turns `did:key:REDACTED`
 41→/// into `did:..vwU` for cleaner log output.
 42→///
 43→/// # Example
 44→/// ```rust
 45→/// use tracing::info;
 46→/// use logging_utils::ShortDid;
 47→///
 48→/// let did = "did:key:REDACTED";
 49→/// info!(peer = %ShortDid(did), "Peer connected");
 50→/// // Output: peer=did:..vwU Peer connected
 51→/// ```
 52→pub struct ShortDid<'a>(pub &'a str);
 53→
 54→impl Display for ShortDid<'_> {
 55→    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
 56→        let s = self.0;
 57→        if s.starts_with("did:") && s.len() > 12 {
 58→            // Show "did:.." + last 4 characters
 59→            write!(f, "did:..{}", &s[s.len()-4..])
 60→        } else if s.len() > 16 {
 61→            write!(f, "{}..{}", &s[..6], &s[s.len()-4..])
 62→        } else {
 63→            write!(f, "{}", s)
 64→        }
 65→    }
 66→}
