 68→/// Shorten a layer name for logging
 69→///
 70→/// Turns `abc123/orders/did:key:REDACTED`
 71→/// into `abc123/orders/did:..vwU` for cleaner log output.
 72→pub struct ShortLayer<'a>(pub &'a str);
 73→
 74→impl Display for ShortLayer<'_> {
 75→    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
 76→        let s = self.0;
 77→        // If layer contains a DID segment, shorten it
 78→        if let Some(did_pos) = s.find("did:") {
 79→            let prefix = &s[..did_pos];
 80→            let did_part = &s[did_pos..];
 81→            if did_part.len() > 12 {
 82→                write!(f, "{}did:..{}", prefix, &did_part[did_part.len()-4..])
 83→            } else {
 84→                write!(f, "{}", s)
 85→            }
 86→        } else if s.len() > 24 {
 87→            // Just truncate long layer names
 88→            write!(f, "{}..{}", &s[..12], &s[s.len()-8..])
 89→        } else {
 90→            write!(f, "{}", s)
 91→        }
 92→    }
 93→}
