451→/// Initialize rich tracing with tree formatting
452→///
453→/// This sets up a hierarchical logging system with optional file output.
454→/// The tree format shows nested function calls with indentation, making it
455→/// easy to trace execution flow through async code and multiple services.
456→///
457→/// When `debug_tx` is provided in config, all logs are also sent to that
458→/// broadcast channel for external consumers (like ai_interface).
459→///
460→/// # Example Output
461→/// ```text
462→/// 🎯 handle_add_folder name="My Folder"
463→///   ├─📁 create_folder folder_id="f_abc123"
464→///   │ ├─🔐 issue_folder_owner_token
465→///   │ │ └─✓ 8.7ms
466→///   │ └─✓ 45.6ms
467→///   └─✓ 50.1ms
468→/// ```
469→pub fn init_rich_tracing(
470→    config: LogConfig,
471→) -> Result<Option<WorkerGuard>, Box<dyn std::error::Error>> {
472→    let mut guard = None;
473→
474→    // Create filter: use RUST_LOG level if set, otherwise config.level,
475→    // but ALWAYS apply our third-party noise suppressions
476→    let base_level = std::env::var("RUST_LOG").unwrap_or_else(|_| config.level.clone());
477→    let filter = EnvFilter::try_new(format!(
478→        "{},\
479→         hyper=warn,\
480→         hyper_util=warn,\
481→         rustls=error,\
482→         iroh=warn,\
483→         iroh::socket=off,\
484→         iroh::net_report=off,\
485→         iroh::net_report::report=off,\
486→         quinn=warn,\
487→         netlink_proto=error,\
488→         netlink_sys=error,\
489→         netlink_packet_route=off,\
490→         hickory_proto=error,\
491→         hickory_resolver=error,\
492→         hickory_client=error,\
493→         portmapper=off,\
494→         tokio_tungstenite=warn,\
495→         tungstenite=warn,\
496→         netwatch=warn,\
497→         iroh_quinn_proto::connection=warn,\
498→         iroh_relay=warn,\
499→         igd_next::aio::tokio=warn,\
500→         tantivy=warn,\
501→         reqwest=warn,\
502→         asset_protocol=warn,\
503→         loro_internal=off,\
504→         loro_internal::oplog=off,\
505→         loro_internal::oplog::change_store=off,\
506→         loro_internal::oplog::change_store::block_encode=off,\
507→         loro_kv_store=off,\
508→         wgpu_core=warn,\
509→         wgpu_hal=off,\
510→         wgpu_hal::gles=off,\
511→         winit=warn,\
512→         naga=warn",
513→        base_level
514→    ))?;
515→
516→    // Create optional debug capture layer (sends logs to broadcast channel)
517→    let debug_layer = config.debug_tx.map(|tx| {
518→        DebugCaptureLayer::new(tx, config.instance_name.clone())
519→    });
520→
521→    let registry = tracing_subscriber::registry().with(filter).with(debug_layer);
522→
