    if isinstance(value, str):
        try:
            return float(value)
        except ValueError:
            # Try ISO8601 format
            iso_value = value
            if iso_value.endswith("Z"):
                iso_value = iso_value[:-1] + "+00:00"
            return datetime.fromisoformat(iso_value).timestamp()
    return None
