///
/// **Context**: Node processed our LayerSubscribe, sent data + permit
/// **We do**: Decrypt data, store permit, apply to Scribe, authorize node, mark synced
pub(in crate::peer_actor) async fn on_layer_subscribe_ack(
    &self,
    _request_id: &str,
    page_id: &str,
    layer_name: &str,
    accepted: bool,
    reason: Option<&str>,
    data: &[u8],
    _state_vector: &[u8],
    ephemeral_public: &[u8; 32],
    layer_permit: &str,
    state: &mut PeerActorState<C>,
) {
    if !accepted {
        warn!(
            "LayerSubscribeAck rejected for page={} layer={}: {}",
            page_id, layer_name, reason.unwrap_or("unknown")
        );
        return;
    }

    info!(
        "LayerSubscribeAck: page={} layer={} from node={} data_len={}",
        page_id, layer_name, node_did, data.len()
    );

    // 1. Decrypt data
    let our_secret = match state.butler.encryption_key().await {
        Ok(key) => key,
        Err(e) => {
            error!("Failed to get encryption key for LayerSubscribeAck: {}", e);
            return;
        }
    };

    let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
        Ok(plaintext) => plaintext,
        Err(e) => {
            error!("Failed to decrypt LayerSubscribeAck data: {}", e);
            return;
        }
    };

