/// Handle AddLayerAccess message
///
/// **Context**: Lua app calls scribe:add_layer_access(layer_name, did)
/// **We do**: Validate capability, issue authority permit (intent), write to target's __sync_meta.
/// **Flow**: Node stores authority permit → writes to target's __sync_meta →
///   target discovers entry → sends LayerSubscribe → node issues access permit + data.
pub fn handle_add_layer_access(
    state: &mut ScribeState,
    layer_name: &str,
    did: &str,
) -> Result<(), String> {
    // 1. Check our permit has manage_layer_access capability
    let permit = state.our_permit.as_ref().ok_or_else(|| {
        warn!(page_id = %state.page_id, layer = %layer_name, audience = %did, "AddLayerAccess rejected: missing our_permit");
        "No permit".to_string()
    })?;
    if !permit.can_manage_layer_access() {
        warn!(
            page_id = %state.page_id,
            layer = %layer_name,
            audience = %did,
            "AddLayerAccess rejected: missing manage_layer_access capability"
        );
        return Err("No manage_layer_access capability".into());
    }

    // 2. Validate schema match + explicit grant
    let (_schema_key, schema, _creator) = find_matching_dynamic_schema(permit, layer_name, &state.page_id)
        .ok_or_else(|| {
            warn!(
                page_id = %state.page_id,
                layer = %layer_name,
                audience = %did,
                "AddLayerAccess rejected: layer does not match dynamic schema"
            );
            "Layer does not match any dynamic schema".to_string()
        })?;
    if schema.grant != gurkha::GrantType::Explicit {
        warn!(
            page_id = %state.page_id,
            layer = %layer_name,
            audience = %did,
            "AddLayerAccess rejected: schema grant is not explicit"
        );
        return Err("AddLayerAccess only applies to explicit dynamic schemas".into());
    }

    // 3. Issue authority permit (intent) — stored by PermitIssuer for later retrieval
    let issuer = state.permit_issuer.as_ref().ok_or_else(|| {
        warn!(
            page_id = %state.page_id,
            layer = %layer_name,
            audience = %did,
            "AddLayerAccess rejected: no permit issuer"
        );
        "No permit issuer".to_string()
    })?;
    let config = schema.permissions.clone();
    issuer.issue_layer_authority_permit(did, layer_name, config, None, 1)
        .map_err(|e| format!("Failed to issue authority permit: {}", e))?;

    info!(
        page_id = %state.page_id,
        layer = %layer_name,
        audience = %did,
        "Stored authority intent for explicit layer access"
    );

    // 4. Write entry to target's __sync_meta (if it exists)
    let bare_name = crate::state::normalize_layer_name(layer_name, &state.page_id);
    {
        use crate::sync::sync_meta;
        let meta_layer = sync_meta::sync_meta_layer_name(did);
        if state.units.contains_key(&meta_layer) {
            sync_meta::write_sync_meta_entry(state, did, &bare_name, false);
            info!(
                layer = %bare_name,
                audience = %did,
                "Wrote explicit-grant entry to target's __sync_meta"
            );
        }
    }

    Ok(())
}
