 48→    node_public_key: &str,
 49→    node_encryption_key: &[u8; 32],
 50→    owner_signing_key: &[u8; 32],
 51→    owner_secret_key: &[u8; 32],
 52→) -> Result<PreparedPage> {
 53→    // 1. Find the page
 54→    let page_data = store.find_page_by_id(page_id)?
 55→        .ok_or_else(|| ButlerError::page_not_found(page_id))?;
 56→
 57→    // 2. Get owner's permit from the page (MY permit) - clone to avoid borrow issues
 58→    let owner_permit = page_data.get_permit()
 59→        .ok_or_else(|| ButlerError::permit_not_found(
 60→            &format!("Owner permit not found for page {}", page_id)
 61→        ))?
 62→        .clone();
 63→
 64→    // 3. Parse permit to get local_only layers (for filtering)
 65→    let permit = gurkha::Permit::from_token(&owner_permit)
 66→        .map_err(|e| ButlerError::permit_error(format!("Failed to parse permit: {:?}", e)))?;
 67→    let local_only_layers: Vec<String> = permit.local_only_layers();
 68→
 69→    // 4. Issue page permit for node via gurkha
 70→    let (node_permit, _cid) = gurkha::delegate_page(
 71→        owner_signing_key,
 72→        &owner_permit,
 73→        "node",  // template_key from PAGE_TEMPLATE.delegation.node
 74→        node_public_key,
 75→    ).await.map_err(|e| ButlerError::permit_error(format!("Failed to issue page permit: {}", e)))?;
 76→
 77→    // 5. Decrypt AES key using owner's secret key
 78→    let aes_key = herald::decrypt(owner_secret_key, &page_data.meta.encrypted_key)
 79→        .map_err(|e| ButlerError::Encryption(format!("Failed to decrypt AES key: {}", e)))?;
 80→
 81→    let aes_key_arr: [u8; 32] = aes_key.try_into()
 82→        .map_err(|_| ButlerError::Encryption("Invalid AES key length".to_string()))?;
 83→
 84→    // 6. Get and decrypt all layers, filtering out local_only
 85→    let encrypted_layers = store.get_all_layers(page_id)?;
 86→    let mut decrypted_layers = Vec::new();
 87→
 88→    for (layer_name, encrypted_bytes) in encrypted_layers {
 89→        // Skip local_only layers (e.g., user_content_doc)
 90→        if local_only_layers.iter().any(|l| l == &layer_name) {
 91→            // Skip local_only layers (e.g., user_content_doc) - not synced to node
 92→            continue;
 93→        }
 94→
 95→        let decrypted_bytes = herald::decrypt_symmetric(&aes_key_arr, &encrypted_bytes)
 96→            .map_err(|e| ButlerError::Encryption(
 97→                format!("Failed to decrypt layer {}: {}", layer_name, e)
 98→            ))?;
 99→        decrypted_layers.push((layer_name, decrypted_bytes));
100→    }
101→
102→    // 7. Generate ephemeral keypair and encrypt layers for transit
103→    let (ephemeral_secret, ephemeral_public) = herald::generate_ephemeral_keypair();
104→
105→    // Derive transit key from ECDH
106→    let shared_secret = herald::ecdh(&ephemeral_secret, node_encryption_key);
107→    let transit_key = herald::derive_key(&shared_secret, None, b"herald-transit-v1");
108→
109→    // Encrypt each layer with transit key
110→    let mut transit_layers = Vec::with_capacity(decrypted_layers.len());
111→    for (layer_name, plaintext) in decrypted_layers {
112→        let encrypted = herald::encrypt_symmetric(&transit_key, &plaintext)
113→            .map_err(|e| ButlerError::Encryption(
114→                format!("Failed to transit-encrypt layer {}: {}", layer_name, e)
115→            ))?;
116→        transit_layers.push((layer_name, encrypted));
117→    }
118→
119→    Ok(PreparedPage {
120→        meta: page_data.meta,
121→        permit: node_permit,
122→        owner_permit,
123→        ephemeral_public,
124→        layers: transit_layers,
125→    })
126→}
