128→/// Store a page received via publish (Node mode)
129→///
130→/// Decrypts transit layers, re-encrypts with new AES key for storage.
131→#[instrument(skip(store, ephemeral_public, transit_layers, node_secret_key, node_public_key), fields(sender_did = %sender_did, sender_device_id = %sender_device_id))]
132→pub fn store_published_page(
133→    store: &RedbStore,
134→    page_meta: PageMeta,
135→    permit: &str,
136→    ephemeral_public: &[u8; 32],
137→    transit_layers: Vec<(String, Vec<u8>)>,
138→    node_secret_key: &[u8; 32],
139→    node_public_key: &[u8; 32],
140→    source_node_did: Option<&str>,
141→    sender_did: &str,
142→    sender_device_id: &str,
143→) -> Result<Page> {
144→    // 1. Derive transit key from ECDH to decrypt
145→    let shared_secret = herald::ecdh(node_secret_key, ephemeral_public);
146→    let transit_key = herald::derive_key(&shared_secret, None, b"herald-transit-v1");
147→
148→    // 2. Decrypt all transit layers
149→    let mut decrypted_layers = Vec::with_capacity(transit_layers.len());
150→    for (layer_name, encrypted) in transit_layers {
151→        let decrypted = herald::decrypt_symmetric(&transit_key, &encrypted)
152→            .map_err(|e| ButlerError::Encryption(
153→                format!("Failed to decrypt transit layer {}: {}", layer_name, e)
154→            ))?;
155→        decrypted_layers.push((layer_name, decrypted));
156→    }
157→
158→    // 3. Generate new AES key for storage on Node
159→    let aes_key = herald::generate_aes_key();
160→
161→    // 4. Re-encrypt layers with new AES key and store sender's state vectors
162→    log::info!("store_published_page: page_id={} storing {} layers",
163→        page_meta.id, decrypted_layers.len());
164→    for (layer_name, plaintext) in &decrypted_layers {
165→        log::info!("store_published_page: storing layer {} ({} bytes plaintext)",
166→            layer_name, plaintext.len());
167→        let encrypted = herald::encrypt_symmetric(&aes_key, plaintext)
168→            .map_err(|e| ButlerError::Encryption(
169→                format!("Failed to encrypt layer {}: {}", layer_name, e)
170→            ))?;
171→        store.put_layer(&page_meta.id, layer_name, &encrypted)?;
172→
173→        // Store sender's state vector so we can send incremental updates later
174→        let temp_doc = loro::LoroDoc::new();
175→        if temp_doc.import(plaintext).is_ok() {
176→            let vector = temp_doc.oplog_vv().encode();
177→            let _ = store.put_peer_vector_for_layer(
178→                &page_meta.id,
179→                sender_did,
180→                sender_device_id,
181→                layer_name,
182→                vector,
183→            );
184→        }
185→    }
186→
187→    // 5. Encrypt AES key with Node's encryption public key (ECIES)
188→    let encrypted_key = herald::encrypt(node_public_key, &aes_key)
189→        .map_err(|e| ButlerError::Encryption(format!("Failed to encrypt AES key: {}", e)))?;
190→
191→    // 6. Create page metadata with encrypted key
192→    let mut meta = page_meta;
193→    meta.encrypted_key = encrypted_key;
194→
195→    // 7. Store page with permit
196→    let mut data = PageData::new(meta.clone());
197→    data.set_permit(permit.to_string());
198→
199→    // Track source node in shares (viewer uses this to know where to get updates)
200→    if let Some(node_did) = source_node_did {
201→        data.add_share(node_did.to_string());
202→    }
203→
204→    store.put_page(&data)?;
205→
206→    // Register sender (owner) as authorized user for this page
207→    // This allows can_write() in Scribe to accept SyncOffer from owner
208→    // Compute CID from permit for revocation tracking
209→    let permit_cid = gurkha::crypto::get_permit_cid(permit)
210→        .unwrap_or_else(|_| "unknown".to_string());
211→    store.put_permit_cid(&meta.id, sender_did, &permit_cid)?;
212→
213→    Ok(Page::from(meta))
214→}
