355→/// Mark a page as published to a specific node
356→#[instrument(skip(store), fields(page_id = %page_id, node_id = %node_id))]
357→pub fn mark_page_published(store: &RedbStore, page_id: &str, node_id: &str) -> Result<()> {
358→    let mut page = store.find_page_by_id(page_id)?
359→        .ok_or_else(|| ButlerError::page_not_found(page_id))?;
360→
361→    // Add node_id to shares list to track publishing (using "published:{node_id}" prefix)
362→    page.add_share(format!("published:{}", node_id));
363→    store.put_page(&page)?;
364→    Ok(())
365→}
