  3→/// Permission level for layer access (simplified for Lua FFI)
  4→/// Hierarchy: Admin > ReadWrite > ReadOnly
  5→#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
  6→pub enum Capability {
  7→    /// Read-only access, no write permissions
  8→    /// Lowest privilege
  9→    ReadOnly,
 10→
 11→    /// Read and write access to layer
 12→    ReadWrite,
 13→
 14→    /// Full administrative access
 15→    /// Highest privilege
 16→    Admin,
 17→}
 18→
 19→impl Capability {
 20→    pub fn from_str(s: &str) -> Result<Self, String> {
 21→        match s {
 22→            "read_only" | "readonly" | "viewer" => Ok(Capability::ReadOnly),
 23→            "read_write" | "readwrite" | "collaborator" => Ok(Capability::ReadWrite),
 24→            "admin" | "owner" => Ok(Capability::Admin),
 25→            _ => Err(format!("Unknown capability: {}", s)),
 26→        }
 27→    }
 28→
 29→    pub fn as_str(&self) -> &str {
 30→        match self {
 31→            Capability::ReadOnly => "read_only",
 32→            Capability::ReadWrite => "read_write",
 33→            Capability::Admin => "admin",
 34→        }
 35→    }
 36→
 37→    pub fn can_write(&self) -> bool {
 38→        matches!(self, Capability::ReadWrite | Capability::Admin)
 39→    }
 40→
 41→    pub fn can_admin(&self) -> bool {
 42→        matches!(self, Capability::Admin)
 43→    }
 44→}
