170→/// Read unsynced entries (synced == false) from a peer's __sync_meta layer
171→pub fn read_unsynced_entries(state: &ScribeState, peer_did: &str) -> Vec<String> {
172→    read_sync_meta_entries(state, peer_did)
173→        .into_iter()
174→        .filter(|e| !e.synced)
175→        .map(|e| e.layer_name)
176→        .collect()
