128→/// Butler's implementation of LayerStorage
129→///
130→/// Saves layer snapshots to RedbStore with AES encryption.
131→/// Scoped to a single page (page_id passed at construction).
132→pub struct ButlerLayerStorage {
133→    store: Arc<RedbStore>,
134→    page_id: String,
135→    aes_key: [u8; 32],
136→}
137→
138→impl ButlerLayerStorage {
139→    pub fn new(store: Arc<RedbStore>, page_id: String, aes_key: [u8; 32]) -> Self {
140→        Self {
141→            store,
142→            page_id,
143→            aes_key,
144→        }
145→    }
146→}
147→
148→impl LayerStorage for ButlerLayerStorage {
149→    #[instrument(skip_all)]
150→    fn save_layer(&self, layer_name: &str, data: &[u8]) -> Result<()> {
151→        info!(page_id = %self.page_id, layer_name = %layer_name, data_len = data.len(), "ButlerLayerStorage::save_layer");
152→
153→        // Encrypt layer data
154→        let encrypted = herald::encrypt_symmetric(&self.aes_key, data)
155→            .map_err(|e| ScribeError::Other(format!("Encryption failed: {}", e)))?;
156→
157→        // Save to store
158→        self.store
159→            .put_layer(&self.page_id, layer_name, &encrypted)
160→            .map_err(|e| ScribeError::Other(format!("Store error: {}", e)))
161→    }
162→}
