312→impl DelegationTemplate {
313→    /// Convert template to permit facts JSON
314→    ///
315→    /// This creates the facts structure that will be embedded in the delegated token.
316→    /// Role-agnostic: only includes capabilities and patterns, no role-based logic.
317→    pub fn to_facts(&self) -> serde_json::Map<String, serde_json::Value> {
318→        let mut facts = serde_json::Map::new();
319→
320→        // Add token_type
321→        facts.insert(
322→            "token_type".to_string(),
323→            serde_json::Value::String(self.token_type.clone()),
324→        );
325→
326→        // Add peer_capabilities
327→        facts.insert(
328→            "peer_capabilities".to_string(),
329→            self.peer_capabilities.to_json(),
330→        );
331→
332→        // Add operations (required for delegation chain - e.g., add_pages permission)
333→        if !self.operations.is_empty() {
334→            let ops_json: serde_json::Map<String, serde_json::Value> = self
335→                .operations
336→                .iter()
337→                .map(|(k, v)| (k.clone(), serde_json::Value::String(v.clone())))
338→                .collect();
339→            facts.insert(
340→                "operations".to_string(),
341→                serde_json::Value::Object(ops_json),
342→            );
343→        }
344→
345→        // Add auth_capabilities
346→        if !self.auth_capabilities.is_empty() {
347→            let auth_json: serde_json::Map<String, serde_json::Value> = self
348→                .auth_capabilities
349→                .iter()
350→                .map(|(k, v)| (k.clone(), v.clone()))
351→                .collect();
352→            facts.insert(
353→                "auth_capabilities".to_string(),
354→                serde_json::Value::Object(auth_json),
355→            );
356→        }
357→
358→        // Add layer_patterns
359→        if !self.layer_patterns.is_empty() {
360→            let patterns_json: serde_json::Map<String, serde_json::Value> = self
361→                .layer_patterns
362→                .iter()
363→                .map(|(pattern, config)| {
364→                    (
365→                        pattern.clone(),
366→                        serde_json::json!({
367→                            "create": config.create,
368→                            "sync": config.sync,
369→                            "write": config.write
370→                        }),
371→                    )
372→                })
373→                .collect();
374→            facts.insert(
375→                "layer_patterns".to_string(),
376→                serde_json::Value::Object(patterns_json),
377→            );
378→        }
379→
380→        // Add fixed layers
381→        if !self.layers.is_empty() {
382→            let layers_json: serde_json::Map<String, serde_json::Value> = self
383→                .layers
384→                .iter()
385→                .map(|(name, config)| {
386→                    let mut layer_obj = serde_json::Map::new();
387→                    layer_obj.insert("sync".to_string(), serde_json::Value::Bool(config.sync));
388→                    layer_obj.insert("write".to_string(), serde_json::Value::Bool(config.write));
389→                    if let Some(ref t) = config.layer_type {
390→                        layer_obj.insert("type".to_string(), serde_json::Value::String(t.clone()));
391→                    }
392→                    (name.clone(), serde_json::Value::Object(layer_obj))
393→                })
394→                .collect();
395→            facts.insert("layers".to_string(), serde_json::Value::Object(layers_json));
396→        }
397→
398→        // Add relationship (for logging only)
399→        if let Some(rel) = &self.relationship {
400→            facts.insert(
401→                "relationship".to_string(),
402→                serde_json::Value::String(rel.clone()),
403→            );
404→        }
405→
406→        // Add issue_on (self-describing templates for what to issue on actions)
407→        if !self.issue_on.is_empty() {
408→            let issue_on_json: serde_json::Map<String, serde_json::Value> = self
409→                .issue_on
410→                .iter()
411→                .map(|(action, template)| {
412→                    (
413→                        action.clone(),
414→                        serde_json::Value::Object(template.to_facts()),
415→                    )
416→                })
417→                .collect();
418→            facts.insert(
419→                "issue_on".to_string(),
420→                serde_json::Value::Object(issue_on_json),
421→            );
422→        }
423→
424→        // Add presence configuration
425→        if let Some(ref presence) = self.presence {
426→            let mut presence_json = serde_json::Map::new();
427→            presence_json.insert(
428→                "visible".to_string(),
429→                serde_json::Value::Bool(presence.visible),
430→            );
431→            presence_json.insert(
432→                "can_see_others".to_string(),
433→                serde_json::Value::Bool(presence.can_see_others),
434→            );
435→            if let Some(ref name) = presence.name {
436→                presence_json.insert("name".to_string(), serde_json::Value::String(name.clone()));
437→            }
438→            facts.insert(
439→                "presence".to_string(),
440→                serde_json::Value::Object(presence_json),
441→            );
442→        }
443→
444→        // Add ephemeral_funcs (allowed ephemeral function names)
445→        if !self.ephemeral_funcs.is_empty() {
446→            let funcs: Vec<serde_json::Value> = self
447→                .ephemeral_funcs
448→                .iter()
449→                .map(|f| serde_json::Value::String(f.clone()))
450→                .collect();
451→            facts.insert(
452→                "ephemeral_funcs".to_string(),
453→                serde_json::Value::Array(funcs),
454→            );
455→        }
456→
457→        // Add dynamic_layer_schemas
458→        if !self.dynamic_layer_schemas.is_empty() {
459→            let schemas_json: serde_json::Map<String, serde_json::Value> = self
460→                .dynamic_layer_schemas
461→                .iter()
462→                .map(|(pattern, schema)| {
463→                    (
464→                        pattern.clone(),
465→                        serde_json::to_value(schema).unwrap_or_default(),
466→                    )
467→                })
468→                .collect();
469→            facts.insert(
470→                "dynamic_layer_schemas".to_string(),
471→                serde_json::Value::Object(schemas_json),
472→            );
473→        }
474→
475→        // Add authorized_peers for layer authority templates.
476→        // Missing/None means open distribution (all peers).
477→        if self.token_type == "layer_authority" {
478→            if let Some(peers) = &self.authorized_peers {
479→                let values = peers
480→                    .iter()
481→                    .map(|did| serde_json::Value::String(did.clone()))
482→                    .collect();
483→                facts.insert(
484→                    "authorized_peers".to_string(),
485→                    serde_json::Value::Array(values),
486→                );
487→            }
488→        }
489→
490→        facts
491→    }
492→}
