600→    /// Parse a DelegationTemplate from a JSON value
601→    fn parse_delegation_template(
602→        key: &str,
603→        template_val: &serde_json::Value,
604→    ) -> Option<DelegationTemplate> {
605→        let template_obj = template_val.as_object()?;
606→
607→        // Extract token_type
608→        let token_type = template_obj
609→            .get("token_type")
610→            .and_then(|v| v.as_str())
611→            .map(String::from)
612→            .unwrap_or_else(|| format!("delegated_{}", key));
613→
614→        // Extract peer_capabilities
615→        let peer_capabilities = template_obj
616→            .get("peer_capabilities")
617→            .and_then(|v| v.as_object())
618→            .map(PeerCapabilities::from_json)
619→            .unwrap_or_default();
620→
621→        // Extract layer_patterns
622→        let mut layer_patterns = HashMap::new();
623→        if let Some(patterns_obj) = template_obj
624→            .get("layer_patterns")
625→            .and_then(|v| v.as_object())
626→        {
627→            for (pattern, config) in patterns_obj {
628→                if let Some(config_obj) = config.as_object() {
629→                    layer_patterns.insert(
630→                        pattern.clone(),
631→                        LayerPatternConfig {
632→                            create: config_obj
633→                                .get("create")
634→                                .and_then(|v| v.as_bool())
635→                                .unwrap_or(false),
636→                            sync: config_obj
637→                                .get("sync")
638→                                .and_then(|v| v.as_bool())
639→                                .unwrap_or(false),
640→                            write: config_obj
641→                                .get("write")
642→                                .and_then(|v| v.as_bool())
643→                                .unwrap_or(false),
644→                        },
645→                    );
646→                }
647→            }
648→        }
649→
650→        // Extract fixed layers
651→        let mut layers = HashMap::new();
652→        if let Some(layers_obj) = template_obj.get("layers").and_then(|v| v.as_object()) {
653→            for (layer_name, layer_val) in layers_obj {
654→                if let Some(layer_obj) = layer_val.as_object() {
655→                    layers.insert(
656→                        layer_name.clone(),
657→                        LayerConfig {
658→                            sync: layer_obj
659→                                .get("sync")
660→                                .and_then(|v| v.as_bool())
661→                                .unwrap_or(false),
662→                            write: layer_obj
663→                                .get("write")
664→                                .and_then(|v| v.as_bool())
665→                                .unwrap_or(false),
666→                            layer_type: layer_obj
667→                                .get("type")
668→                                .and_then(|v| v.as_str())
669→                                .map(String::from),
670→                        },
671→                    );
672→                }
673→            }
674→        }
675→
676→        // Extract relationship (for logging only)
677→        let relationship = template_obj
678→            .get("relationship")
679→            .and_then(|v| v.as_str())
680→            .map(String::from);
681→
682→        // Extract operations (e.g., add_pages, share_page)
683→        let mut operations = HashMap::new();
684→        if let Some(ops_obj) = template_obj.get("operations").and_then(|v| v.as_object()) {
685→            for (op_name, op_val) in ops_obj {
686→                if let Some(op_str) = op_val.as_str() {
687→                    operations.insert(op_name.clone(), op_str.to_string());
688→                }
689→            }
690→        }
691→
692→        // Extract auth_capabilities (can_connect, sync_enabled, etc.)
693→        let mut auth_capabilities = HashMap::new();
694→        if let Some(auth_obj) = template_obj
695→            .get("auth_capabilities")
696→            .and_then(|v| v.as_object())
697→        {
698→            for (cap_name, cap_val) in auth_obj {
699→                auth_capabilities.insert(cap_name.clone(), cap_val.clone());
700→            }
701→        }
702→
703→        // Extract issue_on (recursive - templates for what to issue on actions)
704→        let mut issue_on = HashMap::new();
705→        if let Some(issue_on_obj) = template_obj.get("issue_on").and_then(|v| v.as_object()) {
706→            for (action_key, nested_template_val) in issue_on_obj {
707→                if let Some(nested_template) =
708→                    Self::parse_delegation_template(action_key, nested_template_val)
709→                {
