717→            .get("presence")
718→            .and_then(|v| v.as_object())
719→            .map(|p| PresenceConfig {
720→                visible: p.get("visible").and_then(|v| v.as_bool()).unwrap_or(false),
721→                can_see_others: p
722→                    .get("can_see_others")
723→                    .and_then(|v| v.as_bool())
724→                    .unwrap_or(true),
725→                name: p.get("name").and_then(|v| v.as_str()).map(String::from),
726→            });
727→
728→        // Extract ephemeral_funcs
729→        let ephemeral_funcs = template_obj
730→            .get("ephemeral_funcs")
731→            .and_then(|v| v.as_array())
732→            .map(|arr| {
733→                arr.iter()
734→                    .filter_map(|v| v.as_str().map(String::from))
735→                    .collect()
736→            })
737→            .unwrap_or_default();
738→
739→        // Extract dynamic_layer_schemas
740→        let mut dynamic_layer_schemas = HashMap::new();
741→        if let Some(schemas_obj) = template_obj
742→            .get("dynamic_layer_schemas")
743→            .and_then(|v| v.as_object())
744→        {
745→            for (pattern, schema_val) in schemas_obj {
