749→                }
750→            }
751→        }
752→
753→        let authorized_peers = parse_authorized_peers_fact(template_obj.get("authorized_peers"))
754→            .ok()
755→            .flatten();
756→
757→        Some(DelegationTemplate {
758→            token_type,
759→            peer_capabilities,
760→            operations,
761→            auth_capabilities,
762→            layer_patterns,
763→            layers,
764→            relationship,
765→            issue_on,
766→            presence,
767→            ephemeral_funcs,
768→            dynamic_layer_schemas,
769→            authorized_peers,
770→        })
771→    }
