1117→/// Strip `{page_id}/` prefix from an expanded layer name to get the bare name
1118→///
1119→/// **Context**: Scribe uses bare layer names (no page_id prefix).
1120→/// Permit patterns like `{page_id}/products` expand to `{uuid}/products`.
1121→/// This strips the prefix to get `products` for Scribe's layer map.
1122→///
1123→/// **Example**: `"abc123/products"` with page_id `"abc123"` → `"products"`
1124→/// **Pass-through**: `"app:Shop"` (no prefix) → `"app:Shop"`
1125→fn strip_page_prefix(expanded: &str, page_id: &str) -> String {
1126→    let prefix = format!("{}/", page_id);
1127→    expanded
1128→        .strip_prefix(&prefix)
1129→        .unwrap_or(expanded)
1130→        .to_string()
1131→}
