1133→/// Expand placeholders in a pattern
1134→///
1135→/// **Placeholders:**
1136→/// - `{page_id}` → replaced with page_id
1137→/// - `{aud}` → replaced with did
1138→///
1139→/// **Example:** `{page_id}/orders/{aud}` → `shop123/orders/did:key:abc`
1140→pub fn expand_pattern(pattern: &str, page_id: &str, did: &str) -> String {
1141→    pattern.replace("{page_id}", page_id).replace("{aud}", did)
1142→}
