1144→/// Resolve {page_id} placeholders in permit facts
1145→///
1146→/// Replaces {page_id} in layer keys at all levels (top-level and nested issue_on).
1147→/// Also removes `layer_patterns` from facts (replaced by dynamic_layer_schemas).
1148→pub fn resolve_page_id_in_facts(
1149→    facts: &mut serde_json::Map<String, serde_json::Value>,
1150→    page_id: &str,
1151→) {
1152→    // Resolve top-level layers
1153→    if let Some(layers) = facts.remove("layers") {
1154→        if let Some(layers_obj) = layers.as_object() {
1155→            let mut resolved = serde_json::Map::new();
1156→            for (key, val) in layers_obj {
1157→                let resolved_key = key.replace("{page_id}", page_id);
1158→                resolved.insert(resolved_key, val.clone());
1159→            }
1160→            facts.insert("layers".to_string(), serde_json::Value::Object(resolved));
1161→        }
1162→    }
1163→
1164→    // Remove layer_patterns (replaced by dynamic_layer_schemas)
1165→    facts.remove("layer_patterns");
1166→
1167→    // Recurse into issue_on templates
1168→    if let Some(issue_on) = facts.remove("issue_on") {
1169→        if let Some(issue_on_obj) = issue_on.as_object() {
1170→            let mut resolved_issue_on = serde_json::Map::new();
1171→            for (action, template_val) in issue_on_obj {
1172→                if let Some(mut template_obj) = template_val.as_object().cloned() {
1173→                    resolve_page_id_in_facts(&mut template_obj, page_id);
1174→                    resolved_issue_on
1175→                        .insert(action.clone(), serde_json::Value::Object(template_obj));
1176→                } else {
1177→                    resolved_issue_on.insert(action.clone(), template_val.clone());
1178→                }
1179→            }
1180→            facts.insert(
1181→                "issue_on".to_string(),
1182→                serde_json::Value::Object(resolved_issue_on),
1183→            );
1184→        }
1185→    }
1186→}
