1188→/// Match a layer path against a dynamic layer schema pattern (issuance-side only)
1189→///
1190→/// Used at dynamic layer creation time to validate that the node has authority
1191→/// to create a layer of this type.
1192→///
1193→/// **Pattern:** `{id}` matches any single path segment
1194→///
1195→/// **Examples:**
1196→/// - `channels/announcements/messages` matches `channels/{id}/messages`
1197→/// - `dms/uuid-123/messages` matches `dms/{id}/messages`
1198→/// - `orders/uuid-456` matches `orders/{id}`
1199→pub fn matches_schema_pattern(layer_path: &str, schema_pattern: &str) -> bool {
1200→    let path_parts: Vec<&str> = layer_path.split('/').collect();
1201→    let pattern_parts: Vec<&str> = schema_pattern.split('/').collect();
1202→
1203→    if path_parts.len() != pattern_parts.len() {
1204→        return false;
1205→    }
1206→
1207→    path_parts
1208→        .iter()
1209→        .zip(pattern_parts.iter())
1210→        .all(|(path_seg, pat_seg)| *pat_seg == "{id}" || path_seg == pat_seg)
1211→}
