1236→/// Match layer name against pattern with path-segment wildcards
1237→///
1238→/// **Pattern:** `*` matches any single path segment (delimited by `/`)
1239→///
1240→/// **Examples:**
1241→/// - `shop123/*/did:key:abc` matches `shop123/orders/did:key:abc`
1242→/// - `shop123/*/*` matches `shop123/orders/did:key:abc`
1243→/// - `shop123/*` does NOT match `shop123/orders/did:key:abc` (different segment count)
1244→pub fn matches_wildcard(layer_name: &str, pattern: &str) -> bool {
1245→    let layer_parts: Vec<&str> = layer_name.split('/').collect();
1246→    let pattern_parts: Vec<&str> = pattern.split('/').collect();
1247→
1248→    if layer_parts.len() != pattern_parts.len() {
1249→        return false;
1250→    }
1251→
1252→    layer_parts
1253→        .iter()
1254→        .zip(pattern_parts.iter())
1255→        .all(|(layer, pat)| *pat == "*" || layer == pat)
1256→}
