 13→/// Handle CreateDynamicLayer message
 14→///
 15→/// **Context**: Lua app calls scribe:create_layer("channels/{id}/messages", "general")
 16→/// **We do**: Validate schema exists in permit, generate full path with our DID, create layer
 17→/// **Returns**: Full layer name (bare, without page_id prefix)
 18→pub fn handle_create_dynamic_layer(
 19→    state: &mut ScribeState,
 20→    schema_key: &str,
 21→    layer_id: &str,
 22→) -> Result<String, String> {
 23→    let permit = state.our_permit.as_ref()
 24→        .ok_or_else(|| "No permit available".to_string())?;
 25→
 26→    // Validate schema exists in our permit's dynamic_layer_schemas
 27→    let schemas = permit.dynamic_layer_schemas();
 28→    let _schema = schemas
 29→        .get(schema_key)
 30→        .cloned()
 31→        .ok_or_else(|| format!("Schema '{}' not found in permit", schema_key))?;
 32→
 33→    // Generate full layer path with our DID
 34→    // Schema: "channels/{id}/messages" → Path: "channels/{our_did}/{layer_id}/messages"
 35→    let bare_path = generate_dynamic_path(schema_key, &state.our_did, layer_id);
 36→    let full_name = format!("{}/{}", state.page_id, bare_path);
 37→
 38→    // Check if layer already exists
 39→    if state.units.contains_key(&bare_path) {
 40→        info!(layer = %bare_path, "Dynamic layer already exists");
 41→        return Ok(full_name);
 42→    }
 43→
 44→    // Create the layer
 45→    info!(
 46→        page_id = %state.page_id,
 47→        schema = %schema_key,
 48→        layer = %bare_path,
 49→        "Creating dynamic layer"
 50→    );
 51→    let mut unit = LayerUnit::new_empty();
 52→    unit.set_local_only(!state.should_sync_layer(&bare_path));
 53→    unit.is_dynamic = true;
 54→    state.units.insert(bare_path.clone(), unit);
 55→
 56→    // Add all connected subscribers to the new layer
 57→    if let Ok(subs) = state.subscribers.read() {
 58→        for ((did, _), info) in subs.iter() {
 59→            if let Some(unit) = state.units.get(&bare_path) {
 60→                let caps = super::Capabilities { read: true, write: true, sync: true };
 61→                unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
 62→                state.emit_layer_auth_capture(&bare_path, did, "subscriber_added_on_create");
 63→            }
 64→        }
 65→    }
 66→
 67→    // Set up observer for the new layer
 68→    loro_observer::setup_layer_observer(state, &bare_path);
 69→
 70→    // Write entry to creator's __sync_meta for node discovery
 71→    {
 72→        use crate::sync::sync_meta;
 73→        let our_did = state.our_did.clone();
 74→        let meta_layer = sync_meta::sync_meta_layer_name(&our_did);
 75→        if state.units.contains_key(&meta_layer) {
 76→            sync_meta::write_sync_meta_entry(state, &our_did, &bare_path, false);
 77→            info!(layer = %bare_path, "Wrote dynamic layer entry to creator's __sync_meta");
 78→        }
 79→    }
 80→
 81→    Ok(full_name)
 82→}
 83→
 84→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
 85→///
 86→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
 87→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
 88→///
 89→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
 90→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
 91→    let parts: Vec<&str> = schema_key.split('/').collect();
 92→    let mut result = Vec::new();
 93→
 94→    if parts.is_empty() {
 95→        return format!("{}/{}", our_did, layer_id);
 96→    }
 97→
 98→    // First segment: literal
 99→    result.push(parts[0].to_string());
100→
101→    // Insert our DID as the second segment (namespace)
102→    result.push(our_did.to_string());
103→
104→    // Remaining segments: replace {id} with layer_id, keep literals
105→    for part in &parts[1..] {
106→        if *part == "{id}" {
107→            result.push(layer_id.to_string());
108→        } else {
109→            result.push(part.to_string());
110→        }
111→    }
112→
113→    result.join("/")
114→}
