116→/// Find matching dynamic schema for a layer received from a peer
117→///
118→/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
119→/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
120→pub fn find_matching_dynamic_schema<'a>(
121→    permit: &'a gurkha::Permit,
122→    layer_name: &str,
123→    page_id: &str,
124→) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
125→    let schemas = permit.dynamic_layer_schemas();
126→    if schemas.is_empty() {
127→        return None;
128→    }
129→
130→    // Strip page_id prefix to get bare layer path
131→    let page_prefix = format!("{}/", page_id);
132→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
133→
134→    let path_parts: Vec<&str> = bare_path.split('/').collect();
135→
136→    // Path must have at least 3 segments: prefix/did/id[/suffix]
137→    if path_parts.len() < 3 {
138→        return None;
139→    }
140→
141→    // Second segment should be a DID (the creator)
142→    let potential_creator = path_parts[1];
143→    if !potential_creator.starts_with("did:") {
144→        return None;
145→    }
146→
147→    // Try each schema pattern
148→    for (schema_key, schema) in schemas {
149→        let pattern_parts: Vec<&str> = schema_key.split('/').collect();
150→
151→        // Dynamic path has one extra segment (DID) compared to pattern
152→        if path_parts.len() != pattern_parts.len() + 1 {
153→            continue;
154→        }
155→
156→        // First segment must match literally
157→        if path_parts[0] != pattern_parts[0] {
158→            continue;
159→        }
160→
161→        // path[2..] must match pattern[1..] (with {id} as wildcard)
162→        let mut matched = true;
163→        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
164→            if *pat_seg != "{id}" && path_seg != pat_seg {
165→                matched = false;
166→                break;
167→            }
168→        }
169→
170→        if matched {
171→            return Some((schema_key, schema, potential_creator.to_string()));
172→        }
173→    }
174→
175→    None
176→}
