//! Dynamic Layer Management
//!
//! Schema validation, path generation, and permit preparation for dynamic layers.
//! Uses PermitIssuer trait — never touches signing keys directly.

use tracing::{info, warn};

use crate::state::ScribeState;
use crate::loro_observer;

use super::LayerUnit;

/// Handle CreateDynamicLayer message
///
/// **Context**: Lua app calls scribe:create_layer("channels/{id}/messages", "general")
/// **We do**: Validate schema exists in permit, generate full path with our DID, create layer
/// **Returns**: Full layer name (bare, without page_id prefix)
pub fn handle_create_dynamic_layer(
    state: &mut ScribeState,
    schema_key: &str,
    layer_id: &str,
) -> Result<String, String> {
    let permit = state.our_permit.as_ref()
        .ok_or_else(|| "No permit available".to_string())?;

    // Validate schema exists in our permit's dynamic_layer_schemas
    let schemas = permit.dynamic_layer_schemas();
    let _schema = schemas
        .get(schema_key)
        .cloned()
        .ok_or_else(|| format!("Schema '{}' not found in permit", schema_key))?;

    // Generate full layer path with our DID
    // Schema: "channels/{id}/messages" → Path: "channels/{our_did}/{layer_id}/messages"
    let bare_path = generate_dynamic_path(schema_key, &state.our_did, layer_id);
    let full_name = format!("{}/{}", state.page_id, bare_path);

    // Check if layer already exists
    if state.units.contains_key(&bare_path) {
        info!(layer = %bare_path, "Dynamic layer already exists");
        return Ok(full_name);
    }

    // Create the layer
    info!(
        page_id = %state.page_id,
        schema = %schema_key,
        layer = %bare_path,
        "Creating dynamic layer"
    );
    let mut unit = LayerUnit::new_empty();
    unit.set_local_only(!state.should_sync_layer(&bare_path));
    unit.is_dynamic = true;
    state.units.insert(bare_path.clone(), unit);

    // Add all connected subscribers to the new layer
    if let Ok(subs) = state.subscribers.read() {
        for ((did, _), info) in subs.iter() {
            if let Some(unit) = state.units.get(&bare_path) {
                let caps = super::Capabilities { read: true, write: true, sync: true };
                unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
                state.emit_layer_auth_capture(&bare_path, did, "subscriber_added_on_create");
            }
        }
    }

    // Set up observer for the new layer
    loro_observer::setup_layer_observer(state, &bare_path);

    // Write entry to creator's __sync_meta for node discovery
    {
        use crate::sync::sync_meta;
        let our_did = state.our_did.clone();
        let meta_layer = sync_meta::sync_meta_layer_name(&our_did);
        if state.units.contains_key(&meta_layer) {
            sync_meta::write_sync_meta_entry(state, &our_did, &bare_path, false);
            info!(layer = %bare_path, "Wrote dynamic layer entry to creator's __sync_meta");
        }
    }

    Ok(full_name)
}

/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
///
/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
///
/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
    let parts: Vec<&str> = schema_key.split('/').collect();
    let mut result = Vec::new();

    if parts.is_empty() {
        return format!("{}/{}", our_did, layer_id);
    }

    // First segment: literal
    result.push(parts[0].to_string());

    // Insert our DID as the second segment (namespace)
    result.push(our_did.to_string());

    // Remaining segments: replace {id} with layer_id, keep literals
    for part in &parts[1..] {
        if *part == "{id}" {
            result.push(layer_id.to_string());
        } else {
            result.push(part.to_string());
        }
    }

    result.join("/")
}

/// Find matching dynamic schema for a layer received from a peer
///
/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
pub fn find_matching_dynamic_schema<'a>(
    permit: &'a gurkha::Permit,
    layer_name: &str,
    page_id: &str,
) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
    let schemas = permit.dynamic_layer_schemas();
    if schemas.is_empty() {
        return None;
    }

    // Strip page_id prefix to get bare layer path
    let page_prefix = format!("{}/", page_id);
    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);

    let path_parts: Vec<&str> = bare_path.split('/').collect();

    // Path must have at least 3 segments: prefix/did/id[/suffix]
    if path_parts.len() < 3 {
        return None;
    }

    // Second segment should be a DID (the creator)
    let potential_creator = path_parts[1];
    if !potential_creator.starts_with("did:") {
        return None;
    }

    // Try each schema pattern
    for (schema_key, schema) in schemas {
        let pattern_parts: Vec<&str> = schema_key.split('/').collect();

        // Dynamic path has one extra segment (DID) compared to pattern
        if path_parts.len() != pattern_parts.len() + 1 {
            continue;
        }

        // First segment must match literally
        if path_parts[0] != pattern_parts[0] {
            continue;
        }

        // path[2..] must match pattern[1..] (with {id} as wildcard)
        let mut matched = true;
        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
            if *pat_seg != "{id}" && path_seg != pat_seg {
                matched = false;
                break;
            }
        }

        if matched {
            return Some((schema_key, schema, potential_creator.to_string()));
        }
    }

    None
}

/// Handle AddLayerAccess message
///
/// **Context**: Lua app calls scribe:add_layer_access(layer_name, did)
/// **We do**: Validate capability, issue authority permit (intent), write to target's __sync_meta.
/// **Flow**: Node stores authority permit → writes to target's __sync_meta →
///   target discovers entry → sends LayerSubscribe → node issues access permit + data.
pub fn handle_add_layer_access(
    state: &mut ScribeState,
    layer_name: &str,
    did: &str,
) -> Result<(), String> {
    // 1. Check our permit has manage_layer_access capability
    let permit = state.our_permit.as_ref().ok_or_else(|| {
        warn!(page_id = %state.page_id, layer = %layer_name, audience = %did, "AddLayerAccess rejected: missing our_permit");
        "No permit".to_string()
    })?;
    if !permit.can_manage_layer_access() {
        warn!(
            page_id = %state.page_id,
            layer = %layer_name,
            audience = %did,
            "AddLayerAccess rejected: missing manage_layer_access capability"
        );
        return Err("No manage_layer_access capability".into());
    }

    // 2. Validate schema match + explicit grant
    let (_schema_key, schema, _creator) = find_matching_dynamic_schema(permit, layer_name, &state.page_id)
        .ok_or_else(|| {
            warn!(
                page_id = %state.page_id,
                layer = %layer_name,
                audience = %did,
                "AddLayerAccess rejected: layer does not match dynamic schema"
            );
            "Layer does not match any dynamic schema".to_string()
        })?;
    if schema.grant != gurkha::GrantType::Explicit {
        warn!(
            page_id = %state.page_id,
            layer = %layer_name,
            audience = %did,
            "AddLayerAccess rejected: schema grant is not explicit"
        );
        return Err("AddLayerAccess only applies to explicit dynamic schemas".into());
    }

    // 3. Issue authority permit (intent) — stored by PermitIssuer for later retrieval
    let issuer = state.permit_issuer.as_ref().ok_or_else(|| {
        warn!(
            page_id = %state.page_id,
            layer = %layer_name,
            audience = %did,
            "AddLayerAccess rejected: no permit issuer"
        );
        "No permit issuer".to_string()
    })?;
    let config = schema.permissions.clone();
    issuer.issue_layer_authority_permit(did, layer_name, config, None, 1)
        .map_err(|e| format!("Failed to issue authority permit: {}", e))?;

    info!(
        page_id = %state.page_id,
        layer = %layer_name,
        audience = %did,
        "Stored authority intent for explicit layer access"
    );

    // 4. Write entry to target's __sync_meta (if it exists)
    let bare_name = crate::state::normalize_layer_name(layer_name, &state.page_id);
    {
        use crate::sync::sync_meta;
        let meta_layer = sync_meta::sync_meta_layer_name(did);
        if state.units.contains_key(&meta_layer) {
            sync_meta::write_sync_meta_entry(state, did, &bare_name, false);
            info!(
                layer = %bare_name,
                audience = %did,
                "Wrote explicit-grant entry to target's __sync_meta"
            );
        }
    }

    Ok(())
}

/// Handle RemoveLayerAccess message
///
/// **Context**: Lua app calls scribe:remove_layer_access(layer_name, did)
/// **We do**: Validate capability, reject metadata-era revoke path
pub fn handle_remove_layer_access(
    state: &ScribeState,
    layer_name: &str,
    did: &str,
) -> Result<(), String> {
    let permit = state.our_permit.as_ref().ok_or("No permit")?;
    if !permit.can_manage_layer_access() {
        return Err("No manage_layer_access capability".into());
    }

    let _ = layer_name;
    let _ = did;
    Err("RemoveLayerAccess is deprecated; rotate/revoke layer authority permits instead".to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generate_dynamic_path() {
        assert_eq!(
            generate_dynamic_path("channels/{id}/messages", "did:key:alice", "general"),
            "channels/did:key:alice/general/messages"
        );
        assert_eq!(
            generate_dynamic_path("orders/{id}", "did:key:bob", "uuid-123"),
            "orders/did:key:bob/uuid-123"
        );
        assert_eq!(
            generate_dynamic_path("dms/{id}/messages", "did:key:alice", "room1"),
            "dms/did:key:alice/room1/messages"
        );
    }

    #[test]
    fn test_find_matching_dynamic_schema() {
        // Shop owner has dynamic_layer_schemas: { "orders/{id}": ... }
        let permit = gurkha::test_fixtures::shop_owner("page1", "did:key:owner");

        // Match: orders/did:key:alice/uuid-123 — matches "orders/{id}" with DID inserted
        let result = find_matching_dynamic_schema(&permit, "orders/did:key:alice/uuid-123", "page1");
        assert!(result.is_some(), "Should match orders/{{id}} schema");
        let (schema_key, _schema, creator_did) = result.unwrap();
        assert_eq!(schema_key, "orders/{id}");
        assert_eq!(creator_did, "did:key:alice");

        // Match with page_id prefix
        let result = find_matching_dynamic_schema(&permit, "page1/orders/did:key:bob/order1", "page1");
        assert!(result.is_some());
        let (_, _, creator_did) = result.unwrap();
        assert_eq!(creator_did, "did:key:bob");

        // No match: wrong prefix
        let result = find_matching_dynamic_schema(&permit, "channels/did:key:alice/general/messages", "page1");
        assert!(result.is_none(), "Should not match — no channels schema");

        // No match: no DID in path
        let result = find_matching_dynamic_schema(&permit, "orders/general", "page1");
        assert!(result.is_none(), "Should not match — no DID segment");

        // No match: too short
        let result = find_matching_dynamic_schema(&permit, "orders", "page1");
        assert!(result.is_none(), "Should not match — too short");
    }

}

//! Storage traits for Scribe actor
//!
//! Butler implements these using RedbStore + encryption.
//! Scribe only knows about the abstract interface.
//!
//! ## Design
//!
//! These traits replace the closure-based storage injection pattern:
//! - `LayerStorage` replaces `SaveLayerFn`
//! - `PeerVectorStorage` replaces `LoadPeerVectorFn` + `SavePeerVectorFn`
//! - `PeerResolver` replaces `ListAuthorizedUsersFn` + `LoadUserPermitFn`
//!
//! Each trait is scoped to a single page (page_id passed at construction time).

use std::collections::HashMap;
use std::sync::Arc;

use crate::Result;

// Layer Storage Trait

/// Layer persistence (scoped to a page)
///
/// **Implemented by**: Butler's RedbStore + encryption layer
/// **Used by**: Scribe flush handler, immediate app layer saves
pub trait LayerStorage: Send + Sync {
    /// Save layer snapshot
    ///
    /// **Context**: Called during periodic flush or immediate save (app layers)
    /// **Implementor**: Should encrypt data before persistence
    fn save_layer(&self, layer_name: &str, data: &[u8]) -> Result<()>;
}

// Peer Vector Storage Trait

/// Peer state vector persistence (scoped to a page)
///
/// **Implemented by**: Butler's RedbStore
/// **Used by**: Scribe subscription handling, unsubscription, flush
///
/// State vectors track what each peer has already received.
/// This enables incremental sync (send only what they're missing).
pub trait PeerVectorStorage: Send + Sync {
    /// Load peer's state vectors for all layers
    ///
    /// **Context**: Called when peer subscribes to restore their last known state
    /// **Returns**: HashMap of layer_name -> state_vector bytes, or None if first connection
    fn load_vectors(
        &self,
        user_did: &str,
        device_id: &str,
    ) -> Result<Option<HashMap<String, Vec<u8>>>>;

    /// Save peer's state vectors for all layers
    ///
    /// **Context**: Called during flush and on unsubscribe
    /// **Note**: Vectors are stored as-is (Loro's binary format)
    fn save_vectors(
        &self,
        user_did: &str,
        device_id: &str,
        vectors: &HashMap<String, Vec<u8>>,
    ) -> Result<()>;
}

// Peer Resolver Trait (Node Mode Only)

/// Peer authorization (node mode only)
///
/// **Implemented by**: Butler's permit store
/// **Used by**: Scribe for node-mode peer lookup and validation
///
/// Only used when Scribe runs on a node (is_node=true).
/// Allows looking up authorized users and their permits.
pub trait PeerResolver: Send + Sync {
    /// List all authorized user_dids for this page
    ///
    /// **Context**: Node mode sync - finding peers to broadcast to
    /// **Returns**: List of DIDs that have permits for this page
    fn list_authorized_users(&self) -> Vec<String>;

    /// Load a user's permit for this page
    ///
    /// **Context**: Node mode - getting permit for validation/role extraction
    /// **Returns**: Permit token string if user has access, None otherwise
    fn load_user_permit(&self, user_did: &str) -> Option<String>;
}

// Permit Issuer Trait (Node Mode Only)

/// Layer permit issuance (node mode only, scoped to a page)
///
/// **Implemented by**: Butler using signing key + gurkha
/// **Used by**: Scribe layer_unit for issuing layer permits on dynamic layer detection
///
/// Scribe must never hold signing keys. This trait abstracts permit creation
/// so Scribe can request permits without accessing crypto directly.
pub trait PermitIssuer: Send + Sync {
    /// Issue a layer permit for a single dynamic layer
    ///
    /// **Context**: Node detected new dynamic layer, needs to issue permits
    /// **Returns**: (permit_token, cid) — ready to store and send
    fn issue_layer_permit(
        &self,
        audience: &str,
        layer_name: &str,
        config: gurkha::LayerConfig,
        intent_cid: Option<&str>,
    ) -> Result<(String, String)>;

    /// List layer authority permits applicable to a specific audience on this page.
    ///
    /// **Context**: Subscription-time issuance computes missing layer access permits
    /// from creator->node authority permits.
    /// **Returns**: Vec of (layer_name, version, authority_permit_token).
    fn list_layer_authority_permits_for_audience(
        &self,
        audience: &str,
    ) -> Result<Vec<(String, u64, String)>>;

    /// Get latest layer authority permit for page/layer/audience.
    fn get_layer_authority_permit(
        &self,
        audience: &str,
        layer_name: &str,
    ) -> Result<Option<(u64, String)>>;

    /// Check if this audience already has a stored layer access permit.
    fn has_layer_access_permit(&self, audience: &str, layer_name: &str) -> Result<bool>;

    /// Issue and persist a layer authority permit for this page/layer/audience.
    ///
    /// **Context**: Creator-side dynamic layer creation (viewer/owner) and
    /// node-side authority workflows.
    fn issue_layer_authority_permit(
        &self,
        audience: &str,
        layer_name: &str,
        config: gurkha::LayerConfig,
        authorized_peers: Option<Vec<String>>,
        version: u64,
    ) -> Result<(String, String)>;
}

// Type Aliases for Convenience

/// Reference-counted layer storage
pub type LayerStorageRef = Arc<dyn LayerStorage>;

/// Reference-counted peer vector storage
pub type PeerVectorStorageRef = Arc<dyn PeerVectorStorage>;

/// Reference-counted peer resolver
pub type PeerResolverRef = Arc<dyn PeerResolver>;

/// Reference-counted permit issuer
pub type PermitIssuerRef = Arc<dyn PermitIssuer>;

// Null Implementations (for testing)

/// Null layer storage that discards all saves
///
/// Useful for testing when persistence isn't needed
pub struct NullLayerStorage;

impl LayerStorage for NullLayerStorage {
    fn save_layer(&self, _layer_name: &str, _data: &[u8]) -> Result<()> {
        Ok(())
    }
}

/// Null peer vector storage that stores nothing
///
/// Useful for testing when peer tracking isn't needed
pub struct NullPeerVectorStorage;

impl PeerVectorStorage for NullPeerVectorStorage {
    fn load_vectors(
        &self,
        _user_did: &str,
        _device_id: &str,
    ) -> Result<Option<HashMap<String, Vec<u8>>>> {
        Ok(None)
    }

    fn save_vectors(
        &self,
        _user_did: &str,
        _device_id: &str,
        _vectors: &HashMap<String, Vec<u8>>,
    ) -> Result<()> {
        Ok(())
    }
}

/// Null peer resolver that has no authorized users
///
/// Useful for testing non-node mode
pub struct NullPeerResolver;

impl PeerResolver for NullPeerResolver {
    fn list_authorized_users(&self) -> Vec<String> {
        Vec::new()
    }

    fn load_user_permit(&self, _user_did: &str) -> Option<String> {
        None
    }
}

/// Null permit issuer that returns test tokens
///
/// Useful for testing when permit issuance isn't needed
pub struct NullPermitIssuer;

impl PermitIssuer for NullPermitIssuer {
    fn issue_layer_permit(
        &self,
        _audience: &str,
        _layer_name: &str,
        _config: gurkha::LayerConfig,
        _intent_cid: Option<&str>,
    ) -> Result<(String, String)> {
        Ok(("test-token".into(), "test-cid".into()))
    }

    fn list_layer_authority_permits_for_audience(
        &self,
        _audience: &str,
    ) -> Result<Vec<(String, u64, String)>> {
        Ok(Vec::new())
    }

    fn get_layer_authority_permit(
        &self,
        _audience: &str,
        _layer_name: &str,
    ) -> Result<Option<(u64, String)>> {
        Ok(None)
    }

    fn has_layer_access_permit(&self, _audience: &str, _layer_name: &str) -> Result<bool> {
        Ok(false)
    }

    fn issue_layer_authority_permit(
        &self,
        _audience: &str,
        _layer_name: &str,
        _config: gurkha::LayerConfig,
        _authorized_peers: Option<Vec<String>>,
        _version: u64,
    ) -> Result<(String, String)> {
        Ok(("test-authority-token".into(), "test-authority-cid".into()))
    }
}

