  1→//! Unified Scribe Bindings for Lua
  2→//!
  3→//! Provides a single `scribe` binding that replaces multiple separate bindings (loro, permit, peers).
  4→//! Apps interact with Scribe via this unified API for identity, layers, contacts, and ephemerals.
  5→//!
  6→//! ## API Reference
  7→//!
  8→//! ### Identity
  9→//! - `scribe:my_did()` - Get our DID
 10→//! - `scribe:my_name()` - Get our display name (from permit presence)
 11→//! - `scribe:page_id()` - Get current page ID
 12→//!
 13→//! ### Layers (CRDT)
 14→//! - `scribe:list(name)` - Get or create a list layer
 15→//! - `scribe:map(name)` - Get or create a map layer
 16→//!
 17→//! ### Bindings (Declarative Layer → UI Sync)
 18→//! - `scribe:bind(ui_property, layer_pattern, options?)` - Auto-sync layer to UI
 19→//!
 20→//! ### Contacts
 21→//! - `scribe:get_contacts()` - Get contents of /users layer (persistent contacts)
 22→//!
 23→//! ### Ephemerals
 24→//! - `scribe:send(func, args)` - Send structured ephemeral (permission-validated)
 25→
 26→use mlua::{Error as LuaError, Function, Lua, Result as LuaResult, Table, UserData, UserDataMethods, Value as LuaValue};
 27→use parking_lot::Mutex;
 28→use std::sync::Arc;
 29→use tokio::sync::mpsc;
 30→use tracing::{debug, info, warn};
 31→
 32→use crate::scribe_handle::ScribeHandle;
 33→
 34→use super::binding::{
 35→    expand_pattern, is_wildcard_pattern, process_binding_data, BindingManager, BindingOptions,
 36→};
 37→use super::convert::lua_to_json;
 38→use super::loro::{LuaLoroList, LuaLoroMap};
 39→use crate::ui_types::UiMutation;
 40→
 41→/// Unified Scribe bindings for Lua apps
 42→///
 43→/// Provides identity, layers, contacts, binding, and ephemeral functionality.
 44→pub struct ScribeBindings {
 45→    scribe: Arc<dyn ScribeHandle>,
 46→    page_id: String,
 47→    our_did: String,
 48→    our_name: Option<String>,
 49→    /// Binding manager for declarative layer → UI sync
 50→    binding_manager: Arc<Mutex<BindingManager>>,
 51→    /// UI mutation sender (if UI enabled)
 52→    ui_tx: Option<mpsc::Sender<UiMutation>>,
 53→    /// Whether UI is enabled
 54→    ui_enabled: bool,
 55→}
 56→
 57→impl ScribeBindings {
 58→    /// Create new ScribeBindings (no UI)
 59→    pub fn new(
 60→        scribe: Arc<dyn ScribeHandle>,
 61→        page_id: String,
 62→        our_did: String,
 63→        our_name: Option<String>,
 64→    ) -> Self {
 65→        Self {
 66→            scribe,
 67→            page_id,
 68→            our_did,
 69→            our_name,
 70→            binding_manager: Arc::new(Mutex::new(BindingManager::new())),
 71→            ui_tx: None,
 72→            ui_enabled: false,
 73→        }
 74→    }
 75→
 76→    /// Create ScribeBindings with UI support
 77→    pub fn with_ui(
 78→        scribe: Arc<dyn ScribeHandle>,
 79→        page_id: String,
 80→        our_did: String,
 81→        our_name: Option<String>,
 82→        ui_tx: mpsc::Sender<UiMutation>,
 83→    ) -> Self {
 84→        Self {
 85→            scribe,
 86→            page_id,
 87→            our_did,
 88→            our_name,
 89→            binding_manager: Arc::new(Mutex::new(BindingManager::new())),
 90→            ui_tx: Some(ui_tx),
 91→            ui_enabled: true,
 92→        }
 93→    }
 94→
 95→    /// Get reference to the binding manager
 96→    pub fn binding_manager(&self) -> Arc<Mutex<BindingManager>> {
 97→        self.binding_manager.clone()
 98→    }
 99→}
100→
101→impl UserData for ScribeBindings {
102→    fn add_methods<M: UserDataMethods<Self>>(methods: &mut M) {
103→
104→        // Get our DID
105→        //
106→        // Returns the DID (Decentralized Identifier) of the current user.
107→        // This is the unique identifier used in permit patterns and layer names.
108→        methods.add_method("my_did", |_, this, ()| Ok(this.our_did.clone()));
109→
110→        // Get the current page ID
111→        //
112→        // Returns the page ID this scribe instance is associated with.
113→        methods.add_method("page_id", |_, this, ()| Ok(this.page_id.clone()));
114→
115→        // Get our display name
116→        //
117→        // Returns the display name if available, or nil.
118→        methods.add_method("my_name", |_, this, ()| {
119→            Ok(this.our_name.clone())
120→        });
121→
122→        // Send structured ephemeral data
123→        //
124→        // Broadcasts ephemeral (non-persistent) data to all peers.
125→        // Used for typing indicators, cursor positions, game state, etc.
126→        methods.add_method("send", |_, this, (func, args): (String, LuaValue)| {
127→            let json_args = lua_to_json(&args)?;
128→
129→            let payload = serde_json::json!({
130→                "func": func,
131→                "args": json_args,
132→            });
133→
134→            let payload_bytes = serde_json::to_vec(&payload)
135→                .map_err(|e| LuaError::RuntimeError(format!("Failed to serialize ephemeral: {}", e)))?;
136→
137→            this.scribe.send_ephemeral(payload_bytes)
138→                .map_err(|e| LuaError::RuntimeError(format!("Failed to send ephemeral: {}", e)))?;
139→
140→            Ok(())
141→        });
142→
143→        // Create a dynamic layer from a schema pattern
144→        //
145→        // Creates a dynamic layer matching a schema defined in the permit's dynamic_layer_schemas.
146→        // The schema_key identifies the pattern (e.g., "channels/{id}/messages"),
147→        // and layer_id fills the {id} placeholder (e.g., "general").
148→        //
149→        // Returns a table with:
150→        //   - layer_name: The full layer name (e.g., "{page_id}/channels/{did}/general/messages")
151→        //
152→        // # Examples
153→        // ```lua
154→        // local result = scribe:create_layer("channels/{id}/messages", "general")
155→        // print(result.layer_name) -- "page1/channels/did:key:alice/general/messages"
156→        // local messages = scribe:list(result.layer_name)
157→        // messages:push({text = "Hello!"})
158→        // ```
159→        // Add a DID as participant to an explicit dynamic layer
160→        //
161→        // Grants access to a specific peer for a dynamic layer with explicit grant type.
162→        // The peer will receive a layer permit on their next subscription (or immediately if connected).
163→        //
164→        // # Examples
165→        // ```lua
166→        // scribe:add_layer_access("page1/dms/did:key:alice/dm1/messages", "did:key:bob")
167→        // ```
168→        methods.add_method("add_layer_access", |_, this, (layer_name, did): (String, String)| {
169→            this.scribe.add_layer_access(&layer_name, &did)
170→                .map_err(|e| LuaError::RuntimeError(format!("Failed to add layer access: {}", e)))?;
171→            Ok(())
172→        });
173→
174→        // Remove a DID from an explicit dynamic layer
175→        //
176→        // Revokes access for a specific peer from a dynamic layer with explicit grant type.
177→        //
178→        // # Examples
179→        // ```lua
180→        // scribe:remove_layer_access("page1/dms/did:key:alice/dm1/messages", "did:key:bob")
181→        // ```
182→        methods.add_method("remove_layer_access", |_, this, (layer_name, did): (String, String)| {
183→            this.scribe.remove_layer_access(&layer_name, &did)
184→                .map_err(|e| LuaError::RuntimeError(format!("Failed to remove layer access: {}", e)))?;
185→            Ok(())
186→        });
187→
188→        methods.add_method("create_layer", |lua, this, (schema_key, layer_id): (String, String)| {
189→            let layer_name = this.scribe.create_layer(&schema_key, &layer_id)
190→                .map_err(|e| LuaError::RuntimeError(format!("Failed to create dynamic layer: {}", e)))?;
191→
192→            let result = lua.create_table()?;
193→            result.set("layer_name", layer_name)?;
194→            Ok(result)
195→        });
196→
197→        // Get or create a list layer
198→        //
199→        // Returns a handle to the specified list layer, creating it if it doesn't exist.
200→        // The layer name can include the page_id, e.g., `scribe:list(page_id .. "/messages")`
201→        methods.add_method("list", |_, this, name: String| {
202→            this.scribe.ensure_list(&name)
203→                .map_err(|e| LuaError::RuntimeError(e))?;
204→            Ok(LuaLoroList::new(this.scribe.clone(), name))
205→        });
206→
207→        // Get or create a map layer
208→        //
209→        // Returns a handle to the specified map layer, creating it if it doesn't exist.
210→        methods.add_method("map", |_, this, name: String| {
211→            this.scribe.ensure_map(&name)
212→                .map_err(|e| LuaError::RuntimeError(e))?;
213→            Ok(LuaLoroMap::new(this.scribe.clone(), name))
214→        });
215→
216→        // List layers matching a pattern
217→        //
218→        // Returns a table of layer names matching the glob pattern.
219→        // Example: scribe:list_layers("*:orders") returns all order layers
220→        methods.add_method("list_layers", |lua, this, pattern: String| {
221→            let names = this.scribe.list_layers(&pattern)
222→                .map_err(|e| LuaError::RuntimeError(e))?;
223→
224→            let table = lua.create_table()?;
225→            for (i, name) in names.iter().enumerate() {
226→                table.set(i + 1, name.clone())?;
227→            }
228→            Ok(table)
229→        });
230→
231→        // Bind a layer pattern to a UI property (declarative sync)
232→        //
233→        // Automatically syncs layer data to UI property whenever the layer changes.
234→        // Supports transform, sort, and filter options.
235→        //
236→        // # Arguments
237→        // * `ui_property` - Name of the UI property/model to sync to
238→        // * `layer_pattern` - Layer pattern (page_id auto-prepended)
239→        // * `options` (optional) - Table with transform, sort, filter functions
240→        //
241→        // # Placeholders
242→        // * `{me}` - Expands to user's DID
243→        //
244→        // # Examples
245→        // ```lua
246→        // -- Simple binding
247→        // scribe:bind("products", "products")
248→        //
249→        // -- With transform and sort
250→        // scribe:bind("orders", "derived/orders_summary", {
251→        //     transform = function(item) return {id=item.id, name=item.name} end,
252→        //     sort = function(a, b) return a.created_at > b.created_at end
253→        // })
254→        //
255→        // -- {me} placeholder
256→        // scribe:bind("my_orders", "orders/{me}")
257→        //
258→        // -- Wildcard (aggregates matching layers)
259→        // scribe:bind("all_orders", "orders/*")
260→        // ```
261→        methods.add_method(
262→            "bind",
263→            |lua, this, (ui_property, layer_pattern, options): (String, String, Option<Table>)| {
264→                if !this.ui_enabled {
265→                    debug!(
266→                        ui_property = %ui_property,
267→                        layer_pattern = %layer_pattern,
268→                        "scribe:bind() called but UI not enabled, skipping"
269→                    );
270→                    return Ok(());
271→                }
272→
273→                // Expand placeholders in pattern
274→                let expanded_pattern = expand_pattern(&layer_pattern, &this.page_id, &this.our_did);
275→                let is_wildcard = is_wildcard_pattern(&layer_pattern);
276→
277→                info!(
278→                    ui_property = %ui_property,
279→                    raw_pattern = %layer_pattern,
280→                    expanded_pattern = %expanded_pattern,
281→                    is_wildcard = is_wildcard,
282→                    "scribe:bind() - registering binding"
283→                );
284→
285→                // Parse options
286→                // NOTE: sort is NOT supported - sorting is a Slint view concern
287→                // This enables surgical updates with stable indices
288→                let binding_options = if let Some(opts) = options {
289→                    let transform = opts
290→                        .get::<Function>("transform")
291→                        .ok()
292→                        .map(|f| lua.create_registry_value(f))
293→                        .transpose()
294→                        .map_err(|e| LuaError::RuntimeError(format!("Failed to store transform: {}", e)))?;
295→
296→                    let key = opts.get::<String>("key").ok();
297→                    let max_items = opts.get::<usize>("max_items").ok();
298→
299→                    BindingOptions {
300→                        transform,
301→                        key,
302→                        max_items,
303→                    }
304→                } else {
305→                    BindingOptions::default()
306→                };
307→
308→                // Register binding
309→                {
310→                    let mut manager = this.binding_manager.lock();
311→                    manager.register(
312→                        ui_property.clone(),
313→                        expanded_pattern.clone(),
314→                        layer_pattern.clone(),
315→                        is_wildcard,
316→                        binding_options,
317→                    );
318→                }
319→
320→                // Perform initial sync
321→                if is_wildcard {
322→                    // For wildcards, list matching layers and aggregate data
323→                    let layer_names = this.scribe.list_layers(&expanded_pattern)
324→                        .map_err(|e| LuaError::RuntimeError(e))?;
325→
326→                    let mut aggregated_data = Vec::new();
327→                    for name in &layer_names {
328→                        if let Ok(data) = fetch_layer_data(&this.scribe, name) {
329→                            if let serde_json::Value::Array(items) = data {
330→                                for item in items {
331→                                    aggregated_data.push(item);
332→                                }
333→                            }
334→                        }
335→                    }
336→
337→                    let aggregated_json = serde_json::Value::Array(aggregated_data);
338→                    sync_binding_to_ui(lua, this, &ui_property, &aggregated_json, None)?;
339→                } else {
340→                    // For exact patterns, fetch and sync single layer
341→                    if let Ok(data) = fetch_layer_data(&this.scribe, &expanded_pattern) {
342→                        sync_binding_to_ui(lua, this, &ui_property, &data, None)?;
343→                    }
344→                }
345→
346→                Ok(())
347→            },
348→        );
349→
350→        // Rebind an existing binding to a different layer
351→        //
352→        // Switches which layer backs a UI property while preserving
353→        // transform/key/max_items options. Clears caches and performs
354→        // a full initial sync from the new layer.
355→        //
356→        // # Arguments
357→        // * `ui_property` - Name of the existing binding to rebind
358→        // * `layer_pattern` - New layer pattern (page_id auto-prepended)
359→        //
360→        // # Examples
361→        // ```lua
362→        // -- Switch messages binding to a different channel
363→        // scribe:rebind("messages", "channels/random/messages")
364→        // ```
365→        methods.add_method(
366→            "rebind",
367→            |lua, this, (ui_property, layer_pattern): (String, String)| {
368→                if !this.ui_enabled {
369→                    debug!(
370→                        ui_property = %ui_property,
371→                        layer_pattern = %layer_pattern,
372→                        "scribe:rebind() called but UI not enabled, skipping"
373→                    );
374→                    return Ok(());
375→                }
376→
377→                let expanded_pattern = expand_pattern(&layer_pattern, &this.page_id, &this.our_did);
378→                let is_wildcard = is_wildcard_pattern(&layer_pattern);
379→
380→                info!(
381→                    ui_property = %ui_property,
382→                    raw_pattern = %layer_pattern,
383→                    expanded_pattern = %expanded_pattern,
384→                    is_wildcard = is_wildcard,
385→                    "scribe:rebind() - switching binding layer"
386→                );
387→
388→                // Rebind in the manager (preserves transform/key/max_items)
389→                {
390→                    let mut manager = this.binding_manager.lock();
391→                    if !manager.rebind(
392→                        &ui_property,
393→                        expanded_pattern.clone(),
394→                        layer_pattern.clone(),
395→                        is_wildcard,
396→                    ) {
397→                        return Err(LuaError::RuntimeError(format!(
398→                            "scribe:rebind() - no existing binding for '{}'",
399→                            ui_property
400→                        )));
401→                    }
402→                }
403→
404→                // Fetch and sync new layer's data
405→                if is_wildcard {
406→                    let layer_names = this.scribe.list_layers(&expanded_pattern)
407→                        .map_err(|e| LuaError::RuntimeError(e))?;
408→
409→                    let mut aggregated_data = Vec::new();
410→                    for name in &layer_names {
411→                        if let Ok(data) = fetch_layer_data(&this.scribe, name) {
412→                            if let serde_json::Value::Array(items) = data {
413→                                for item in items {
414→                                    aggregated_data.push(item);
415→                                }
416→                            }
417→                        }
418→                    }
419→
420→                    let aggregated_json = serde_json::Value::Array(aggregated_data);
421→                    sync_binding_to_ui(lua, this, &ui_property, &aggregated_json, None)?;
422→                } else {
423→                    if let Ok(data) = fetch_layer_data(&this.scribe, &expanded_pattern) {
424→                        sync_binding_to_ui(lua, this, &ui_property, &data, None)?;
425→                    }
426→                }
427→
428→                Ok(())
429→            },
430→        );
431→    }
432→}
433→
434→/// Fetch layer data as JSON from Scribe
435→fn fetch_layer_data(
436→    scribe: &Arc<dyn ScribeHandle>,
437→    layer_name: &str,
438→) -> Result<serde_json::Value, String> {
439→    match scribe.get_layer_json(layer_name)? {
440→        Some(data) => Ok(data),
441→        None => Ok(serde_json::Value::Array(vec![])),
442→    }
443→}
444→
445→/// Sync binding data to UI after processing through transform/sort/filter
446→fn sync_binding_to_ui(
447→    lua: &Lua,
448→    this: &ScribeBindings,
449→    ui_property: &str,
450→    data: &serde_json::Value,
451→    layer_name: Option<&str>,
452→) -> LuaResult<()> {
453→    let manager = this.binding_manager.lock();
454→
455→    if let Some(binding) = manager.get_binding(ui_property) {
456→        // Process through binding options
457→        let processed = process_binding_data(lua, binding, data, layer_name)?;
458→
459→        // Send to UI (skip if data_to_ui_mutation returns None for empty/null data)
460→        if let Some(ref ui_tx) = this.ui_tx {
461→            if let Some(mutation) = super::binding::data_to_ui_mutation(&this.page_id, ui_property, processed) {
462→                if let Err(e) = ui_tx.try_send(mutation) {
463→                    warn!(
464→                        ui_property = %ui_property,
465→                        error = %e,
466→                        "Failed to send binding UI mutation"
467→                    );
468→                } else {
469→                    debug!(
470→                        ui_property = %ui_property,
471→                        "Binding synced to UI"
472→                    );
473→                }
474→            }
475→        }
476→    }
477→
478→    Ok(())
479→}
