 89→    // Filter protocol layers from Lua/UI notifications
 90→    if crate::sync::sync_meta::is_protocol_layer(layer_name) {
 91→        debug!(layer = %layer_name, "Skipping notify_layer_discovered for protocol layer");
 92→        return;
 93→    }
 94→    let full_data = state.units.get(layer_name)
 95→        .map(|unit| unit.layer().get_content(layer_name))
 96→        .unwrap_or(serde_json::Value::Null);
 97→
 98→    let state_vector = state.units.get(layer_name)
 99→        .map(|unit| unit.layer().version_vector())
100→        .unwrap_or_default();

