112→use ractor::ActorRef;
113→use scribe::ScribeMessage;
114→use tokio::sync::oneshot;
115→
116→/// Helper: block_on an async oneshot that returns `Result<T, ScribeError>`,
117→/// flattening both channel errors and scribe errors to `String`.
118→fn rpc<T, E: std::fmt::Display>(rx: oneshot::Receiver<Result<T, E>>) -> Result<T, String> {
119→    let inner = match tokio::runtime::Handle::try_current() {
120→        Ok(handle) => tokio::task::block_in_place(|| handle.block_on(rx)),
121→        Err(_) => futures::executor::block_on(rx),
122→    };
123→    inner
124→        .map_err(|e| format!("Channel error: {}", e))?
125→        .map_err(|e| format!("{}", e))
126→}
127→
128→/// Helper: block_on an async oneshot that returns `T` directly (no inner Result)
129→fn rpc_direct<T>(rx: oneshot::Receiver<T>) -> Result<T, String> {
130→    let result = match tokio::runtime::Handle::try_current() {
131→        Ok(handle) => tokio::task::block_in_place(|| handle.block_on(rx)),
132→        Err(_) => futures::executor::block_on(rx),
133→    };
134→    result.map_err(|e| format!("Channel error: {}", e))
135→}
