1028→fn issue_layer_permit_for_subscribe(
1029→    state: &ScribeState,
1030→    peer_did: &str,
1031→    bare_layer_name: &str,
1032→    full_layer_name: &str,
1033→) -> std::result::Result<String, String> {
1034→    let issuer = state.permit_issuer.as_ref()
1035→        .ok_or_else(|| "No permit issuer (not node mode)".to_string())?;
1036→
1037→    // Check if permit already exists
1038→    if let Ok(true) = issuer.has_layer_access_permit(peer_did, full_layer_name) {
1039→        // Re-issue since we need the token to send back
1040→        // (has_layer_access_permit only checks existence)
1041→    }
1042→
1043→    // Try open-grant schema match
1044→    if let Some(ref our_permit) = state.our_permit {
1045→        if let Some((_schema_key, schema, _creator_did)) =
1046→            crate::layer_unit::find_matching_dynamic_schema(our_permit, bare_layer_name, &state.page_id)
1047→        {
1048→            let config = schema.permissions.clone();
1049→            match issuer.issue_layer_permit(peer_did, full_layer_name, config, None) {
1050→                Ok((token, _cid)) => return Ok(token),
1051→                Err(e) => {
1052→                    warn!(error = %e, layer = %full_layer_name, "Failed to issue permit via schema");
1053→                }
1054→            }
1055→        }
1056→    }
1057→
1058→    // Try static layer from our own permit
1059→    //
1060→    // **Context**: Static layers (app:Group Chat, channels/general/messages, etc.) are
1061→    // defined in the node's page permit. The peer's __sync_meta has entries for these
1062→    // but they're not dynamic schemas, so we issue a permit using our permit's config.
1063→    if let Some(ref our_permit) = state.our_permit {
1064→        if let Some(config) = our_permit.layers().get(full_layer_name) {
1065→            match issuer.issue_layer_permit(peer_did, full_layer_name, config.clone(), None) {
1066→                Ok((token, _cid)) => return Ok(token),
1067→                Err(e) => {
1068→                    warn!(error = %e, layer = %full_layer_name, "Failed to issue permit for static layer");
1069→                }
1070→            }
1071→        }
1072→    }
1073→
1074→    // Try explicit-grant authority permit
1075→    match issuer.get_layer_authority_permit(peer_did, full_layer_name) {
1076→        Ok(Some((_version, authority_token))) => {
1077→            if let Ok(authority_permit) = gurkha::Permit::from_token(&authority_token) {
1078→                let config = authority_permit.layers().get(full_layer_name)
1079→                    .or_else(|| authority_permit.layers().get(bare_layer_name));
1080→                if let Some(config) = config {
1081→                    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok();
1082→                    match issuer.issue_layer_permit(
1083→                        peer_did, full_layer_name, config.clone(), intent_cid.as_deref(),
1084→                    ) {
1085→                        Ok((token, _cid)) => return Ok(token),
1086→                        Err(e) => {
1087→                            warn!(error = %e, "Failed to issue permit from authority");
1088→                        }
1089→                    }
1090→                }
1091→            }
1092→        }
1093→        Ok(None) => {}
1094→        Err(e) => {
1095→            warn!(error = %e, "Error looking up authority permit");
1096→        }
1097→    }
1098→
1099→    Err(format!("Cannot issue layer permit for {} to {}", full_layer_name, peer_did))
1100→}
