1079→                    .or_else(|| authority_permit.layers().get(bare_layer_name));
1080→                if let Some(config) = config {
1081→                    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok();
1082→                    match issuer.issue_layer_permit(
1083→                        peer_did, full_layer_name, config.clone(), intent_cid.as_deref(),
1084→                    ) {
1085→                        Ok((token, _cid)) => return Ok(token),
1086→                        Err(e) => {
1087→                            warn!(error = %e, "Failed to issue permit from authority");
1088→                        }
1089→                    }
1090→                }
1091→            }
1092→        }
1093→        Ok(None) => {}
1094→        Err(e) => {
1095→            warn!(error = %e, "Error looking up authority permit");
1096→        }
1097→    }
1098→
1099→    Err(format!("Cannot issue layer permit for {} to {}", full_layer_name, peer_did))
