fn issue_layer_permit_for_subscribe(
    state: &ScribeState,
    peer_did: &str,
    bare_layer_name: &str,
    full_layer_name: &str,
) -> std::result::Result<String, String> {
    let issuer = state.permit_issuer.as_ref()
        .ok_or_else(|| "No permit issuer (not node mode)".to_string())?;

    // Check if permit already exists
    if let Ok(true) = issuer.has_layer_access_permit(peer_did, full_layer_name) {
        // Re-issue since we need the token to send back
        // (has_layer_access_permit only checks existence)
    }

    // Try open-grant schema match
    if let Some(ref our_permit) = state.our_permit {
        if let Some((_schema_key, schema, _creator_did)) =
            crate::layer_unit::find_matching_dynamic_schema(our_permit, bare_layer_name, &state.page_id)
        {
            let config = schema.permissions.clone();
            match issuer.issue_layer_permit(peer_did, full_layer_name, config, None) {
                Ok((token, _cid)) => return Ok(token),
                Err(e) => {
                    warn!(error = %e, layer = %full_layer_name, "Failed to issue permit via schema");
                }
            }
        }
    }

    // Try static layer from our own permit
    //
    // **Context**: Static layers (app:Group Chat, channels/general/messages, etc.) are
    // defined in the node's page permit. The peer's __sync_meta has entries for these
    // but they're not dynamic schemas, so we issue a permit using our permit's config.
    if let Some(ref our_permit) = state.our_permit {
        if let Some(config) = our_permit.layers().get(full_layer_name) {
            match issuer.issue_layer_permit(peer_did, full_layer_name, config.clone(), None) {
                Ok((token, _cid)) => return Ok(token),
                Err(e) => {
                    warn!(error = %e, layer = %full_layer_name, "Failed to issue permit for static layer");
                }
            }
        }
    }

    // Try explicit-grant authority permit
    match issuer.get_layer_authority_permit(peer_did, full_layer_name) {
        Ok(Some((_version, authority_token))) => {
            if let Ok(authority_permit) = gurkha::Permit::from_token(&authority_token) {
                let config = authority_permit.layers().get(full_layer_name)
                    .or_else(|| authority_permit.layers().get(bare_layer_name));
                if let Some(config) = config {
                    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok();
                    match issuer.issue_layer_permit(
                        peer_did, full_layer_name, config.clone(), intent_cid.as_deref(),
                    ) {
                        Ok((token, _cid)) => return Ok(token),
                        Err(e) => {
                            warn!(error = %e, "Failed to issue permit from authority");
                        }
                    }
                }
            }
        }
        Ok(None) => {}
        Err(e) => {
            warn!(error = %e, "Error looking up authority permit");
        }
    }

    Err(format!("Cannot issue layer permit for {} to {}", full_layer_name, peer_did))
}

