    let page_id = state.page_id.clone();

    // Collect all pending writes first, then apply
    let mut pending_writes: Vec<PendingMetaWrite> = Vec::new();

    for entry in &entries {
        if is_protocol_layer(&entry.layer_name) { continue; }

        let Some((_schema_key, schema, path_creator_did)) =
            find_matching_dynamic_schema(&our_permit, &entry.layer_name, &page_id)
        else {
            continue;
        };

        if path_creator_did != creator_did {
            // Expected: entries written by the node for discovery have a different
            // creator namespace. These are not new layers from this peer — skip silently.
            debug!(
                layer = %entry.layer_name,
                creator = %creator_did,
                path_creator = %path_creator_did,
                "Skipping non-owned __sync_meta entry (written by node for discovery)"
            );
            continue;
        }

        match schema.grant {
            gurkha::GrantType::Open => {
                for peer_did in &all_peer_dids {
                    let peer_entries = read_sync_meta_entries(state, peer_did);
                    let already_has = peer_entries.iter().any(|e| e.layer_name == entry.layer_name);
                    if !already_has {
                        pending_writes.push(PendingMetaWrite {
                            peer_did: peer_did.clone(),
                            layer_name: entry.layer_name.clone(),
                            synced: false,
                        });
                    }
                }
                if !entry.synced {
                    pending_writes.push(PendingMetaWrite {
                        peer_did: creator_did.to_string(),
                        layer_name: entry.layer_name.clone(),
                        synced: true,
                    });
                }
            }
            gurkha::GrantType::Explicit => {
                if let Some(ref issuer) = state.permit_issuer {
                    let full_layer_name = format!("{}/{}", page_id, entry.layer_name);
                    for peer_did in &all_peer_dids {
                        let has_authority = issuer
                            .get_layer_authority_permit(peer_did, &full_layer_name)
                            .ok()
                            .flatten()
                            .is_some();

                        if has_authority {
                            let peer_entries = read_sync_meta_entries(state, peer_did);
                            let already_has = peer_entries.iter().any(|e| e.layer_name == entry.layer_name);
                            if !already_has {
                                pending_writes.push(PendingMetaWrite {
                                    peer_did: peer_did.clone(),
                                    layer_name: entry.layer_name.clone(),
                                    synced: false,
                                });
                            }
                        }
                    }
                }
                if !entry.synced {
                    pending_writes.push(PendingMetaWrite {
                        peer_did: creator_did.to_string(),
                        layer_name: entry.layer_name.clone(),
                        synced: true,
                    });
                }
            }
        }
    }

    // Apply all pending writes
    for write in pending_writes {
        write_sync_meta_entry(state, &write.peer_did, &write.layer_name, write.synced);
        if !write.synced {
            info!(
                layer = %write.layer_name,
                peer_did = %write.peer_did,
                "Wrote dynamic entry to peer's __sync_meta"
            );
        }
    }
