pub fn populate_dynamic_layers_for_late_joiner(
    state: &mut ScribeState,
    peer_did: &str,
) {
    use crate::layer_unit::find_matching_dynamic_schema;

    // Clone our_permit to avoid borrowing state
    let our_permit = match state.our_permit.clone() {
        Some(p) => p,
        None => return,
    };
    if our_permit.dynamic_layer_schemas().is_empty() { return; }

    let page_id = state.page_id.clone();

    // Collect all sync_meta layers to scan
    let sync_meta_layers: Vec<(String, String)> = state
        .units
        .keys()
        .filter_map(|name| {
            if is_sync_meta_layer(name) {
                extract_peer_did(name).map(|did| (name.clone(), did.to_string()))
            } else {
                None
            }
        })
        .filter(|(_, did)| did != peer_did)
        .collect();

    let peer_entries = read_sync_meta_entries(state, peer_did);

    // Collect pending writes
    let mut pending_writes: Vec<PendingMetaWrite> = Vec::new();

    for (_meta_layer, creator_did) in &sync_meta_layers {
        let creator_entries = read_sync_meta_entries(state, creator_did);

        for entry in creator_entries {
            if is_protocol_layer(&entry.layer_name) { continue; }

            let Some((_key, schema, _path_creator)) =
                find_matching_dynamic_schema(&our_permit, &entry.layer_name, &page_id)
            else {
                continue;
            };

            let already_has = peer_entries.iter().any(|e| e.layer_name == entry.layer_name);
            if already_has { continue; }
            // Also check if already in pending_writes
            let already_pending = pending_writes.iter().any(|w| w.layer_name == entry.layer_name && w.peer_did == peer_did);
            if already_pending { continue; }

            match schema.grant {
                gurkha::GrantType::Open => {
                    pending_writes.push(PendingMetaWrite {
                        peer_did: peer_did.to_string(),
                        layer_name: entry.layer_name.clone(),
                        synced: false,
                    });
                }
                gurkha::GrantType::Explicit => {
                    if let Some(ref issuer) = state.permit_issuer {
                        let full_name = format!("{}/{}", page_id, entry.layer_name);
                        let has_authority = issuer
                            .get_layer_authority_permit(peer_did, &full_name)
                            .ok()
                            .flatten()
                            .is_some();
                        if has_authority {
                            pending_writes.push(PendingMetaWrite {
                                peer_did: peer_did.to_string(),
                                layer_name: entry.layer_name.clone(),
                                synced: false,
                            });
                        }
                    }
                }
            }
        }
    }

    // Apply all pending writes
    for write in pending_writes {
        write_sync_meta_entry(state, &write.peer_did, &write.layer_name, write.synced);
        info!(
            layer = %write.layer_name,
            peer_did = %write.peer_did,
            "Late joiner: wrote dynamic entry to __sync_meta"
        );
    }

