  1→//! Sync Metadata Protocol Layer
  2→//!
  3→//! Each peer has a `__sync_meta:{did}` layer that serves as:
  4→//! - **Discovery catalog**: what layers exist and should be synced
  5→//! - **Access intent**: who should get access to explicit-grant layers
  6→//! - **Sync status tracker**: what has been synced
  7→//!
  8→//! Contents are a Loro Map: `layer_name → synced (bool)`.
  9→//! - `false` = layer discovered but not yet synced
 10→//! - `true` = layer data has been synced
 11→//!
 12→//! Both the peer and the node write to the same CRDT doc.
 13→//! Concurrent writes merge naturally via Loro.
 14→
 15→use tracing::{debug, info, warn, instrument};
 16→
 17→use crate::layer_unit::LayerUnit;
 18→use crate::loro_observer;
 19→use crate::state::ScribeState;
 20→
 21→/// Prefix for sync metadata protocol layers
 22→pub const SYNC_META_PREFIX: &str = "__sync_meta:";
 23→
 24→/// Check if a layer name is a sync metadata protocol layer
 25→pub fn is_sync_meta_layer(name: &str) -> bool {
 26→    name.starts_with(SYNC_META_PREFIX)
 27→}
 28→
 29→/// Check if a layer name is any protocol-internal layer (filtered from Lua callbacks)
 30→pub fn is_protocol_layer(name: &str) -> bool {
 31→    is_sync_meta_layer(name)
 32→}
 33→
 34→/// Extract the peer DID from a sync metadata layer name
 35→///
 36→/// `__sync_meta:did:key:z6Mk...` → `Some("did:key:z6Mk...")`
 37→pub fn extract_peer_did(name: &str) -> Option<&str> {
 38→    name.strip_prefix(SYNC_META_PREFIX)
 39→}
 40→
 41→/// Build the sync metadata layer name for a peer
 42→pub fn sync_meta_layer_name(peer_did: &str) -> String {
 43→    format!("{}{}", SYNC_META_PREFIX, peer_did)
 44→}
 45→
 46→/// A single entry in a __sync_meta layer
 47→#[derive(Debug, Clone)]
 48→pub struct SyncMetaEntry {
 49→    /// Bare layer name (no page_id prefix)
 50→    pub layer_name: String,
 51→    /// Whether the layer data has been synced
 52→    pub synced: bool,
 53→}
 54→
 55→/// Create or get the __sync_meta layer for a peer
 56→///
 57→/// **Context**: Called on node when a peer subscribes, or on peer for their own layer.
 58→/// Creates the LayerUnit if it doesn't exist, sets up observer.
 59→#[instrument(skip(state), fields(page_id = %state.page_id))]
 60→pub fn ensure_sync_meta_layer(state: &mut ScribeState, peer_did: &str) -> String {
 61→    let layer_name = sync_meta_layer_name(peer_did);
 62→
 63→    if !state.units.contains_key(&layer_name) {
 64→        let mut unit = LayerUnit::new_empty();
 65→        // sync_meta layers DO sync (they're not local-only)
 66→        unit.set_local_only(false);
 67→        state.units.insert(layer_name.clone(), unit);
 68→
 69→        // Set up observer so changes propagate
 70→        loro_observer::setup_layer_observer(state, &layer_name);
 71→
 72→        info!(layer = %layer_name, peer_did = %peer_did, "Created __sync_meta layer");
 73→    }
 74→
 75→    layer_name
 76→}
 77→
 78→/// Write an entry to a peer's __sync_meta layer
 79→///
 80→/// **Context**: Node writes entries for layers the peer should discover.
 81→/// Peer writes entries for layers they've created locally.
 82→#[instrument(skip(state), fields(page_id = %state.page_id, peer_did = %peer_did))]
 83→pub fn write_sync_meta_entry(
 84→    state: &mut ScribeState,
 85→    peer_did: &str,
 86→    layer_name: &str,
 87→    synced: bool,
 88→) {
 89→    let meta_layer = sync_meta_layer_name(peer_did);
 90→
 91→    // Auto-create the layer if it doesn't exist
 92→    if !state.units.contains_key(&meta_layer) {
 93→        ensure_sync_meta_layer(state, peer_did);
 94→    }
 95→
 96→    let Some(unit) = state.units.get(&meta_layer) else {
 97→        warn!(
 98→            meta_layer = %meta_layer,
 99→            layer = %layer_name,
100→            "Cannot write sync_meta entry: layer creation failed"
101→        );
102→        return;
103→    };
104→
105→    let map = unit.layer().loro().get_map(meta_layer.as_str());
106→    let value = if synced {
107→        loro::LoroValue::Bool(true)
108→    } else {
109→        loro::LoroValue::Bool(false)
110→    };
111→
112→    if let Err(e) = map.insert(layer_name, value) {
113→        warn!(
114→            meta_layer = %meta_layer,
115→            entry = %layer_name,
116→            error = %e,
117→            "Failed to write sync_meta entry"
118→        );
119→        return;
120→    }
121→
122→    unit.layer().commit();
123→
124→    if let Some(unit) = state.units.get_mut(&meta_layer) {
125→        unit.mark_dirty();
126→    }
127→
128→    debug!(
129→        meta_layer = %meta_layer,
130→        entry = %layer_name,
131→        synced = synced,
132→        "Wrote sync_meta entry"
133→    );
134→}
135→
136→/// Read all entries from a peer's __sync_meta layer
137→///
138→/// **Returns**: Vec of (layer_name, synced) entries
139→pub fn read_sync_meta_entries(state: &ScribeState, peer_did: &str) -> Vec<SyncMetaEntry> {
140→    let meta_layer = sync_meta_layer_name(peer_did);
141→    let Some(unit) = state.units.get(&meta_layer) else {
142→        return Vec::new();
143→    };
144→
145→    let map = unit.layer().loro().get_map(meta_layer.as_str());
146→    let mut entries = Vec::new();
147→
148→    for key in map.keys() {
149→        let synced = map
150→            .get(&key)
151→            .and_then(|v| {
152→                let deep = v.get_deep_value();
153→                if let loro::LoroValue::Bool(b) = deep {
154→                    Some(b)
155→                } else {
156→                    None
157→                }
158→            })
159→            .unwrap_or(false);
160→
161→        entries.push(SyncMetaEntry {
162→            layer_name: key.to_string(),
163→            synced,
164→        });
165→    }
166→
167→    entries
168→}
169→
170→/// Read unsynced entries (synced == false) from a peer's __sync_meta layer
171→pub fn read_unsynced_entries(state: &ScribeState, peer_did: &str) -> Vec<String> {
172→    read_sync_meta_entries(state, peer_did)
173→        .into_iter()
174→        .filter(|e| !e.synced)
175→        .map(|e| e.layer_name)
176→        .collect()
177→}
178→
179→/// Mark a sync_meta entry as synced (true)
180→#[instrument(skip(state), fields(page_id = %state.page_id))]
181→pub fn mark_entry_synced(state: &mut ScribeState, peer_did: &str, layer_name: &str) {
182→    write_sync_meta_entry(state, peer_did, layer_name, true);
183→}
184→
185→/// Populate a peer's __sync_meta with static layer entries
186→///
187→/// **Context**: Node calls this after creating the peer's __sync_meta layer.
188→/// Writes entries for all static layers the peer has access to.
189→/// Owner gets entries marked `true` (already has data), viewers get `false`.
190→#[instrument(skip(state), fields(page_id = %state.page_id, peer_did = %peer_did))]
191→pub fn populate_static_layers(
192→    state: &mut ScribeState,
193→    peer_did: &str,
194→    peer_permit: &gurkha::Permit,
195→    is_owner: bool,
196→) {
197→    let static_layers = peer_permit.static_layers(&state.page_id, peer_did);
198→
199→    for layer_name in &static_layers {
200→        if is_protocol_layer(layer_name) {
201→            continue;
202→        }
203→        let synced = is_owner;
204→        write_sync_meta_entry(state, peer_did, layer_name, synced);
205→    }
206→
207→    info!(
208→        peer_did = %peer_did,
209→        entry_count = static_layers.len(),
210→        is_owner = is_owner,
211→        "Populated static layers in __sync_meta"
212→    );
213→}
214→
215→/// Describes a write action to perform on a peer's __sync_meta layer
216→struct PendingMetaWrite {
217→    peer_did: String,
218→    layer_name: String,
219→    synced: bool,
220→}
221→
222→/// Node-side: process updates to a creator's __sync_meta layer
223→///
224→/// **Context**: Node observes changes in a peer's __sync_meta. For each new entry:
225→/// - Check if it matches a dynamic schema
226→/// - Open grant: write entry to ALL other peers' __sync_meta
227→/// - Explicit grant: read permit audience, write to target peer's __sync_meta only
228→///
229→/// **Note**: This is called after the __sync_meta layer is updated via CRDT sync.
230→#[instrument(skip(state), fields(page_id = %state.page_id, creator_did = %creator_did))]
231→pub fn process_creator_sync_meta(
232→    state: &mut ScribeState,
233→    creator_did: &str,
234→) {
235→    use crate::layer_unit::find_matching_dynamic_schema;
236→
237→    // Clone our_permit to avoid borrowing state
238→    let our_permit = match state.our_permit.clone() {
239→        Some(p) => p,
240→        None => return,
241→    };
242→    if our_permit.dynamic_layer_schemas().is_empty() { return; }
243→
244→    // Read all entries from creator's __sync_meta (snapshot, no borrow held after)
245→    let entries = read_sync_meta_entries(state, creator_did);
246→
247→    // Collect all peer DIDs (excluding creator)
248→    let all_peer_dids: Vec<String> = {
249→        let mut dids = Vec::new();
250→        if let Ok(subs) = state.subscribers.read() {
251→            for ((did, _), _) in subs.iter() {
252→                if did != creator_did && !dids.contains(did) {
253→                    dids.push(did.clone());
254→                }
255→            }
256→        }
257→        dids
258→    };
259→
260→    let page_id = state.page_id.clone();
261→
262→    // Collect all pending writes first, then apply
263→    let mut pending_writes: Vec<PendingMetaWrite> = Vec::new();
264→
265→    for entry in &entries {
266→        if is_protocol_layer(&entry.layer_name) { continue; }
267→
268→        let Some((_schema_key, schema, path_creator_did)) =
269→            find_matching_dynamic_schema(&our_permit, &entry.layer_name, &page_id)
270→        else {
271→            continue;
272→        };
273→
274→        if path_creator_did != creator_did {
275→            // Expected: entries written by the node for discovery have a different
276→            // creator namespace. These are not new layers from this peer — skip silently.
277→            debug!(
278→                layer = %entry.layer_name,
279→                creator = %creator_did,
280→                path_creator = %path_creator_did,
281→                "Skipping non-owned __sync_meta entry (written by node for discovery)"
282→            );
283→            continue;
284→        }
285→
286→        match schema.grant {
287→            gurkha::GrantType::Open => {
288→                for peer_did in &all_peer_dids {
289→                    let peer_entries = read_sync_meta_entries(state, peer_did);
290→                    let already_has = peer_entries.iter().any(|e| e.layer_name == entry.layer_name);
291→                    if !already_has {
292→                        pending_writes.push(PendingMetaWrite {
293→                            peer_did: peer_did.clone(),
294→                            layer_name: entry.layer_name.clone(),
295→                            synced: false,
296→                        });
297→                    }
298→                }
299→                if !entry.synced {
300→                    pending_writes.push(PendingMetaWrite {
301→                        peer_did: creator_did.to_string(),
302→                        layer_name: entry.layer_name.clone(),
303→                        synced: true,
304→                    });
305→                }
306→            }
307→            gurkha::GrantType::Explicit => {
308→                if let Some(ref issuer) = state.permit_issuer {
309→                    let full_layer_name = format!("{}/{}", page_id, entry.layer_name);
310→                    for peer_did in &all_peer_dids {
311→                        let has_authority = issuer
312→                            .get_layer_authority_permit(peer_did, &full_layer_name)
313→                            .ok()
314→                            .flatten()
315→                            .is_some();
316→
317→                        if has_authority {
318→                            let peer_entries = read_sync_meta_entries(state, peer_did);
319→                            let already_has = peer_entries.iter().any(|e| e.layer_name == entry.layer_name);
320→                            if !already_has {
321→                                pending_writes.push(PendingMetaWrite {
322→                                    peer_did: peer_did.clone(),
323→                                    layer_name: entry.layer_name.clone(),
324→                                    synced: false,
325→                                });
326→                            }
327→                        }
328→                    }
329→                }
330→                if !entry.synced {
331→                    pending_writes.push(PendingMetaWrite {
332→                        peer_did: creator_did.to_string(),
333→                        layer_name: entry.layer_name.clone(),
334→                        synced: true,
335→                    });
336→                }
337→            }
338→        }
339→    }
340→
341→    // Apply all pending writes
342→    for write in pending_writes {
343→        write_sync_meta_entry(state, &write.peer_did, &write.layer_name, write.synced);
344→        if !write.synced {
345→            info!(
346→                layer = %write.layer_name,
347→                peer_did = %write.peer_did,
348→                "Wrote dynamic entry to peer's __sync_meta"
349→            );
350→        }
351→    }
352→}
353→
354→/// Populate a late joiner's __sync_meta with existing dynamic layer entries
355→///
356→/// **Context**: New peer connects after dynamic layers already exist.
357→/// Node scans all existing __sync_meta layers to find layers the new peer
358→/// should discover.
359→#[instrument(skip(state), fields(page_id = %state.page_id, peer_did = %peer_did))]
360→pub fn populate_dynamic_layers_for_late_joiner(
361→    state: &mut ScribeState,
362→    peer_did: &str,
363→) {
364→    use crate::layer_unit::find_matching_dynamic_schema;
365→
366→    // Clone our_permit to avoid borrowing state
367→    let our_permit = match state.our_permit.clone() {
368→        Some(p) => p,
369→        None => return,
370→    };
371→    if our_permit.dynamic_layer_schemas().is_empty() { return; }
372→
373→    let page_id = state.page_id.clone();
374→
375→    // Collect all sync_meta layers to scan
376→    let sync_meta_layers: Vec<(String, String)> = state
377→        .units
378→        .keys()
379→        .filter_map(|name| {
380→            if is_sync_meta_layer(name) {
381→                extract_peer_did(name).map(|did| (name.clone(), did.to_string()))
382→            } else {
383→                None
384→            }
385→        })
386→        .filter(|(_, did)| did != peer_did)
387→        .collect();
388→
389→    let peer_entries = read_sync_meta_entries(state, peer_did);
390→
391→    // Collect pending writes
392→    let mut pending_writes: Vec<PendingMetaWrite> = Vec::new();
393→
394→    for (_meta_layer, creator_did) in &sync_meta_layers {
395→        let creator_entries = read_sync_meta_entries(state, creator_did);
396→
397→        for entry in creator_entries {
398→            if is_protocol_layer(&entry.layer_name) { continue; }
399→
400→            let Some((_key, schema, _path_creator)) =
401→                find_matching_dynamic_schema(&our_permit, &entry.layer_name, &page_id)
402→            else {
403→                continue;
404→            };
405→
406→            let already_has = peer_entries.iter().any(|e| e.layer_name == entry.layer_name);
407→            if already_has { continue; }
408→            // Also check if already in pending_writes
409→            let already_pending = pending_writes.iter().any(|w| w.layer_name == entry.layer_name && w.peer_did == peer_did);
410→            if already_pending { continue; }
411→
412→            match schema.grant {
413→                gurkha::GrantType::Open => {
414→                    pending_writes.push(PendingMetaWrite {
415→                        peer_did: peer_did.to_string(),
416→                        layer_name: entry.layer_name.clone(),
417→                        synced: false,
418→                    });
419→                }
420→                gurkha::GrantType::Explicit => {
421→                    if let Some(ref issuer) = state.permit_issuer {
422→                        let full_name = format!("{}/{}", page_id, entry.layer_name);
423→                        let has_authority = issuer
424→                            .get_layer_authority_permit(peer_did, &full_name)
425→                            .ok()
426→                            .flatten()
427→                            .is_some();
428→                        if has_authority {
429→                            pending_writes.push(PendingMetaWrite {
430→                                peer_did: peer_did.to_string(),
431→                                layer_name: entry.layer_name.clone(),
432→                                synced: false,
433→                            });
434→                        }
435→                    }
436→                }
437→            }
438→        }
439→    }
440→
441→    // Apply all pending writes
442→    for write in pending_writes {
443→        write_sync_meta_entry(state, &write.peer_did, &write.layer_name, write.synced);
444→        info!(
445→            layer = %write.layer_name,
446→            peer_did = %write.peer_did,
447→            "Late joiner: wrote dynamic entry to __sync_meta"
448→        );
449→    }
450→}
451→
452→#[cfg(test)]
453→mod tests {
454→    use super::*;
455→    use std::collections::HashMap;
456→    use std::sync::{Arc, Mutex};
457→    use std::sync::atomic::AtomicU64;
458→
459→    use crate::storage::{
460→        NullLayerStorage, NullPeerVectorStorage, NullPermitIssuer,
461→        LayerStorageRef, PeerVectorStorageRef, PermitIssuerRef,
462→    };
463→
464→    fn make_test_state() -> ScribeState {
465→        ScribeState {
