  1→//! Broadcast handling for Scribe actor
  2→
  3→use tokio::sync::mpsc;
  4→use tracing::{debug, info, instrument, warn};
  5→
  6→use crate::message::{BroadcastPayload, PageUpdate};
  7→use crate::state::ScribeState;
  8→
  9→/// Broadcast layer update to all layer subscribers (excludes sender)
 10→///
 11→/// Uses LayerUnit's per-subscriber state for authorization, version vectors,
 12→/// and broadcast channels. Disconnected subscribers are removed from the unit.
 13→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
 14→pub async fn broadcast_update(
 15→    state: &mut ScribeState,
 16→    layer_name: &str,
 17→    from_peer: Option<&(String, String)>,
 18→) {
 19→    let Some(unit) = state.units.get(layer_name) else {
 20→        return;
 21→    };
 22→
 23→    let current_vector = unit.layer().version_vector();
 24→    let layer = unit.layer().clone();
 25→    let sender_did = from_peer.map(|(did, _)| did.as_str());
 26→
 27→    let mut to_remove: Vec<String> = Vec::new();
 28→
 29→    if let Ok(mut layer_subs) = unit.subscribers().write() {
 30→        for (did, sub) in layer_subs.iter_mut() {
 31→            // Skip sender
 32→            if sender_did == Some(did.as_str()) {
 33→                state.emit_broadcast_decision_capture(layer_name, did, "skip_sender");
 34→                continue;
 35→            }
 36→
 37→            if !sub.capabilities.read {
 38→                state.emit_broadcast_decision_capture(layer_name, did, "no_read_capability");
 39→                continue;
 40→            }
 41→
 42→            let update = if !sub.version_vector.is_empty() {
 43→                layer.export_updates(&sub.version_vector)
 44→                    .unwrap_or_else(|_| layer.export_snapshot())
 45→            } else {
 46→                layer.export_snapshot()
 47→            };
 48→
 49→            let payload = BroadcastPayload {
 50→                page_id: state.page_id.clone(),
 51→                layer_name: layer_name.to_string(),
 52→                layer_type: domains::LayerType::from_layer_name(layer_name),
 53→                update,
 54→                state_vector: current_vector.clone(),
 55→            };
 56→
 57→            match sub.broadcast_tx.try_send(payload) {
 58→                Ok(()) => {
 59→                    sub.version_vector = current_vector.clone();
 60→                }
 61→                Err(mpsc::error::TrySendError::Closed(_)) => {
 62→                    info!(user_did = %did, "Layer subscriber disconnected, removing");
 63→                    to_remove.push(did.clone());
 64→                }
 65→                Err(mpsc::error::TrySendError::Full(_)) => {
 66→                    warn!(user_did = %did, "Broadcast channel full, update dropped");
 67→                }
 68→            }
 69→        }
 70→
 71→        for did in &to_remove {
 72→            layer_subs.remove(did);
 73→            debug!(user_did = %did, layer = %layer_name, "Removed disconnected layer subscriber");
 74→        }
 75→    }
 76→
 77→    super::reconcile::emit_sync_events_for_missing_targets(state);
 78→}
 79→
 80→// Page Update Emission
 81→
 82→/// Notify page event subscribers of new layer discovery
 83→///
 84→/// **Context**: A new layer was created (from peer sync or local creation)
 85→/// **We do**: Send PageUpdate::LayerChanged with created=true to unified subscribers
 86→/// **Filters**: Protocol layers (__sync_meta:*) are not sent to Lua/UI subscribers
 87→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
 88→pub fn notify_layer_discovered(state: &ScribeState, layer_name: &str) {
 89→    // Filter protocol layers from Lua/UI notifications
 90→    if crate::sync::sync_meta::is_protocol_layer(layer_name) {
 91→        debug!(layer = %layer_name, "Skipping notify_layer_discovered for protocol layer");
 92→        return;
 93→    }
 94→    let full_data = state.units.get(layer_name)
 95→        .map(|unit| unit.layer().get_content(layer_name))
 96→        .unwrap_or(serde_json::Value::Null);
 97→
 98→    let state_vector = state.units.get(layer_name)
 99→        .map(|unit| unit.layer().version_vector())
100→        .unwrap_or_default();
101→
102→    let update = PageUpdate::LayerChanged {
103→        layer: layer_name.to_string(),
104→        from_peer: None,
105→        ops: None,
106→        delta: None,
107→        state_vector: state_vector.clone(),
108→        full_data: Some(full_data.clone()),
109→        created: true,
110→    };
111→    state.emit_page_update_capture(&update);
112→    if let Ok(subs) = state.page_update_subscribers.read() {
113→        for tx in subs.iter() {
114→            let _ = tx.try_send(update.clone());
115→        }
116→    }
117→}
