272→// Startup Observer Setup
273→
274→/// Set up Loro observers for all layers at Scribe startup
275→///
276→/// **Context**: Called from `pre_start` to ensure observers are ready before any updates
277→/// **Why**: Loro's `import()` triggers observers automatically, so we need them set up
278→/// **Handles**: Peer broadcasts (to subscribers) + UI notifications (to loro_observers)
279→///
280→/// This ensures both local changes (via commit) and remote changes (via import)
281→/// go through the same observer-based notification path.
282→#[instrument(skip_all, fields(page_id = %state.page_id))]
283→pub fn setup_observers_for_all_layers(state: &mut ScribeState) {
284→    let layer_names: Vec<String> = state.units.keys().cloned().collect();
285→
286→    for layer_name in layer_names {
287→        setup_layer_observer(state, &layer_name);
288→    }
289→
290→    let observer_count = state.units.values().filter(|u| u.has_observer()).count();
291→    info!(
292→        page_id = %state.page_id,
293→        layer_count = observer_count,
294→        "Set up Loro observers for all layers"
295→    );
296→}
297→
298→/// Set up Loro observer for a single layer
299→///
300→/// **Context**: Sets up the observer infrastructure for peer broadcasts and UI notifications
301→/// **Observer fires**: On commit() AND import() - both trigger subscribe_root
302→///
303→/// **Public**: Called from mod.rs when new layers are dynamically created
304→#[instrument(skip(state), fields(page_id = %state.page_id))]
305→pub fn setup_layer_observer(state: &mut ScribeState, layer_name: &str) {
306→    // Skip if already set up
307→    match state.units.get(layer_name) {
308→        Some(u) if u.has_observer() => return,
309→        Some(_) => {}
310→        None => {
311→            warn!(layer_name = %layer_name, "Layer not found for observer setup");
312→            return;
313→        }
314→    };
315→
316→    // We need to get the layer clone and is_local_only before borrowing state mutably
317→    let (layer_clone, is_local_only) = {
318→        let unit = state.units.get(layer_name).unwrap();
319→        (unit.layer().clone(), unit.is_local_only())
320→    };
321→
322→    // Create internal channel for observer signals (includes ops for reactive bindings)
323→    let (signal_tx, mut signal_rx) = tokio::sync::mpsc::unbounded_channel::<ObserverSignal>();
324→
325→    // Clone for the async task
326→    let layer_for_task = layer_clone.clone();
327→    let layer_name_for_task = layer_name.to_string();
328→    let page_id_for_task = state.page_id.clone();
329→    let page_update_subscribers_for_task = state.page_update_subscribers.clone();
330→    // Capture LayerUnit's subscriber map for broadcast filtering and sending
331→    let layer_subscribers_for_task = state.units.get(layer_name).unwrap().subscribers().clone();
332→    // Clone capture_tx for the observer task
333→    let capture_tx_for_task = state.capture_tx.clone();
334→
335→    // Clone pending_update_source for the synchronous callback
336→    let pending_update_source = state.pending_update_source.clone();
337→
338→    // Spawn async task to handle observer signals
339→    // Note: Derivation is handled in handle_apply_update using ops, not here
340→    tokio::spawn(async move {
341→        while let Some(signal) = signal_rx.recv().await {
342→            let state_vector = layer_for_task.version_vector();
343→
344→            // Prepare ops for reactive bindings (Some if non-empty, None otherwise)
345→            let ops = if signal.ops.is_empty() { None } else { Some(signal.ops) };
346→
347→            // Skip expensive get_content() only for List deltas (surgical conversion always works).
348→            // For Map/Text deltas, always provide full_data so non-keyed Map bindings can
349→            // fall back to Replace when delta conversion returns empty.
350→            let full_data = if matches!(&signal.delta, Some(LoroDelta::List { .. })) {
351→                None
352→            } else {
353→                Some(layer_for_task.get_content(&layer_name_for_task))
354→            };
355→
356→            let page_update = PageUpdate::LayerChanged {
357→                layer: layer_name_for_task.clone(),
358→                from_peer: None,  // Local change
359→                ops,
360→                delta: signal.delta,
361→                state_vector,
362→                full_data,
363→                created: false,
364→            };
365→            // Emit to capture channel (pre-serialized JSON line)
366→            if let Some(ref capture_tx) = capture_tx_for_task {
367→                let ts = std::time::SystemTime::now()
368→                    .duration_since(std::time::UNIX_EPOCH)
369→                    .map(|d| d.as_millis())
370→                    .unwrap_or(0);
371→                if let Ok(json) = serde_json::to_string(&serde_json::json!({
372→                    "type": "page_update",
373→                    "ts": ts,
374→                    "page_id": &page_id_for_task,
375→                    "data": &page_update,
376→                })) {
377→                    let _ = capture_tx.send(json);
378→                }
379→            }
380→            // Filter protocol layers from Lua/UI callbacks
381→            if !crate::sync::sync_meta::is_protocol_layer(&layer_name_for_task) {
382→                if let Ok(subs) = page_update_subscribers_for_task.read() {
383→                    for tx in subs.iter() {
384→                        let _ = tx.try_send(page_update.clone());
385→                    }
386→                    if !subs.is_empty() {
387→                        debug!(
388→                            layer_name = %layer_name_for_task,
389→                            subscriber_count = subs.len(),
390→                            "Sent PageUpdate::LayerChanged"
391→                        );
392→                    }
393→                }
394→            }
395→
396→            // Check if layer is local-only (sync: false in permit)
397→            // Captured as bool at observer setup time — static per layer
398→            if is_local_only {
399→                if let Some(ref ctx) = capture_tx_for_task {
400→                    let ts = std::time::SystemTime::now()
401→                        .duration_since(std::time::UNIX_EPOCH)
402→                        .map(|d| d.as_millis())
403→                        .unwrap_or(0);
404→                    let _ = ctx.send(serde_json::json!({
405→                        "type": "broadcast_decision",
406→                        "ts": ts,
407→                        "page_id": &page_id_for_task,
408→                        "layer": &layer_name_for_task,
409→                        "decision": "skip",
410→                        "reason": "local_only",
411→                    }).to_string());
412→                }
413→                debug!(
414→                    layer_name = %layer_name_for_task,
415→                    "Skipping peer broadcast for local-only layer (sync: false)"
416→                );
417→                continue;
418→            }
419→
420→            // Skip peer broadcast for remote updates (sender exclusion)
421→            // Remote updates are forwarded via broadcast_update() in apply.rs which has proper sender exclusion
422→            // Broadcasting here would send the update back to the original sender, causing a sync storm
423→            if signal.from_peer.is_some() {
424→                if let Some(ref ctx) = capture_tx_for_task {
425→                    let ts = std::time::SystemTime::now()
426→                        .duration_since(std::time::UNIX_EPOCH)
427→                        .map(|d| d.as_millis())
428→                        .unwrap_or(0);
429→                    let _ = ctx.send(serde_json::json!({
430→                        "type": "broadcast_decision",
431→                        "ts": ts,
432→                        "page_id": &page_id_for_task,
433→                        "layer": &layer_name_for_task,
434→                        "decision": "skip",
435→                        "reason": "remote_handled_by_apply",
436→                    }).to_string());
437→                }
438→                debug!(
439→                    layer_name = %layer_name_for_task,
440→                    "Skipping observer peer broadcast for remote update (handled by broadcast_update)"
441→                );
442→                continue;
443→            }
444→
445→            // Broadcast incremental updates to layer subscribers
446→            // Uses per-subscriber version_vector for incremental export
447→            let current_vector = layer_for_task.version_vector();
448→
449→            if let Ok(layer_subs) = layer_subscribers_for_task.read() {
450→                info!(
451→                    page_id = %page_id_for_task,
452→                    layer_name = %layer_name_for_task,
453→                    subscriber_count = layer_subs.len(),
454→                    "Observer broadcasting local write to layer subscribers"
455→                );
456→                for (did, sub) in layer_subs.iter() {
457→                    // Check read capability (replaces authorized_dids check)
458→                    if !sub.capabilities.read {
459→                        if let Some(ref ctx) = capture_tx_for_task {
460→                            let ts = std::time::SystemTime::now()
461→                                .duration_since(std::time::UNIX_EPOCH)
462→                                .map(|d| d.as_millis())
463→                                .unwrap_or(0);
464→                            let _ = ctx.send(serde_json::json!({
465→                                "type": "broadcast_decision",
466→                                "ts": ts,
467→                                "page_id": &page_id_for_task,
468→                                "layer": &layer_name_for_task,
469→                                "peer_did": did,
470→                                "decision": "skip",
471→                                "reason": "no_read_capability",
472→                            }).to_string());
473→                        }
474→                        continue;
475→                    }
476→
477→                    // Incremental export: use subscriber's last known vector
478→                    // Falls back to full snapshot for first sync (no vector cached)
479→                    let update = if !sub.version_vector.is_empty() {
480→                        layer_for_task.export_updates(&sub.version_vector)
481→                            .unwrap_or_else(|_| layer_for_task.export_snapshot())
482→                    } else {
483→                        layer_for_task.export_snapshot()
484→                    };
485→
486→                    let update_size = update.len();
487→                    let payload = BroadcastPayload {
488→                        page_id: page_id_for_task.clone(),
489→                        layer_name: layer_name_for_task.clone(),
490→                        layer_type: domains::LayerType::from_layer_name(&layer_name_for_task),
491→                        update,
492→                        state_vector: current_vector.clone(),
493→                    };
494→
495→                    match sub.broadcast_tx.try_send(payload) {
496→                        Ok(()) => {
497→                            debug!(
498→                                user_did = %did,
499→                                layer_name = %layer_name_for_task,
500→                                update_size = update_size,
501→                                "Sent incremental broadcast to layer subscriber"
502→                            );
503→                        }
504→                        Err(mpsc::error::TrySendError::Full(_)) => {
505→                            warn!(user_did = %did, "Peer broadcast channel full");
506→                        }
507→                        Err(mpsc::error::TrySendError::Closed(_)) => {
508→                            warn!(user_did = %did, layer_name = %layer_name_for_task, "Peer broadcast channel closed — receiver dropped");
509→                        }
510→                    }
511→                }
512→            }
513→        }
514→        debug!(layer_name = %layer_name_for_task, "Observer task ended");
515→    });
516→
517→    // Subscribe to Loro changes - extract ops and delta for reactive bindings
518→    let subscription = layer_clone.subscribe_root(move |diff_event: loro::event::DiffEvent| {
519→        // Extract structured ops for reactive Lua bindings (surgical UI updates)
520→        let ops = diff_event_to_ops(&diff_event);
521→
522→        // Extract delta for legacy VecModel operations
523→        let delta = diff_event.events.first()
524→            .and_then(|container_diff| convert_loro_diff_to_delta(&container_diff.diff));
525→
526→        // Read pending_update_source to determine if this is a remote update
527→        // Remote updates should not trigger peer broadcast (handled by broadcast_update with sender exclusion)
528→        let from_peer = pending_update_source.lock().ok().and_then(|g| g.clone());
529→
530→        let _ = signal_tx.send(ObserverSignal { delta, ops, from_peer });
531→    });
532→
533→    // Store subscription in the LayerUnit
534→    if let Some(unit) = state.units.get_mut(layer_name) {
535→        unit.set_observer(subscription);
536→    }
537→    debug!(layer_name = %layer_name, "Set up Loro observer for layer");
538→}
539→
540→// Pending Update Source Helpers
541→
542→/// Set pending update source before import()
543→///
544→/// **Context**: Called in handle_apply_update before import()
545→/// **Usage**: Observer reads this to populate `from_peer` in PageEvent
546→pub fn set_pending_update_source(state: &ScribeState, from_peer: Option<(String, String)>) {
547→    if let Ok(mut guard) = state.pending_update_source.lock() {
548→        *guard = from_peer;
549→    }
550→}
551→
552→/// Clear pending update source after import()
553→///
554→/// **Context**: Called in handle_apply_update after import()
555→/// **Important**: Must be called to reset for next local operation
556→pub fn clear_pending_update_source(state: &ScribeState) {
557→    if let Ok(mut guard) = state.pending_update_source.lock() {
558→        *guard = None;
559→    }
560→}
