156→/// Handle peer unsubscription
157→#[instrument(skip(state), fields(page_id = %state.page_id))]
158→pub async fn handle_unsubscribe(
159→    state: &mut ScribeState,
160→    user_did: &str,
161→    device_id: &str,
162→) {
163→    info!(user_did = %user_did, device_id = %device_id, "Peer unsubscribing");
164→
165→    // Save vectors from LayerUnit subscribers before removing
166→    let mut vectors: HashMap<String, Vec<u8>> = HashMap::new();
167→    for (layer_name, unit) in &state.units {
168→        if let Some(sub) = unit.remove_subscriber(user_did) {
169→            if !sub.version_vector.is_empty() {
170→                vectors.insert(layer_name.clone(), sub.version_vector);
171→            }
172→        }
173→    }
174→    if !vectors.is_empty() {
175→        if let Err(e) = state.vector_storage.save_vectors(user_did, device_id, &vectors) {
176→            warn!(error = %e, "Failed to save peer vectors on unsubscribe");
177→        }
178→    }
179→
180→    if let Ok(mut subs) = state.subscribers.write() {
181→        subs.remove(&(user_did.to_string(), device_id.to_string()));
182→        debug!(subscriber_count = subs.len(), "Subscriber removed");
183→    }
184→
185→    emit_peer_unsubscribed(state, user_did);
186→}
