279→// Helper Functions
280→
281→/// Validate update using ValidationHandle (kunki) or fallback to Lua runtime
282→///
283→/// **Context**: Business logic validation for remote updates
284→/// **Returns**: Ok(()) if validation passed, Err(message) if rejected
285→/// **Timeout**: 5 seconds for ValidationHandle (kunki), immediate for Lua runtime
286→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
287→async fn validate_update_with_context(
288→    state: &ScribeState,
289→    ctx: &UpdateContext,
290→    extracted_ops: &Option<Vec<JsonOp>>,
291→) -> Result<(), String> {
292→    let Some(ref ops) = extracted_ops else {
293→        return Ok(()); // No ops to validate
294→    };
295→
296→    if ops.is_empty() {
297→        return Ok(()); // Empty ops = nothing to validate
298→    }
299→
300→    // Extract actual DID from from_peer, not the role
301→    let from_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str()).unwrap_or("local");
302→
303→    // Use ValidationHandle (kunki mode with presence_lib)
304→    let Some(ref validation_handle) = state.validation_handle else {
305→        // No validation available - allow update (viewer/owner mode without kunki)
306→        // This is expected in viewer/owner mode but unexpected in node mode without kunki
307→        warn!(layer = %ctx.layer_name, from_did = %from_did, "No ValidationHandle available, allowing remote update without validation");
308→        return Ok(());
309→    };
310→
311→    use tokio::time::{timeout, Duration};
312→
313→    let validation_future = validation_handle.validate_ops(
314→        &state.page_id,
315→        &ctx.layer_name,
316→        ops,
317→        from_did,
318→        &ctx.peer_role,
319→    );
320→
321→    match timeout(Duration::from_secs(5), validation_future).await {
322→        Ok(Ok((true, _))) => {
323→            debug!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, "Validation passed");
324→            Ok(())
325→        }
326→        Ok(Ok((false, error_msg))) => {
327→            let msg = error_msg.unwrap_or_else(|| "Validation failed".to_string());
328→            warn!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, error = %msg, "Validation rejected update");
329→            Err(format!("Validation failed: {}", msg))
330→        }
331→        Ok(Err(e)) => {
332→            warn!(layer = %ctx.layer_name, error = %e, "Validation error, rejecting update");
333→            Err(format!("Validation error: {}", e))
334→        }
335→        Err(_) => {
336→            warn!(layer = %ctx.layer_name, "Validation timeout (5s), rejecting update");
337→            Err("Validation timeout".to_string())
338→        }
339→    }
340→}
