342→/// Create a new layer from peer sync
343→///
344→/// **Context**: Peer sent update for a layer we don't have yet
345→/// **We do**: Create layer, set up observer, notify UI
346→#[instrument(skip(state), fields(page_id = %state.page_id))]
347→fn create_layer_from_peer(state: &mut ScribeState, layer_name: &str) {
348→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
349→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
350→    let layer_name = layer_name.as_str();
351→    let mut unit = LayerUnit::new_empty();
352→    unit.set_local_only(!state.should_sync_layer(layer_name));
353→    unit.mark_dirty();
354→    state.units.insert(layer_name.to_string(), unit);
355→    info!(layer = %layer_name, "Created new layer from peer sync");
356→
357→    // Add existing subscribers to this new layer
358→    if let Ok(subs) = state.subscribers.read() {
359→        for ((did, _), info) in subs.iter() {
360→            if info.can_receive_layer(layer_name, &state.page_id) {
361→                if let Some(unit) = state.units.get(layer_name) {
362→                    let can_write = info.can_write_layer(layer_name, &state.page_id);
363→                    let caps = crate::layer_unit::Capabilities { read: true, write: can_write, sync: true };
364→                    unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
365→                    state.emit_layer_auth_capture(layer_name, did, "subscriber_added_from_peer");
366→                }
367→            }
368→        }
369→    }
370→
371→    // Set up Loro observer for new layer to enable sync broadcasts
372→    setup_layer_observer(state, layer_name);
373→
374→    // Notify UI subscribers about the new layer
375→    notify_layer_discovered(state, layer_name);
376→}
