383→fn apply_crdt_update(
384→    state: &mut ScribeState,
385→    layer_name: &str,
386→    update: &[u8],
387→    from_peer: Option<(String, String)>,
388→) -> Result<(), String> {
389→    // Set pending update source BEFORE apply() so observer knows who caused this change
390→    set_pending_update_source(state, from_peer);
391→
392→    // Get the layer and apply update
393→    let result = if let Some(unit) = state.units.get(layer_name) {
394→        unit.layer().apply(update)
395→    } else {
396→        clear_pending_update_source(state);
397→        return Err("Layer not found".to_string());
398→    };
399→
400→    if let Err(e) = result {
401→        // Clear on error too
402→        clear_pending_update_source(state);
403→        error!(error = %e, "Failed to apply update to layer");
404→        return Err(format!("Failed to apply update: {}", e));
405→    }
406→
407→    // Clear pending update source AFTER apply() (observer already captured it)
408→    clear_pending_update_source(state);
409→
410→    Ok(())
411→}
412→
413→/// Handle post-apply actions for remote updates
414→///
415→/// **Context**: Remote update was successfully applied
416→/// **We do**: Flush app layers immediately
417→/// **Note**: UI notification is handled by Loro observer (no duplicate emit here)
418→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
419→async fn handle_post_apply(
420→    state: &mut ScribeState,
421→    layer_name: &str,
422→    _from_peer: Option<(String, String)>,
423→) {
424→    // For app layers, flush immediately to storage so restart loads new code
425→    if layer_name.starts_with("app:") {
426→        if let Some(unit) = state.units.get_mut(layer_name) {
427→            let snapshot = unit.layer().export_snapshot();
428→            if let Err(e) = state.layer_storage.save_layer(layer_name, &snapshot) {
429→                error!(layer = %layer_name, error = %e, "Failed to save app layer immediately");
430→            } else {
431→                info!(layer = %layer_name, "Saved app layer immediately for restart");
432→                // Remove from dirty since we just saved it
433→                unit.clear_dirty();
434→            }
435→        }
436→    }
437→
438→    // Note: UI notification via emit_layer_changed_after_apply was removed
439→    // The Loro observer handles PageUpdate::LayerChanged for all changes (local and remote)
440→    // This prevents duplicate notifications
441→}
442→
443→/// Update sender's peer vector after receiving their update
444→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
445→fn update_sender_vector(state: &mut ScribeState, peer: &(String, String), layer_name: &str) {
446→    if let Some(unit) = state.units.get(layer_name) {
447→        if let Ok(mut subs) = state.subscribers.write() {
448→            if let Some(info) = subs.get_mut(peer) {
449→                let current_vector = unit.layer().version_vector();
450→                info.vectors.insert(layer_name.to_string(), current_vector);
451→                debug!(user_did = %peer.0, "Updated sender's peer vector");
452→            }
453→        }
454→    }
455→}
456→
457→/// Ensure the update sender is a per-layer subscriber on the LayerUnit.
458→///
459→/// **Context**: When a LayerUnit is created via LayerSubscribeAck before the
460→/// creator's data arrives, the creator isn't in the per-layer subscriber list.
461→/// This adds them if they're a global subscriber with access to this layer.
462→fn ensure_sender_subscribed(
463→    state: &ScribeState,
464→    layer_name: &str,
465→    from_peer: Option<&(String, String)>,
466→) {
467→    let Some(peer) = from_peer else { return };
468→    let (peer_did, _device_id) = peer;
469→
470→    // Check if already subscribed at the layer level
471→    if let Some(unit) = state.units.get(layer_name) {
472→        if unit.can_push_to(peer_did) {
473→            return;
474→        }
475→    }
476→
477→    // Look up in global subscribers
478→    if let Ok(subs) = state.subscribers.read() {
479→        if let Some(info) = subs.get(peer) {
480→            if info.can_receive_layer(layer_name, &state.page_id) {
481→                if let Some(unit) = state.units.get(layer_name) {
482→                    let can_write = info.can_write_layer(layer_name, &state.page_id);
483→                    let caps = crate::layer_unit::Capabilities {
484→                        read: true,
485→                        write: can_write,
486→                        sync: true,
487→                    };
488→                    unit.add_subscriber(peer_did.clone(), caps, info.broadcast_tx.clone());
489→                    state.emit_layer_auth_capture(
490→                        layer_name, peer_did, "sender_added_post_apply",
491→                    );
492→                }
493→            }
494→        }
495→    }
496→}
497→
498→/// Get role for a peer from their stored permit
499→///
500→/// **Context**: Determining role for Lua validation
501→/// **Checks**:
502→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
503→/// 2. Stored permit (node mode) -> extract role from permit
504→/// 3. Default -> "peer"
505→#[instrument(skip(state), fields(page_id = %state.page_id))]
506→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
507→    // If peer is our sync target, they are the "node" from our perspective
508→    if let Some(ref config) = state.sync_config {
509→        if let Some(ref sync_target) = config.sync_target {
510→            if sync_target == peer_did {
511→                return "node".to_string();
512→            }
513→        }
514→    }
515→
516→    // Node mode: look up peer's stored permit and extract role via PermitContext
517→    if let Some(ref resolver) = state.peer_resolver {
518→        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
519→            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
520→                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
521→                .unwrap_or_else(|_| "peer".to_string());
522→            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
523→            return role;
524→        }
525→    }
526→
527→    // Default role
528→    "peer".to_string()
529→}
