312→mod tests {
313→    /// Helper to test pattern matching with expansion
314→    fn matches_with_expansion(layer_name: &str, pattern: &str, page_id: &str, did: &str) -> bool {
315→        let expanded = gurkha::expand_pattern(pattern, page_id, did);
316→        gurkha::matches_wildcard(layer_name, &expanded)
317→    }
318→
319→    #[test]
320→    fn test_wildcard_pattern_matching() {
321→        // Exact segments with single wildcard
322→        assert!(gurkha::matches_wildcard(
323→            "shop123/orders/did:key:customer_a",
324→            "shop123/*/did:key:customer_a"
325→        ));
326→        assert!(gurkha::matches_wildcard(
327→            "shop123/cart/did:key:customer_a",
328→            "shop123/*/did:key:customer_a"
329→        ));
330→
331→        // Double wildcard (owner/admin pattern)
332→        assert!(gurkha::matches_wildcard(
333→            "shop123/orders/did:key:customer_a",
334→            "shop123/*/*"
335→        ));
336→        assert!(gurkha::matches_wildcard(
337→            "shop123/anything/anything_else",
338→            "shop123/*/*"
339→        ));
340→
341→        // Wrong segment count
342→        assert!(!gurkha::matches_wildcard(
343→            "shop123/orders",
344→            "shop123/*/did:key:customer_a"
345→        ));
346→        assert!(!gurkha::matches_wildcard(
347→            "shop123/orders/sub/did:key:customer_a",
348→            "shop123/*/did:key:customer_a"
349→        ));
350→
351→        // Wrong DID
352→        assert!(!gurkha::matches_wildcard(
353→            "shop123/orders/did:key:customer_b",
354→            "shop123/*/did:key:customer_a"
355→        ));
356→    }
357→
358→    #[test]
359→    fn test_pattern_expansion_and_privacy() {
360→        let pattern = "{page_id}/*/{aud}";
361→
362→        // Expansion matches own DID
363→        assert!(matches_with_expansion(
364→            "shop123/orders/did:key:customer_a",
365→            pattern,
366→            "shop123",
367→            "did:key:customer_a"
368→        ));
369→        // Expansion rejects other DID
370→        assert!(!matches_with_expansion(
371→            "shop123/orders/did:key:customer_b",
372→            pattern,
373→            "shop123",
374→            "did:key:customer_a"
375→        ));
376→
377→        // Owner wildcard pattern matches all
378→        let owner_pattern = "{page_id}/*/*";
379→        assert!(matches_with_expansion(
380→            "shop123/orders/did:key:customer_a",
381→            owner_pattern,
382→            "shop123",
383→            "did:key:owner"
384→        ));
385→        assert!(matches_with_expansion(
386→            "shop123/orders/did:key:customer_b",
387→            owner_pattern,
388→            "shop123",
389→            "did:key:owner"
390→        ));
391→    }
392→
393→    #[test]
394→    fn test_privacy_isolation() {
395→        let pattern = "{page_id}/*/{aud}";
396→        let layer_a = "shop123/orders/did:key:customer_a";
397→        let layer_b = "shop123/orders/did:key:customer_b";
398→
399→        // Customer A can access their own layer
400→        assert!(matches_with_expansion(
401→            layer_a,
402→            pattern,
403→            "shop123",
404→            "did:key:customer_a"
405→        ));
406→        // Customer A cannot access Customer B's layer
407→        assert!(!matches_with_expansion(
408→            layer_b,
409→            pattern,
410→            "shop123",
411→            "did:key:customer_a"
412→        ));
413→
414→        // Customer B can access their own layer
415→        assert!(matches_with_expansion(
416→            layer_b,
417→            pattern,
418→            "shop123",
419→            "did:key:customer_b"
420→        ));
421→        // Customer B cannot access Customer A's layer
422→        assert!(!matches_with_expansion(
423→            layer_a,
424→            pattern,
425→            "shop123",
426→            "did:key:customer_b"
427→        ));
428→    }
429→}
