  1→//! 3-Step Sync Protocol
  2→//!
  3→//! Handles the SyncOffer → SyncAccept → SyncAck protocol for CRDT synchronization.
  4→//! Also includes asset sync triggering after layer sync completes.
  5→//!
  6→//! ## Bounded Resync Protocol
  7→//!
  8→//! When vectors diverge after SyncOffer/SyncAccept, we resync. But to prevent
  9→//! infinite loops, we track resync attempts:
 10→//!
 11→//! 1. `resync_attempts < MAX_RESYNC_ATTEMPTS`: Send another SyncOffer
 12→//! 2. `resync_attempts >= MAX_RESYNC_ATTEMPTS`: Send SyncReset (request full snapshot)
 13→//! 3. Node responds with SyncSnapshot (authoritative full state)
 14→//! 4. User replaces local layer entirely
 15→//!
 16→//! **Invariant**: Node is source of truth for divergence resolution.
 17→
 18→use tracing::{debug, error, info, trace, warn, instrument};
 19→
 20→use crate::message::*;
 21→use transport::Connection;
 22→
 23→use super::super::guards::require_auth;
 24→use super::super::{PeerActor, PeerActorState, MAX_RESYNC_ATTEMPTS};
 25→use crate::coordinator::CourierMode;
 26→
 27→impl<C: Connection> PeerActor<C> {
 28→
 29→    /// Handle incoming SyncOffer from peer (Step 1)
 30→    ///
 31→    /// **Context**: Peer has a layer update with their state vector
 32→    /// **Peer sends**: SyncOffer with page_id, layer_name, encrypted data, state_vector
 33→    /// **We decrypt**: ECDH with ephemeral_public + our encryption key
 34→    /// **We apply**: Via Scribe.ApplyUpdateWithResult (handles merge)
 35→    /// **We respond**: SyncAccept with our state vector after applying (only if successful)
 36→    #[instrument(skip(self, myself, state, data, their_state_vector, ephemeral_public, authority_permit), fields(page_id = %page_id, layer_name = %layer_name))]
 37→    pub(in crate::peer_actor) async fn on_sync_offer(
 38→        &self,
 39→        myself: ractor::ActorRef<super::super::PeerMessage>,
 40→        page_id: &str,
 41→        layer_name: &str,
 42→        data: &[u8],
 43→        their_state_vector: &[u8],
 44→        ephemeral_public: &[u8; 32],
 45→        authority_permit: Option<&str>,
 46→        state: &mut PeerActorState<C>,
 47→    ) {
 48→        let (peer_did, _) = match require_auth(&state.state) {
 49→            Ok(info) => (info.0.to_string(), info.1.to_string()),
 50→            Err(_) => {
 51→                warn!("SyncOffer from unauthenticated peer: {}", self.node_id);
 52→                return;
 53→            }
 54→        };
 55→
 56→        let peer_device_id = self.node_id.to_string();
 57→
 58→        info!(
 59→            "SyncOffer received: page={} layer={} ({} bytes, vector {} bytes) from {}",
 60→            page_id, layer_name, data.len(), their_state_vector.len(), peer_did
 61→        );
 62→
 63→        // Open page early so bundled authority fanout and apply share one Scribe handle.
 64→        let scribe = match state.butler.open_page(page_id).await {
 65→            Ok(s) => s,
 66→            Err(e) => {
 67→                error!("Failed to open page {}: {}", page_id, e);
 68→                return;
 69→            }
 70→        };
 71→
 72→        if let Some(permit) = authority_permit {
 73→            match gurkha::Permit::from_token(permit) {
 74→                Ok(parsed) => {
 75→                    if parsed.token_type() == Some("layer_authority") {
 76→                        let audience = parsed.parsed().audience().to_string();
 77→                        let version = parsed
 78→                            .get_fact("version")
 79→                            .and_then(|v| v.as_u64())
 80→                            .unwrap_or(0);
 81→                        let full_layer_name = if layer_name.starts_with(&format!("{}/", page_id)) {
 82→                            layer_name.to_string()
 83→                        } else {
 84→                            format!("{}/{}", page_id, layer_name)
 85→                        };
 86→                        if let Err(e) = state.butler.permits().store_layer_authority_permit(
 87→                            page_id,
 88→                            &full_layer_name,
 89→                            &audience,
 90→                            version,
 91→                            permit,
 92→                        ) {
 93→                            warn!(
 94→                                page_id = %page_id,
 95→                                layer = %full_layer_name,
 96→                                audience = %audience,
 97→                                error = %e,
 98→                                "Failed to store bundled layer authority permit"
 99→                            );
100→                        }
101→                    }
102→                }
103→                Err(e) => {
104→                    warn!(page_id = %page_id, layer = %layer_name, error = %e, "Invalid bundled authority permit in SyncOffer");
105→                }
106→            }
107→        }
108→
109→        // Decrypt transit-encrypted update using ECDH
110→        let our_secret = match state.butler.encryption_key().await {
111→            Ok(key) => key,
112→            Err(e) => {
113→                error!("Failed to get encryption key for SyncOffer decryption: {}", e);
114→                return;
115→            }
116→        };
117→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
118→            Ok(data) => data,
119→            Err(e) => {
120→                error!("Failed to decrypt SyncOffer from {}: {}", peer_did, e);
121→                return;
122→            }
123→        };
124→
125→        // Auto-subscribe peer if not already subscribed (both Node and User modes)
126→        // For Node mode: Ensures can_write() can check viewer's write permissions
127→        // For User mode: Ensures node gets subscribed to viewer's scribe for bidirectional sync
128→        if !state.page_subscriptions.contains_key(page_id) {
129→            info!("Auto-subscribing peer {} to page {} from SyncOffer", peer_did, page_id);
130→            self.subscribe_to_page(myself.clone(), page_id, "", state).await;
131→        }
132→
133→        // Apply the update with result feedback
134→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
135→        if let Err(e) = scribe.cast(butler::ScribeMessage::ApplyUpdateWithResult {
136→            layer_name: layer_name.to_string(),
137→            update: decrypted_data,
138→            from_peer: Some((peer_did.clone(), peer_device_id.clone())),
139→            permit: None,
140→            reply: reply_tx,
141→        }) {
142→            error!("Failed to send ApplyUpdateWithResult to Scribe: {}", e);
143→            return;
144→        }
145→
146→        // Wait for apply result - only send SyncAccept if successful
147→        match reply_rx.await {
148→            Ok(Ok(())) => {
149→                debug!("ApplyUpdate succeeded for page={} layer={}", page_id, layer_name);
150→            }
151→            Ok(Err(e)) => {
152→                warn!("ApplyUpdate rejected for page={} layer={}: {}", page_id, layer_name, e);
153→                // DO NOT send SyncAccept - this stops the infinite retry loop
154→                return;
155→            }
156→            Err(_) => {
157→                error!("ApplyUpdate reply channel closed for page={} layer={}", page_id, layer_name);
158→                return;
159→            }
160→        }
161→
162→        // Get our state vector after applying
163→        let (tx, rx) = tokio::sync::oneshot::channel();
164→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
165→            layer_name: layer_name.to_string(),
166→            reply: tx.into(),
167→        }) {
168→            error!("Failed to request state vector from Scribe: {}", e);
169→            return;
170→        }
171→
172→        let our_state_vector = match rx.await {
173→            Ok(Ok(vector)) => vector,
174→            Ok(Err(e)) => {
175→                error!("Scribe returned error getting state vector: {}", e);
176→                return;
177→            }
178→            Err(_) => {
179→                error!("Scribe dropped state vector reply channel");
180→                return;
181→            }
182→        };
183→
184→        // Send SyncAccept with our state vector
185→        let msg = Message::SyncAccept(SyncAcceptMsg {
186→            page_id: page_id.to_string(),
187→            layer_name: layer_name.to_string(),
188→            state_vector: our_state_vector.clone(),
189→        });
190→
191→        self.send_message(&msg, state).await;
192→        debug!(
193→            "Sent SyncAccept for page={} layer={} to {} (our vector {} bytes)",
194→            page_id, layer_name, peer_did, our_state_vector.len()
195→        );
196→
197→        // After applying a __sync_meta update:
198→        // - User mode: check for unsynced entries and send LayerSubscribe
199→        // - Node mode: no action needed (Scribe's apply.rs handles process_creator_sync_meta)
200→        if layer_name.starts_with("__sync_meta:") && state.mode == CourierMode::User {
201→            self.check_sync_meta_and_subscribe(page_id, state).await;
202→        }
203→    }
204→
205→    /// Handle incoming SyncAccept from peer (Step 2)
206→    ///
207→    /// **Context**: Peer applied our update and reports their state vector
208→    /// **Peer sends**: SyncAccept with their state vector after applying
209→    /// **We compare**: Their vector with our current vector
210→    /// **If match**: Send SyncAck (sync complete)
211→    /// **If diverged**: Send new SyncOffer with full diff from their vector (resync)
212→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
213→    pub(in crate::peer_actor) async fn on_sync_accept(
214→        &self,
215→        page_id: &str,
216→        layer_name: &str,
217→        their_state_vector: &[u8],
218→        state: &mut PeerActorState<C>,
219→    ) {
220→        let (peer_did, _) = match require_auth(&state.state) {
221→            Ok(info) => (info.0.to_string(), info.1.to_string()),
222→            Err(_) => {
223→                warn!("SyncAccept from unauthenticated peer: {}", self.node_id);
224→                return;
225→            }
226→        };
227→
228→        debug!(
229→            "SyncAccept: page={} layer={} from {} (their vector {} bytes)",
230→            page_id, layer_name, peer_did, their_state_vector.len()
231→        );
232→
233→        // Get pending sync context (may not exist for fire-and-forget broadcasts)
234→        let key = (page_id.to_string(), layer_name.to_string());
235→        let pending = state.pending_sync_offers.remove(&key);
236→
237→        // Get our current state vector from Scribe
238→        let scribe = match state.butler.open_page(page_id).await {
239→            Ok(s) => s,
240→            Err(e) => {
241→                error!("Failed to open page {}: {}", page_id, e);
242→                return;
243→            }
244→        };
245→
246→        let (tx, rx) = tokio::sync::oneshot::channel();
247→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
248→            layer_name: layer_name.to_string(),
249→            reply: tx.into(),
250→        }) {
251→            error!("Failed to request state vector from Scribe: {}", e);
252→            return;
253→        }
254→
255→        let our_current_vector = match rx.await {
256→            Ok(Ok(vector)) => vector,
257→            Ok(Err(e)) => {
258→                error!("Scribe returned error getting state vector: {}", e);
259→                return;
260→            }
261→            Err(_) => {
262→                error!("Scribe dropped state vector reply channel");
263→                return;
264→            }
265→        };
266→
267→        // Handle based on whether we have a pending offer
268→        match pending {
269→            None => {
270→                // Fire-and-forget broadcast: No pending offer tracked.
271→                // Just update peer vector cache and send SyncAck. Trust CRDT to converge.
272→                debug!(
273→                    "SyncAccept: no pending offer (fire-and-forget) for page={} layer={} - sending SyncAck",
274→                    page_id, layer_name
275→                );
276→
277→                let msg = Message::SyncAck(SyncAckMsg {
278→                    page_id: page_id.to_string(),
279→                    layer_name: layer_name.to_string(),
280→                    state_vector: our_current_vector,
281→                });
282→                self.send_message(&msg, state).await;
283→
284→                // Update Scribe's in-memory vector cache (persistence via periodic flush)
285→                let peer_device_id = self.node_id.to_string();
286→                if let Some(subscription) = state.page_subscriptions.get(page_id) {
287→                    let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
288→                        user_did: peer_did,
289→                        device_id: peer_device_id,
290→                        layer_name: layer_name.to_string(),
291→                        state_vector: their_state_vector.to_vec(),
292→                    });
293→                }
294→            }
295→            Some(offer) => {
296→                // Tracked sync (initial sync / reconciliation): Compare vectors
297→                trace!(
298→                    "SyncAccept comparison: their_vector={} bytes, offered_vector={} bytes, current_vector={} bytes",
299→                    their_state_vector.len(),
300→                    offer.our_state_vector.len(),
301→                    our_current_vector.len()
302→                );
303→
304→                if their_state_vector == offer.our_state_vector.as_slice() {
305→                    // In sync! Send SyncAck
306→                    trace!(
307→                        "SyncAccept: vectors match for page={} layer={} - sending SyncAck",
308→                        page_id, layer_name
309→                    );
310→
311→                    let msg = Message::SyncAck(SyncAckMsg {
312→                        page_id: page_id.to_string(),
313→                        layer_name: layer_name.to_string(),
314→                        state_vector: our_current_vector,
315→                    });
316→                    self.send_message(&msg, state).await;
317→
318→                    // Update Scribe's in-memory vector cache (persistence via periodic flush)
319→                    let peer_device_id = self.node_id.to_string();
320→                    if let Some(subscription) = state.page_subscriptions.get(page_id) {
321→                        let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
322→                            user_did: peer_did,
323→                            device_id: peer_device_id,
324→                            layer_name: layer_name.to_string(),
325→                            state_vector: their_state_vector.to_vec(),
326→                        });
327→                    }
328→                } else {
329→                    // Diverged! Check if we should resync or fall back to SyncReset
330→                    let new_attempts = offer.resync_attempts + 1;
331→
332→                    if new_attempts > MAX_RESYNC_ATTEMPTS {
333→                        // Max resyncs exceeded - fall back to SyncReset (request full snapshot)
334→                        warn!(
335→                            "SyncAccept: max resyncs ({}) exceeded for page={} layer={} - sending SyncReset",
336→                            MAX_RESYNC_ATTEMPTS, page_id, layer_name
337→                        );
338→
339→                        let msg = Message::SyncReset(SyncResetMsg {
340→                            page_id: page_id.to_string(),
341→                            layer_name: layer_name.to_string(),
342→                        });
343→                        self.send_message(&msg, state).await;
344→                        return;
345→                    }
346→
347→                    // Still have retries - send resync SyncOffer with full diff from their vector
348→                    info!(
349→                        "SyncAccept: vectors DIVERGED for page={} layer={} - sending resync SyncOffer (attempt {}/{})",
350→                        page_id, layer_name, new_attempts, MAX_RESYNC_ATTEMPTS
351→                    );
352→
353→                    // Get diff from their state vector
354→                    let (tx, rx) = tokio::sync::oneshot::channel();
355→                    if let Err(e) = scribe.cast(butler::ScribeMessage::GetUpdatesSince {
356→                        layer_name: layer_name.to_string(),
357→                        state_vector: their_state_vector.to_vec(),
358→                        reply: tx,
359→                    }) {
360→                        error!("Failed to request updates from Scribe: {}", e);
361→                        return;
362→                    }
363→
364→                    let diff = match rx.await {
365→                        Ok(Ok(d)) => d,
366→                        Ok(Err(e)) => {
367→                            error!("Scribe returned error getting updates: {}", e);
368→                            return;
369→                        }
370→                        Err(_) => {
371→                            error!("Scribe dropped updates reply channel");
372→                            return;
373→                        }
374→                    };
375→
376→                    // Encrypt and send new SyncOffer
377→                    let peer_encryption_key = match state.peer_encryption_key {
378→                        Some(key) => key,
379→                        None => {
380→                            warn!("Cannot send resync SyncOffer: peer encryption key not set");
381→                            return;
382→                        }
383→                    };
384→
385→                    let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
386→                        &peer_encryption_key,
387→                        &diff,
388→                    ) {
389→                        Ok(result) => result,
390→                        Err(e) => {
391→                            error!("Failed to encrypt resync data: {}", e);
392→                            return;
393→                        }
394→                    };
395→
396→                    // Track this new pending sync with incremented attempt counter
397→                    state.pending_sync_offers.insert(
398→                        key,
399→                        super::super::PendingSyncOffer {
400→                            our_state_vector: our_current_vector.clone(),
401→                            permit: String::new(),
402→                            resync_attempts: new_attempts,
403→                        },
404→                    );
405→
406→                    let layer_name_owned = layer_name.to_string();
407→                    let msg = Message::SyncOffer(SyncOfferMsg {
408→                        page_id: page_id.to_string(),
409→                        layer_type: LayerType::from_layer_name(&layer_name_owned),
410→                        layer_name: layer_name_owned,
411→                        data: encrypted_data,
412→                        state_vector: our_current_vector,
413→                        ephemeral_public,
414→                        authority_permit: None,
415→                    });
416→                    self.send_message(&msg, state).await;
417→                }
418→            }
419→        }
420→    }
421→
422→    /// Handle incoming SyncAck from peer (Step 3)
423→    ///
424→    /// **Context**: Peer confirms sync complete after comparing vectors
425→    /// **Peer sends**: SyncAck with their final state vector
426→    /// **We do**: Update cached peer vector, log sync complete
427→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
428→    pub(in crate::peer_actor) async fn on_sync_ack(
429→        &self,
430→        page_id: &str,
431→        layer_name: &str,
432→        their_state_vector: &[u8],
433→        state: &mut PeerActorState<C>,
434→    ) {
435→        let (peer_did, _) = match require_auth(&state.state) {
436→            Ok(info) => (info.0.to_string(), info.1.to_string()),
437→            Err(_) => {
438→                warn!("SyncAck from unauthenticated peer: {}", self.node_id);
439→                return;
440→            }
441→        };
442→
443→        debug!(
444→            "SyncAck: page={} layer={} from {} - sync complete",
445→            page_id, layer_name, peer_did
446→        );
447→
448→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
449→        let peer_device_id = self.node_id.to_string();
450→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
451→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
452→                user_did: peer_did.clone(),
453→                device_id: peer_device_id.clone(),
454→                layer_name: layer_name.to_string(),
455→                state_vector: their_state_vector.to_vec(),
456→            });
457→        }
458→
459→        // Clean up any pending sync for this page/layer (shouldn't exist but be safe)
460→        let key = (page_id.to_string(), layer_name.to_string());
461→        state.pending_sync_offers.remove(&key);
462→
463→        // Check if this is an assets layer sync - trigger asset fetch for missing blobs
464→        if layer_name == "assets" || layer_name.ends_with("/assets") {
465→            self.trigger_asset_sync_after_layer_sync(page_id, layer_name, state).await;
466→        }
467→    }
468→
469→    /// Handle incoming SyncReset from peer (fallback after max resyncs)
470→    ///
471→    /// **Context**: Peer exceeded MAX_RESYNC_ATTEMPTS OR explicitly needs layer snapshot.
472→    /// **Both modes**: Respond with SyncSnapshot when layer exists locally.
473→    #[instrument(skip(self, state), fields(page_id = %page_id, layer_name = %layer_name))]
474→    pub(in crate::peer_actor) async fn on_sync_reset(
475→        &self,
476→        page_id: &str,
477→        layer_name: &str,
478→        state: &mut PeerActorState<C>,
479→    ) {
480→        let peer_did = match require_auth(&state.state) {
481→            Ok((did, _)) => did.to_string(),
482→            Err(_) => {
483→                warn!("SyncReset from unauthenticated peer: {}", self.node_id);
484→                return;
485→            }
486→        };
487→
488→        info!(
489→            "SyncReset: page={} layer={} from {} - sending full snapshot",
490→            page_id, layer_name, peer_did
491→        );
492→
493→        // Get Scribe and export full snapshot
494→        let scribe = match state.butler.open_page(page_id).await {
495→            Ok(s) => s,
496→            Err(e) => {
497→                error!("Failed to open page {} for SyncReset: {}", page_id, e);
498→                return;
499→            }
500→        };
501→
502→        // Get full snapshot
503→        let (snapshot_tx, snapshot_rx) = tokio::sync::oneshot::channel();
504→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetSnapshot {
505→            layer_name: layer_name.to_string(),
506→            reply: snapshot_tx,
507→        }) {
508→            error!("Failed to request snapshot from Scribe: {}", e);
509→            return;
510→        }
511→
512→        let snapshot = match snapshot_rx.await {
513→            Ok(Some(data)) => data,
514→            Ok(None) => {
515→                warn!("Layer {} not found in Scribe for SyncReset", layer_name);
516→                return;
517→            }
518→            Err(_) => {
519→                error!("Scribe dropped snapshot reply channel");
520→                return;
521→            }
522→        };
523→
524→        // Get state vector
525→        let (vector_tx, vector_rx) = tokio::sync::oneshot::channel();
526→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
527→            layer_name: layer_name.to_string(),
528→            reply: vector_tx.into(),
529→        }) {
530→            error!("Failed to request state vector from Scribe: {}", e);
531→            return;
532→        }
533→
534→        let state_vector = match vector_rx.await {
535→            Ok(Ok(v)) => v,
536→            Ok(Err(e)) => {
537→                error!("Scribe returned error getting state vector: {}", e);
538→                return;
539→            }
540→            Err(_) => {
541→                error!("Scribe dropped state vector reply channel");
542→                return;
543→            }
544→        };
545→
546→        // Encrypt snapshot for transfer
547→        let peer_encryption_key = match state.peer_encryption_key {
548→            Some(key) => key,
549→            None => {
550→                warn!("Cannot send SyncSnapshot: peer encryption key not set");
551→                return;
552→            }
553→        };
554→
555→        let (ephemeral_public, encrypted_snapshot) = match herald::encrypt_for_transfer(
556→            &peer_encryption_key,
557→            &snapshot,
558→        ) {
559→            Ok(result) => result,
560→            Err(e) => {
561→                error!("Failed to encrypt snapshot: {}", e);
562→                return;
563→            }
564→        };
565→
566→        // Send SyncSnapshot
567→        let layer_name_owned = layer_name.to_string();
568→        let msg = Message::SyncSnapshot(SyncSnapshotMsg {
569→            page_id: page_id.to_string(),
570→            layer_type: LayerType::from_layer_name(&layer_name_owned),
571→            layer_name: layer_name_owned,
572→            snapshot: encrypted_snapshot,
573→            state_vector,
574→            ephemeral_public,
575→        });
576→        self.send_message(&msg, state).await;
577→
578→        info!(
579→            "Sent SyncSnapshot for page={} layer={} to {} ({} bytes)",
580→            page_id, layer_name, peer_did, snapshot.len()
581→        );
582→    }
583→
584→    /// Handle incoming SyncSnapshot from peer (response to SyncReset)
585→    ///
586→    /// **Context**: Peer responded to our SyncReset with a full snapshot.
587→    /// **Both modes**: Replace local layer with received state.
588→    #[instrument(skip(self, state, snapshot, their_state_vector, ephemeral_public), fields(page_id = %page_id, layer_name = %layer_name))]
589→    pub(in crate::peer_actor) async fn on_sync_snapshot(
590→        &self,
591→        page_id: &str,
592→        layer_name: &str,
593→        snapshot: &[u8],
594→        their_state_vector: &[u8],
595→        ephemeral_public: &[u8; 32],
596→        state: &mut PeerActorState<C>,
597→    ) {
598→        let peer_did = match require_auth(&state.state) {
599→            Ok((did, _)) => did.to_string(),
600→            Err(_) => {
601→                warn!("SyncSnapshot from unauthenticated peer: {}", self.node_id);
602→                return;
603→            }
604→        };
605→
606→        info!(
607→            "SyncSnapshot: page={} layer={} from {} ({} bytes) - replacing local state",
608→            page_id, layer_name, peer_did, snapshot.len()
609→        );
610→
611→        // Decrypt snapshot
612→        let our_secret = match state.butler.encryption_key().await {
613→            Ok(key) => key,
614→            Err(e) => {
615→                error!("Failed to get encryption key for SyncSnapshot decryption: {}", e);
616→                return;
617→            }
618→        };
619→
620→        let decrypted_snapshot = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, snapshot) {
621→            Ok(data) => data,
622→            Err(e) => {
623→                error!("Failed to decrypt SyncSnapshot from {}: {}", peer_did, e);
624→                return;
625→            }
626→        };
627→
628→        // Get Scribe and replace layer
629→        let scribe = match state.butler.open_page(page_id).await {
630→            Ok(s) => s,
631→            Err(e) => {
632→                error!("Failed to open page {} for SyncSnapshot: {}", page_id, e);
633→                return;
634→            }
635→        };
636→
637→        // Replace layer with snapshot
638→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
639→        if let Err(e) = scribe.cast(butler::ScribeMessage::ReplaceLayer {
640→            layer_name: layer_name.to_string(),
641→            snapshot: decrypted_snapshot,
642→            reply: reply_tx,
643→        }) {
644→            error!("Failed to send ReplaceLayer to Scribe: {}", e);
645→            return;
646→        }
647→
648→        match reply_rx.await {
649→            Ok(Ok(())) => {
650→                info!(
651→                    "SyncSnapshot applied: page={} layer={} - sync recovery complete",
652→                    page_id, layer_name
653→                );
654→            }
655→            Ok(Err(e)) => {
656→                error!("ReplaceLayer failed for page={} layer={}: {}", page_id, layer_name, e);
657→                return;
658→            }
659→            Err(_) => {
660→                error!("Scribe dropped ReplaceLayer reply channel");
661→                return;
662→            }
663→        }
664→
665→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
666→        let peer_device_id = self.node_id.to_string();
667→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
668→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
669→                user_did: peer_did.clone(),
670→                device_id: peer_device_id,
671→                layer_name: layer_name.to_string(),
672→                state_vector: their_state_vector.to_vec(),
673→            });
674→        }
675→
676→        // Clean up any pending sync
677→        let key = (page_id.to_string(), layer_name.to_string());
678→        state.pending_sync_offers.remove(&key);
679→    }
680→}
681→

  1→//! Layer Subscribe Protocol (pull-based via __sync_meta)
  2→//!
  3→//! Handles the pull-based layer discovery and subscription flow:
  4→//! 1. Peer detects new entries in their __sync_meta (via SyncOffer)
  5→//! 2. Peer sends LayerSubscribe for each unsynced layer
  6→//! 3. Node validates, exports snapshot, issues permit, responds with LayerSubscribeAck
  7→//! 4. Peer decrypts data, stores permit, applies to Scribe, marks synced
  8→
  9→use tracing::{debug, error, info, warn, instrument};
 10→
 11→use crate::message::*;
 12→use transport::Connection;
 13→
 14→use super::guards::{require_node_mode, require_user_mode, require_auth};
 15→use super::{PeerActor, PeerActorState};
 16→use butler::ScribeMessage;
 17→
 18→impl<C: Connection> PeerActor<C> {
 19→
 20→    /// Detect __sync_meta updates and send LayerSubscribe for unsynced entries
 21→    ///
 22→    /// **Context**: PeerActor applied a SyncOffer for a __sync_meta layer
 23→    /// **We do**: Query Scribe for unsynced entries, send LayerSubscribe for each
 24→    #[instrument(skip(self, state), fields(node = %self.node_id, page_id = %page_id))]
 25→    pub(in crate::peer_actor) async fn check_sync_meta_and_subscribe(
 26→        &self,
 27→        page_id: &str,
 28→        state: &mut PeerActorState<C>,
 29→    ) {
 30→        // Only peer side (user mode) subscribes — node doesn't subscribe to layers
 31→        if require_user_mode(state.mode, "check_sync_meta_and_subscribe").is_some() {
 32→            return;
 33→        }
 34→
 35→        let scribe = match state.butler.open_page(page_id).await {
 36→            Ok(s) => s,
 37→            Err(e) => {
 38→                error!("Failed to open page {} for sync_meta check: {}", page_id, e);
 39→                return;
 40→            }
 41→        };
 42→
 43→        // Query Scribe for unsynced __sync_meta entries
 44→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
 45→        if let Err(e) = scribe.cast(ScribeMessage::GetUnsyncedSyncMeta { reply: reply_tx }) {
 46→            error!("Failed to query unsynced sync_meta: {}", e);
 47→            return;
 48→        }
 49→
 50→        let unsynced = match reply_rx.await {
 51→            Ok(entries) => entries,
 52→            Err(_) => {
 53→                error!("GetUnsyncedSyncMeta reply channel dropped");
 54→                return;
 55→            }
 56→        };
 57→
 58→        if unsynced.is_empty() {
 59→            debug!("No unsynced __sync_meta entries for page={}", page_id);
 60→            return;
 61→        }
 62→
 63→        info!(
 64→            page_id = %page_id,
 65→            count = unsynced.len(),
 66→            "Discovered {} unsynced layers via __sync_meta, sending LayerSubscribe",
 67→            unsynced.len()
 68→        );
 69→
 70→        for layer_name in unsynced {
 71→            let request_id = uuid::Uuid::new_v4().to_string();
 72→            let msg = Message::LayerSubscribe(LayerSubscribeMsg {
 73→                request_id,
 74→                page_id: page_id.to_string(),
 75→                layer_name: layer_name.clone(),
 76→            });
 77→            self.send_message(&msg, state).await;
 78→            debug!(page_id = %page_id, layer = %layer_name, "Sent LayerSubscribe");
 79→        }
 80→    }
 81→
 82→    /// Handle incoming LayerSubscribe from peer (Node-side handler)
 83→    ///
 84→    /// **Context**: Peer discovered a layer in __sync_meta, requests data + permit
 85→    /// **We do**: Delegate to Scribe (which issues permit + exports snapshot), encrypt, respond
 86→    #[instrument(skip(self, state), fields(page_id = %page_id, layer = %layer_name))]
 87→    pub(in crate::peer_actor) async fn on_layer_subscribe(
 88→        &self,
 89→        request_id: &str,
 90→        page_id: &str,
 91→        layer_name: &str,
 92→        state: &mut PeerActorState<C>,
 93→    ) {
 94→        if require_node_mode(state.mode, "on_layer_subscribe").is_some() {
 95→            return;
 96→        }
 97→
 98→        let (peer_did, _) = match require_auth(&state.state) {
 99→            Ok(info) => (info.0.to_string(), info.1.to_string()),
100→            Err(_) => {
101→                warn!("LayerSubscribe from unauthenticated peer: {}", self.node_id);
102→                return;
103→            }
104→        };
105→
106→        info!(
107→            "LayerSubscribe: page={} layer={} from peer={}",
108→            page_id, layer_name, peer_did
109→        );
110→
111→        // Get Scribe for this page
112→        let scribe = match state.page_subscriptions.get(page_id) {
113→            Some(sub) => sub.scribe.clone(),
114→            None => {
115→                warn!("LayerSubscribe: no page subscription for page={}", page_id);
116→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "page not subscribed", state).await;
117→                return;
118→            }
119→        };
120→
121→        // Delegate to Scribe: issues permit, adds subscriber, exports snapshot
122→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
123→        if let Err(e) = scribe.cast(ScribeMessage::HandleLayerSubscribe {
124→            layer_name: layer_name.to_string(),
125→            peer_did: peer_did.clone(),
126→            reply: reply_tx,
127→        }) {
128→            error!("Failed to send HandleLayerSubscribe to Scribe: {}", e);
129→            self.send_layer_subscribe_reject(request_id, page_id, layer_name, "internal error", state).await;
130→            return;
131→        }
132→
133→        let (snapshot_data, state_vector, layer_permit) = match reply_rx.await {
134→            Ok(Ok(result)) => result,
135→            Ok(Err(e)) => {
136→                warn!("HandleLayerSubscribe error for layer={}: {}", layer_name, e);
137→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, &e, state).await;
138→                return;
139→            }
140→            Err(_) => {
141→                error!("HandleLayerSubscribe reply dropped for layer={}", layer_name);
142→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "internal error", state).await;
143→                return;
144→            }
145→        };
146→
147→        // Encrypt snapshot for transfer
148→        let peer_encryption_key = match state.peer_encryption_key {
149→            Some(key) => key,
150→            None => {
151→                warn!("Cannot send LayerSubscribeAck: peer encryption key not set");
152→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "no encryption key", state).await;
153→                return;
154→            }
155→        };
156→
157→        let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
158→            &peer_encryption_key,
159→            &snapshot_data,
160→        ) {
161→            Ok(result) => result,
162→            Err(e) => {
163→                error!("Failed to encrypt LayerSubscribeAck data: {}", e);
164→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "encryption failed", state).await;
165→                return;
166→            }
167→        };
168→
169→        // Mark the entry as synced in the peer's __sync_meta on the node
170→        if let Some(sub) = state.page_subscriptions.get(page_id) {
171→            let meta_layer = format!("__sync_meta:{}", peer_did);
172→            let _ = sub.scribe.cast(ScribeMessage::UpdateFromJson {
173→                layer_name: meta_layer,
174→                path: layer_name.to_string(),
175→                value: serde_json::json!(true),
176→                reply: None,
177→            });
178→        }
179→
180→        let msg = Message::LayerSubscribeAck(LayerSubscribeAckMsg {
181→            request_id: request_id.to_string(),
182→            page_id: page_id.to_string(),
183→            layer_name: layer_name.to_string(),
184→            accepted: true,
185→            reason: None,
186→            data: encrypted_data,
187→            state_vector,
188→            ephemeral_public,
189→            layer_permit,
190→        });
191→
192→        self.send_message(&msg, state).await;
193→        info!("Sent LayerSubscribeAck for page={} layer={} to peer={}", page_id, layer_name, peer_did);
194→    }
195→
196→    /// Send a rejected LayerSubscribeAck
197→    async fn send_layer_subscribe_reject(
198→        &self,
199→        request_id: &str,
200→        page_id: &str,
201→        layer_name: &str,
202→        reason: &str,
203→        state: &PeerActorState<C>,
204→    ) {
205→        let msg = Message::LayerSubscribeAck(LayerSubscribeAckMsg {
206→            request_id: request_id.to_string(),
207→            page_id: page_id.to_string(),
208→            layer_name: layer_name.to_string(),
209→            accepted: false,
210→            reason: Some(reason.to_string()),
211→            data: Vec::new(),
212→            state_vector: Vec::new(),
213→            ephemeral_public: [0u8; 32],
214→            layer_permit: String::new(),
215→        });
216→        self.send_message(&msg, state).await;
217→    }
218→
219→    /// Handle incoming LayerSubscribeAck from node (Peer-side handler)
220→    ///
221→    /// **Context**: Node processed our LayerSubscribe, sent data + permit
222→    /// **We do**: Decrypt data, store permit, apply to Scribe, authorize node, mark synced
223→    #[instrument(skip(self, state, data, _state_vector, ephemeral_public, layer_permit), fields(page_id = %page_id, layer = %layer_name))]
224→    pub(in crate::peer_actor) async fn on_layer_subscribe_ack(
225→        &self,
226→        _request_id: &str,
227→        page_id: &str,
228→        layer_name: &str,
229→        accepted: bool,
230→        reason: Option<&str>,
231→        data: &[u8],
232→        _state_vector: &[u8],
233→        ephemeral_public: &[u8; 32],
234→        layer_permit: &str,
235→        state: &mut PeerActorState<C>,
236→    ) {
237→        if require_user_mode(state.mode, "on_layer_subscribe_ack").is_some() {
238→            return;
239→        }
240→
241→        let (node_did, _) = match require_auth(&state.state) {
242→            Ok(info) => (info.0.to_string(), info.1.to_string()),
243→            Err(_) => {
244→                warn!("LayerSubscribeAck from unauthenticated peer: {}", self.node_id);
245→                return;
246→            }
247→        };
248→
249→        if !accepted {
250→            warn!(
251→                "LayerSubscribeAck rejected for page={} layer={}: {}",
252→                page_id, layer_name, reason.unwrap_or("unknown")
253→            );
254→            return;
255→        }
256→
257→        info!(
258→            "LayerSubscribeAck: page={} layer={} from node={} data_len={}",
259→            page_id, layer_name, node_did, data.len()
260→        );
261→
262→        // 1. Decrypt data
263→        let our_secret = match state.butler.encryption_key().await {
264→            Ok(key) => key,
265→            Err(e) => {
266→                error!("Failed to get encryption key for LayerSubscribeAck: {}", e);
267→                return;
268→            }
269→        };
270→
271→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
272→            Ok(plaintext) => plaintext,
273→            Err(e) => {
274→                error!("Failed to decrypt LayerSubscribeAck data: {}", e);
275→                return;
276→            }
277→        };
278→
279→        // 2. Store layer permit
280→        let full_layer_name = format!("{}/{}", page_id, layer_name);
281→        let our_did = match state.butler.get_identity().await {
282→            Ok(identity) => identity.did().to_string(),
283→            Err(e) => {
284→                error!("Failed to get our identity: {}", e);
285→                return;
286→            }
287→        };
288→
289→        if let Err(e) = state.butler.permits().store_layer_permit(
290→            page_id, &our_did, &full_layer_name, layer_permit,
291→        ) {
292→            error!("Failed to store layer permit: {}", e);
293→            return;
294→        }
295→
296→        info!("Stored layer permit for layer={}", full_layer_name);
297→
298→        // 3. Apply data to Scribe
299→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
300→            let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
301→            if let Err(e) = subscription.scribe.cast(ScribeMessage::ApplyUpdateWithResult {
302→                layer_name: layer_name.to_string(),
303→                update: decrypted_data,
304→                from_peer: Some((node_did.clone(), self.node_id.to_string())),
305→                permit: Some(layer_permit.to_string()),
306→                reply: reply_tx,
307→            }) {
308→                error!("Failed to send ApplyUpdate for LayerSubscribeAck: {}", e);
309→                return;
310→            }
311→
312→            match reply_rx.await {
313→                Ok(Ok(())) => {
314→                    info!("Applied LayerSubscribeAck data for layer={}", layer_name);
315→                }
316→                Ok(Err(e)) => {
317→                    warn!("Scribe rejected LayerSubscribeAck data for layer={}: {}", layer_name, e);
318→                }
319→                Err(_) => {
320→                    error!("ApplyUpdate reply dropped for layer={}", layer_name);
321→                    return;
322→                }
323→            }
324→
325→            // 4. Authorize node as subscriber for bidirectional sync
326→            subscription.scribe.cast(ScribeMessage::AuthorizeLayerSubscriber {
327→                layer_name: layer_name.to_string(),
328→                subscriber_did: node_did.clone(),
329→            }).ok();
330→            info!("Authorized node {} on layer={}", node_did, layer_name);
331→
332→            // 5. Mark __sync_meta entry as synced
333→            subscription.scribe.cast(ScribeMessage::MarkSyncMetaSynced {
334→                layer_name: layer_name.to_string(),
335→            }).ok();
336→        } else {
337→            warn!("No page subscription for page={}, cannot apply LayerSubscribeAck", page_id);
338→        }
339→    }
340→}
