  1→//! Sync Consent
  2→//!
  3→//! Handles viewer issuing consent permits to node, and node receiving/storing them.
  4→//! Consent permits authorize the node to send sync updates to the viewer.
  5→
  6→use tracing::{error, info, warn, instrument};
  7→
  8→use crate::message::*;
  9→use transport::Connection;
 10→
 11→use super::guards::{require_user_mode, require_auth, parse_permit};
 12→use super::{PeerActor, PeerActorState};
 13→
 14→// Used for automatic consent issuance when viewer receives space/pages.
 15→// In production, these could be configurable.
 16→
 17→/// Default space consent template - viewer consents to receive space sync + new pages
 18→pub(in crate::peer_actor) const DEFAULT_SPACE_CONSENT_TEMPLATE: &str = r#"{
 19→  "consent_template": {
 20→    "token_type": "sync_space_consent",
 21→    "operations": { "receive_pages": "allow", "receive_updates": "allow" },
 22→    "auth_capabilities": { "accept_sync": true, "accept_new_pages": true },
 23→    "relationship": "sync_consent"
 24→  }
 25→}"#;
 26→
 27→
 28→impl<C: Connection> PeerActor<C> {
 29→
 30→    /// Issue sync consent permits and send to node (User/Viewer mode)
 31→    ///
 32→    /// **Context**: Viewer received space + pages, now issues consent permits
 33→    /// **We do**: Issue consent permits via gurkha, send SyncConsentGrant to node
 34→    /// **Node stores**: These permits to attach to future SyncOffer messages
 35→    #[instrument(skip(self, state, space_template, page_template), fields(space_id = %space_id))]
 36→    pub(in crate::peer_actor) async fn issue_sync_consent(
 37→        &self,
 38→        space_id: &str,
 39→        space_template: &str,
 40→        page_template: &str,
 41→        state: &mut PeerActorState<C>,
 42→    ) {
 43→        if require_user_mode(state.mode, "issue_sync_consent").is_some() {
 44→            return;
 45→        }
 46→
 47→        // Get node's public key from authenticated state (this is who we're issuing permits to)
 48→        let node_pubkey = match require_auth(&state.state) {
 49→            Ok((did, _)) => did.to_string(),
 50→            Err(_) => {
 51→                warn!("Cannot issue sync consent: not authenticated with node");
 52→                return;
 53→            }
 54→        };
 55→
 56→        // Get viewer's signing key
 57→        let signing_key = match state.butler.signing_key().await {
 58→            Ok(key) => key,
 59→            Err(e) => {
 60→                error!("Failed to get signing key for consent permits: {}", e);
 61→                return;
 62→            }
 63→        };
 64→
 65→        // Get space data with permit (node's viewer permit for space)
 66→        let space_data = match state.butler.spaces().get_data(space_id) {
 67→            Ok(Some(space)) => space,
 68→            Ok(None) => {
 69→                error!("Space {} not found for consent issuance", space_id);
 70→                return;
 71→            }
 72→            Err(e) => {
 73→                error!("Failed to get space {}: {}", space_id, e);
 74→                return;
 75→            }
 76→        };
 77→
 78→        let node_space_permit = match space_data.get_permit() {
 79→            Some(permit) => permit.clone(),
 80→            None => {
 81→                error!("No permit found for space {} - cannot issue consent", space_id);
 82→                return;
 83→            }
 84→        };
 85→
 86→        // Issue space consent permit
 87→        let (space_consent_permit, _cid) = match gurkha::issue_sync_space_consent(
 88→            &signing_key,
 89→            &node_pubkey,
 90→            space_id,
 91→            &node_space_permit,
 92→            space_template,
 93→        ).await {
 94→            Ok(result) => result,
 95→            Err(e) => {
 96→                error!("Failed to issue space consent permit: {}", e);
 97→                return;
 98→            }
 99→        };
100→
101→        info!("Issued space consent permit for space {}", space_id);
102→
103→        // Get all pages in space and issue page consent permits
104→        let pages = match state.butler.pages().list(space_id) {
105→            Ok(pages) => pages,
106→            Err(e) => {
107→                error!("Failed to list pages in space {}: {}", space_id, e);
108→                return;
109→            }
110→        };
111→
112→        let mut page_consent_permits: Vec<(String, String)> = Vec::with_capacity(pages.len());
113→
114→        for page in pages {
115→            // Get page data with permit
116→            let page_data = match state.butler.pages().get(&page.id) {
117→                Ok(Some(data)) => data,
118→                Ok(None) => {
119→                    warn!("Page {} not found - skipping consent", page.id);
120→                    continue;
121→                }
122→                Err(e) => {
123→                    warn!("Failed to get page {}: {} - skipping consent", page.id, e);
124→                    continue;
125→                }
126→            };
127→
128→            let node_page_permit = match page_data.get_permit() {
129→                Some(permit) => permit.clone(),
130→                None => {
131→                    warn!("No permit found for page {} - skipping consent", page.id);
132→                    continue;
133→                }
134→            };
135→
136→            // Issue page consent permit
137→            let (page_consent_permit, _cid) = match gurkha::issue_sync_page_consent(
138→                &signing_key,
139→                &node_pubkey,
140→                &page.id,
141→                &node_page_permit,
142→                page_template,
143→            ).await {
144→                Ok(result) => result,
145→                Err(e) => {
146→                    warn!("Failed to issue page consent permit for {}: {}", page.id, e);
147→                    continue;
148→                }
149→            };
150→
151→            page_consent_permits.push((page.id.clone(), page_consent_permit));
152→        }
153→
154→        info!(
155→            "Issued {} page consent permits for space {}",
156→            page_consent_permits.len(),
157→            space_id
158→        );
159→
160→        // Send SyncConsentGrant to node
161→        let request_id = uuid::Uuid::new_v4().to_string();
162→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
163→            request_id,
164→            space_id: space_id.to_string(),
165→            space_consent_permit,
166→            page_consent_permits,
167→        });
168→
169→        self.send_message(&msg, state).await;
170→        info!("Sent SyncConsentGrant for space {} to node", space_id);
171→    }
172→
173→    /// Issue space consent permit only (when space is received)
174→    ///
175→    /// **Context**: Viewer received space, issues consent immediately
176→    /// **We do**: Issue space consent permit via gurkha, send SyncConsentGrant
177→    #[instrument(skip(self, state, node_space_permit, space_template), fields(space_id = %space_id))]
178→    pub(in crate::peer_actor) async fn issue_space_consent(
179→        &self,
180→        space_id: &str,
181→        node_space_permit: &str,
182→        space_template: &str,
183→        state: &mut PeerActorState<C>,
184→    ) {
185→        if require_user_mode(state.mode, "issue_space_consent").is_some() {
186→            return;
187→        }
188→
189→        // Extract node's DID from the permit (iss field)
190→        // This works for both handshake and SpaceRequest flows
191→        let node_pubkey = match parse_permit(node_space_permit) {
192→            Ok(permit) => permit.parsed().issuer().to_string(),
193→            Err(e) => {
194→                error!("Cannot issue space consent: failed to parse permit: {}", e);
195→                return;
196→            }
197→        };
198→
199→        let signing_key = match state.butler.signing_key().await {
200→            Ok(key) => key,
201→            Err(e) => {
202→                error!("Failed to get signing key for space consent: {}", e);
203→                return;
204→            }
205→        };
206→
207→        let (space_consent_permit, _cid) = match gurkha::issue_sync_space_consent(
208→            &signing_key,
209→            &node_pubkey,
210→            space_id,
211→            node_space_permit,
212→            space_template,
213→        ).await {
214→            Ok(result) => result,
215→            Err(e) => {
216→                error!("Failed to issue space consent permit: {}", e);
217→                return;
218→            }
219→        };
220→
221→        info!("Issued space consent permit for space {}", space_id);
222→
223→        // Send SyncConsentGrant with only space consent (no page consents yet)
224→        let request_id = uuid::Uuid::new_v4().to_string();
225→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
226→            request_id,
227→            space_id: space_id.to_string(),
228→            space_consent_permit,
229→            page_consent_permits: vec![],
230→        });
231→
232→        self.send_message(&msg, state).await;
233→        info!("Sent space consent for space {} to node", space_id);
234→    }
235→
236→    /// Handle incoming SyncConsentGrant from viewer (Node mode)
237→    ///
238→    /// **Context**: Viewer issued consent permits after receiving space content
239→    /// **We store**: Viewer's consent permits keyed by (viewer_did, space_id/page_id)
240→    /// **We send**: SyncConsentAck to confirm receipt
241→    #[instrument(skip(self, state, space_consent_permit, page_consent_permits), fields(space_id = %space_id))]
242→    pub(in crate::peer_actor) async fn on_sync_consent_grant(
243→        &self,
244→        request_id: &str,
245→        space_id: &str,
246→        space_consent_permit: &str,
247→        page_consent_permits: &[(String, String)],
248→        state: &mut PeerActorState<C>,
249→    ) {
250→        // Extract viewer's DID from the consent permit (iss field)
251→        // The viewer issues consent permits, so `iss` contains viewer's DID
252→        // This works for SpaceRequest flow where viewer isn't handshake-authenticated
253→        let viewer_did = if !space_consent_permit.is_empty() {
254→            match parse_permit(space_consent_permit) {
255→                Ok(permit) => permit.parsed().issuer().to_string(),
256→                Err(e) => {
257→                    error!("Cannot process SyncConsentGrant: failed to parse space consent permit: {}", e);
258→                    return;
259→                }
260→            }
261→        } else if let Some((_, permit)) = page_consent_permits.first() {
262→            match parse_permit(permit) {
263→                Ok(permit) => permit.parsed().issuer().to_string(),
264→                Err(e) => {
265→                    error!("Cannot process SyncConsentGrant: failed to parse page consent permit: {}", e);
266→                    return;
267→                }
268→            }
269→        } else {
270→            error!("SyncConsentGrant has no permits to extract viewer DID from");
271→            return;
272→        };
273→
274→        info!(
275→            "SyncConsentGrant: space={} from viewer={} ({} page consents)",
276→            space_id, viewer_did, page_consent_permits.len()
277→        );
278→
279→        // Store viewer consent permits via Butler
280→        if let Err(e) = state.butler.contacts().store_viewer_consent(
281→            &viewer_did,
282→            space_id,
283→            space_consent_permit,
284→            page_consent_permits,
285→        ).await {
286→            error!("Failed to store viewer consent permits: {}", e);
287→            return;
288→        }
289→
290→        info!("Stored viewer consent permits for {} space={}", viewer_did, space_id);
291→
292→        // Send acknowledgment
293→        let msg = Message::SyncConsentAck(SyncConsentAckMsg {
294→            request_id: request_id.to_string(),
295→            space_id: space_id.to_string(),
296→        });
297→        self.send_message(&msg, state).await;
298→    }
299→
300→    /// Handle incoming SyncConsentAck from node (Viewer-side handler)
301→    ///
302→    /// **Context**: Node has acknowledged our consent permits
303→    /// **Node sends**: SyncConsentAck confirming storage
304→    /// **We know**: Node can now send us sync updates with our consent permits attached
305→    #[instrument(skip(self, state), fields(space_id = %space_id))]
306→    pub(in crate::peer_actor) async fn on_sync_consent_ack(
307→        &self,
308→        request_id: &str,
309→        space_id: &str,
310→        state: &mut PeerActorState<C>,
311→    ) {
312→        let (node_did, _) = match require_auth(&state.state) {
313→            Ok(info) => (info.0.to_string(), info.1.to_string()),
314→            Err(_) => {
315→                warn!("SyncConsentAck from unauthenticated peer: {}", self.node_id);
316→                return;
317→            }
318→        };
319→
320→        info!(
321→            "SyncConsentAck: space={} from node={} request={}",
322→            space_id, node_did, request_id
323→        );
324→
325→        info!("Sync consent complete for space {}", space_id);
326→    }
327→
328→    /// Send a PermitUpdate to this peer (Node mode)
329→    ///
330→    /// **Context**: Page permit reissued with new app layers
331→    /// **We do**: Send PermitUpdate message on the wire
332→    #[instrument(skip(self, state, permit), fields(page_id = %page_id))]
333→    pub(in crate::peer_actor) async fn send_page_permit_update(
334→        &self,
335→        page_id: &str,
336→        permit: &str,
337→        state: &mut PeerActorState<C>,
338→    ) {
339→        let msg = Message::PermitUpdate(PermitUpdateMsg {
340→            permit: permit.to_string(),
341→            scope: PermitScope::Page { page_id: page_id.to_string() },
342→        });
343→
344→        self.send_message(&msg, state).await;
345→        info!("Sent PermitUpdate for page={}", page_id);
346→    }
347→
348→}
