  1→//! Sync Consent Decisions
  2→//!
  3→//! Decision functions for sync consent permits:
  4→//! - Space sync consent (viewer → node)
  5→//! - Page sync consent (viewer → node)
  6→
  7→use super::types::{DecisionResult, TokenDecision};
  8→use crate::errors::GurkhaError;
  9→use base64::{Engine as _, engine::general_purpose};
 10→use ed25519_dalek::VerifyingKey;
 11→use serde_json::{json, Value};
 12→use tracing::trace;
 13→
 14→/// Decide what should be in a space sync consent permit
 15→///
 16→/// **Context**: Viewer issues this permit back to the node after receiving SpaceSync.
 17→/// It expresses the viewer's consent to receive sync updates for the space.
 18→///
 19→/// **Issued by**: Viewer
 20→/// **Audience**: Node (the specific node DID)
 21→/// **Proof**: Node's original viewer permit (establishes delegation chain)
 22→///
 23→/// Space consent permits have:
 24→/// - Specific node pubkey as audience (not wildcard)
 25→/// - Facts expressing consent to receive updates and new pages
 26→/// - Proof chain to node's original permit
 27→/// - Same space_id as the original permit
 28→pub fn decide_sync_space_consent(
 29→    viewer_verifying_key: &VerifyingKey,
 30→    node_pubkey: &str,
 31→    space_id: &str,
 32→    node_viewer_permit: &str,
 33→    template_json: &str,
 34→) -> DecisionResult<TokenDecision> {
 35→    let viewer_pub_key_b64 = general_purpose::STANDARD.encode(viewer_verifying_key.as_bytes());
 36→
 37→    let mut decision = TokenDecision::new(node_pubkey); // Specific node as audience
 38→
 39→    // Parse consent template
 40→    let template_data: Value = serde_json::from_str(template_json)
 41→        .map_err(|e| GurkhaError::InvalidTemplate(format!("Invalid consent template JSON: {}", e)))?;
 42→
 43→    let consent_template = template_data
 44→        .get("consent_template")
 45→        .ok_or_else(|| GurkhaError::InvalidTemplate("Missing consent_template".to_string()))?;
 46→
 47→    // Core consent facts
 48→    decision.add_fact("token_type".into(), json!("sync_space_consent"));
 49→    decision.add_fact("relationship".into(), json!("sync_consent"));
 50→    decision.add_fact("space_id".into(), json!(space_id));
 51→    decision.add_fact("user_id".into(), json!(viewer_pub_key_b64));
 52→
 53→    // Operations from template
 54→    if let Some(operations) = consent_template.get("operations") {
 55→        decision.add_fact("operations".into(), operations.clone());
 56→    }
 57→
 58→    // Auth capabilities from template
 59→    if let Some(auth_caps) = consent_template.get("auth_capabilities") {
 60→        decision.add_fact("auth_capabilities".into(), auth_caps.clone());
 61→    }
 62→
 63→    // Calculate CID of the proof token and add to proof chain
 64→    let proof_cid = crate::crypto::get_permit_cid(node_viewer_permit)?;
 65→    decision.proofs.push(proof_cid.clone());
 66→    decision.proof_tokens.insert(proof_cid, node_viewer_permit.to_string());
 67→
 68→    trace!("Space sync consent decision created for space {} -> node {}", space_id, node_pubkey);
 69→    Ok(decision)
 70→}
 71→
 72→/// Decide what should be in a page sync consent permit
 73→///
 74→/// **Context**: Viewer issues this permit back to the node after receiving PageSync.
 75→/// It expresses the viewer's consent to receive layer updates for a specific page.
 76→///
 77→/// **Issued by**: Viewer
 78→/// **Audience**: Node (the specific node DID)
 79→/// **Proof**: Node's original page_viewer permit (establishes delegation chain)
 80→///
 81→/// Page consent permits have:
 82→/// - Specific node pubkey as audience
 83→/// - Facts expressing consent to receive layer updates
 84→/// - Layers with "receive" capability (mirroring original viewer layers)
 85→/// - Proof chain to node's original permit
 86→/// - Same page_id as the original permit
 87→pub fn decide_sync_page_consent(
 88→    viewer_verifying_key: &VerifyingKey,
 89→    node_pubkey: &str,
 90→    page_id: &str,
 91→    node_viewer_permit: &str,
 92→    template_json: &str,
 93→) -> DecisionResult<TokenDecision> {
 94→    let viewer_pub_key_b64 = general_purpose::STANDARD.encode(viewer_verifying_key.as_bytes());
 95→
 96→    let mut decision = TokenDecision::new(node_pubkey); // Specific node as audience
 97→
 98→    // Parse consent template
