100→        .map_err(|e| GurkhaError::InvalidTemplate(format!("Invalid consent template JSON: {}", e)))?;
101→
102→    let consent_template = template_data
103→        .get("consent_template")
104→        .ok_or_else(|| GurkhaError::InvalidTemplate("Missing consent_template".to_string()))?;
105→
106→    // Core consent facts
