108→    decision.add_fact("relationship".into(), json!("sync_consent"));
109→    decision.add_fact("page_id".into(), json!(page_id));
110→    decision.add_fact("user_id".into(), json!(viewer_pub_key_b64));
111→
112→    // Operations from template
