125→    }
126→
127→    // Auth capabilities from template
128→    if let Some(auth_caps) = consent_template.get("auth_capabilities") {
129→        decision.add_fact("auth_capabilities".into(), auth_caps.clone());
130→    }
131→
132→    // Calculate CID of the proof token and add to proof chain
