190→    }
191→
192→    // Calculate CID of the layer permit and add to proof chain
193→    let proof_cid = crate::crypto::get_permit_cid(layer_permit_token)?;
194→    decision.proofs.push(proof_cid.clone());
195→    decision.proof_tokens.insert(proof_cid, layer_permit_token.to_string());
