  1→//! Layer Pattern Authorization
  2→//!
  3→//! Functions for checking if a permit authorizes access to a layer.
  4→//! Supports two-tier access: page permit (static layers) + layer permits (dynamic layers).
  5→
  6→/// Check if permit authorizes access to a layer
  7→///
  8→/// With fully-resolved permits, this is a simple map lookup.
  9→/// Layer keys in the permit are already expanded (e.g., "abc123/products").
 10→///
 11→/// # Arguments
 12→/// * `permit` - The viewer's permit
 13→/// * `layer_name` - Name of the layer to access (bare or full)
 14→/// * `operation` - Operation to check: "read", "write", "sync"
 15→///
 16→/// # Returns
 17→/// `true` if the permit authorizes this layer access
 18→pub fn can_access_layer(permit: &crate::parser::Permit, layer_name: &str, operation: &str) -> bool {
 19→    let page_id = permit.get_fact("page_id")
 20→        .and_then(|v| v.as_str())
 21→        .unwrap_or("");
 22→
 23→    // Try direct lookup first
 24→    if let Some(config) = permit.layers().get(layer_name) {
 25→        return check_operation(config, operation);
 26→    }
 27→
 28→    // Try with page_id prefix (for bare names like "products")
 29→    let full_name = format!("{}/{}", page_id, layer_name);
 30→    if let Some(config) = permit.layers().get(&full_name) {
 31→        return check_operation(config, operation);
 32→    }
 33→
 34→    // Try stripping page_id prefix (for full names when permit has bare)
 35→    let page_prefix = format!("{}/", page_id);
 36→    if let Some(bare) = layer_name.strip_prefix(&page_prefix) {
 37→        if let Some(config) = permit.layers().get(bare) {
 38→            return check_operation(config, operation);
 39→        }
 40→    }
 41→
 42→    tracing::debug!("[can_access_layer] No layer match for '{}'", layer_name);
 43→    false
 44→}
 45→
 46→/// Check access across a page permit + set of layer permits (two-tier model)
 47→///
 48→/// **Context**: Dynamic layers are authorized via separate layer permits.
 49→/// This function checks if any permit in the set grants access to the layer.
 50→///
 51→/// Access check = page permit layers ∪ all layer permit layers
 52→pub fn can_access_with_layer_permits(
 53→    page_permit: &crate::parser::Permit,
 54→    layer_permits: &[crate::parser::Permit],
 55→    layer_name: &str,
 56→    page_id: &str,
 57→    did: &str,
 58→    operation: &str,
 59→) -> bool {
 60→    // Check page permit first
 61→    if can_access_layer(page_permit, layer_name, operation) {
 62→        return true;
 63→    }
 64→
 65→    // Check each layer permit
 66→    for lp in layer_permits {
 67→        if can_access_layer(lp, layer_name, operation) {
 68→            return true;
 69→        }
 70→    }
 71→
 72→    // Schema fallback: creator can access dynamic layers matching their own DID in path
 73→    if matches_creator_schema(page_permit, layer_name, page_id, did, operation) {
 74→        return true;
 75→    }
 76→
 77→    false
 78→}
 79→
 80→/// Check if a layer matches a dynamic schema (node-side auth)
 81→///
 82→/// **Context**: Node needs to authorize writes from peers to dynamic layers.
 83→/// The peer's page permit doesn't cover the dynamic layer (it has another user's DID in the path).
 84→/// Instead, the node checks its own permit's `dynamic_layer_schemas` permissions.
 85→///
 86→/// **Example**: Bob writes to `channels/did:key:alice/project-x/messages`.
 87→/// Node's permit has schema `channels/{id}/messages` with `permissions.write = true`.
 88→/// The path structure matches the schema → write is allowed.
 89→pub fn matches_dynamic_schema(
 90→    permit: &crate::parser::Permit,
 91→    layer_name: &str,
 92→    page_id: &str,
 93→    operation: &str,
 94→) -> bool {
 95→    let schemas = permit.dynamic_layer_schemas();
 96→    if schemas.is_empty() {
 97→        return false;
 98→    }
 99→
100→    // Strip page_id prefix to get bare layer path
101→    let page_prefix = format!("{}/", page_id);
102→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
103→
104→    for (schema_pattern, schema) in schemas {
105→        if matches_dynamic_path_any_did(bare_path, schema_pattern) {
106→            if check_operation(&schema.permissions, operation) {
107→                return true;
108→            }
109→        }
110→    }
111→
112→    false
113→}
114→
115→/// Match a layer path against a dynamic schema pattern (any DID accepted)
116→///
117→/// **Context**: Unlike `matches_dynamic_path`, this doesn't require a specific DID.
118→/// Used for node-side authorization where the peer writing isn't the creator.
119→///
120→/// **Pattern**: `channels/{id}/messages`
121→/// **Path**:    `channels/did:key:alice/project-x/messages`
122→///
123→/// Accepts any value in the DID position (path_parts[1]).
124→fn matches_dynamic_path_any_did(bare_path: &str, schema_pattern: &str) -> bool {
125→    let path_parts: Vec<&str> = bare_path.split('/').collect();
126→    let pattern_parts: Vec<&str> = schema_pattern.split('/').collect();
127→
128→    // Dynamic path has one extra segment (the DID) compared to schema pattern
129→    if path_parts.len() != pattern_parts.len() + 1 {
130→        return false;
131→    }
132→
133→    // First segment must match literally
134→    if path_parts.is_empty() || pattern_parts.is_empty() || path_parts[0] != pattern_parts[0] {
135→        return false;
136→    }
137→
138→    // path_parts[1] is the DID segment — accept any value (no specific DID check)
139→
140→    // Remaining segments: match path[2..] against pattern[1..]
141→    for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
142→        if *pat_seg != "{id}" && path_seg != pat_seg {
143→            return false;
144→        }
145→    }
146→
147→    true
148→}
149→
150→/// Schema fallback for creator access to dynamic layers
151→///
152→/// **Context**: When a creator creates a dynamic layer, they can access it immediately
153→/// via schema matching (before the node issues a layer permit). The layer path must
154→/// contain the creator's DID to prove ownership.
155→///
156→/// **Example**: Creator with DID `did:key:alice` and schema `channels/{id}/messages`
157→/// can access `page1/channels/did:key:alice/general/messages` because:
158→/// 1. Schema `channels/{id}/messages` exists in their permit
159→/// 2. The path contains their DID after stripping page_id prefix
160→pub fn matches_creator_schema(
161→    permit: &crate::parser::Permit,
162→    layer_name: &str,
163→    page_id: &str,
164→    our_did: &str,
165→    operation: &str,
166→) -> bool {
167→    let schemas = permit.dynamic_layer_schemas();
168→    if schemas.is_empty() {
169→        return false;
170→    }
171→
172→    // Strip page_id prefix to get bare layer path
173→    let page_prefix = format!("{}/", page_id);
174→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
175→
176→    // For creator access, the path must contain the creator's DID
177→    // Path format: {schema_prefix}/{creator_did}/{id_segments}/{schema_suffix}
178→    if !bare_path.contains(our_did) {
179→        return false;
180→    }
181→
182→    // Try to match against each schema pattern
183→    // Schema pattern: "channels/{id}/messages"
184→    // Layer path:     "channels/did:key:alice/general/messages"
185→    // We need to check if the path matches the schema with DID inserted
186→    for (schema_pattern, schema) in schemas {
187→        if matches_dynamic_path(bare_path, schema_pattern, our_did) {
188→            if check_operation(&schema.permissions, operation) {
189→                return true;
190→            }
191→        }
192→    }
193→
194→    false
195→}
196→
197→/// Check if a layer path matches a dynamic schema pattern with a DID inserted
198→///
199→/// Schema patterns use `{id}` as wildcard. For creator access, the DID is
200→/// inserted as an additional path segment after the first literal segment.
201→///
202→/// **Pattern**: `channels/{id}/messages`
203→/// **Path**:    `channels/did:key:alice/general/messages`
204→///
205→/// The DID segment (`did:key:alice`) is the creator's namespace.
206→/// The `{id}` matches the user-chosen ID (`general`).
207→fn matches_dynamic_path(bare_path: &str, schema_pattern: &str, creator_did: &str) -> bool {
208→    let path_parts: Vec<&str> = bare_path.split('/').collect();
209→    let pattern_parts: Vec<&str> = schema_pattern.split('/').collect();
210→
211→    // Dynamic path has one extra segment (the DID) compared to schema pattern
212→    if path_parts.len() != pattern_parts.len() + 1 {
213→        return false;
214→    }
215→
216→    // First segment must match literally
217→    if path_parts.is_empty() || pattern_parts.is_empty() || path_parts[0] != pattern_parts[0] {
218→        return false;
219→    }
220→
221→    // Second segment in path must be the creator's DID
222→    if path_parts.len() < 2 || path_parts[1] != creator_did {
223→        return false;
224→    }
225→
226→    // Remaining segments: match path[2..] against pattern[1..]
227→    for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
228→        if *pat_seg != "{id}" && path_seg != pat_seg {
229→            return false;
230→        }
231→    }
232→
233→    true
234→}
235→
236→/// Check if a layer config allows the given operation
237→fn check_operation(config: &crate::parser::LayerConfig, operation: &str) -> bool {
238→    match operation {
239→        "read" => config.sync,
240→        "write" => config.write,
241→        "sync" => config.sync,
242→        _ => false,
243→    }
244→}
