  1→//! Contact and Device table operations
  2→
  3→use super::{RedbStore, CONTACTS, DEVICES};
  4→use crate::error::{ButlerError, Result};
  5→use crate::models::{ContactData, DeviceData};
  6→use redb::{ReadableDatabase, ReadableTable};
  7→use tracing::instrument;
  8→
  9→impl RedbStore {
 10→    // Device Operations
 11→    // Key: {device_id}
 12→
 13→    #[instrument(skip_all)]
 14→    pub fn put_device(&self, device: &DeviceData) -> Result<()> {
 15→        let value =
 16→            bincode::serialize(device).map_err(|e| ButlerError::Serialization(e.to_string()))?;
 17→
 18→        let write_txn = self.db.begin_write()?;
 19→        {
 20→            let mut table = write_txn.open_table(DEVICES)?;
 21→            table.insert(device.id.as_str(), value.as_slice())?;
 22→        }
 23→        write_txn.commit()?;
 24→        Ok(())
 25→    }
 26→
 27→    #[instrument(skip_all)]
 28→    pub fn get_device(&self, device_id: &str) -> Result<Option<DeviceData>> {
 29→        let read_txn = self.db.begin_read()?;
 30→        let table = read_txn.open_table(DEVICES)?;
 31→
 32→        match table.get(device_id)? {
 33→            Some(guard) => {
 34→                let bytes = guard.value();
 35→                let device: DeviceData = bincode::deserialize(bytes)
 36→                    .map_err(|e| ButlerError::Serialization(e.to_string()))?;
 37→                Ok(Some(device))
 38→            }
 39→            None => Ok(None),
 40→        }
 41→    }
 42→
 43→    #[instrument(skip_all)]
 44→    pub fn delete_device(&self, device_id: &str) -> Result<bool> {
 45→        let write_txn = self.db.begin_write()?;
 46→        let removed = {
 47→            let mut table = write_txn.open_table(DEVICES)?;
 48→            let result = table.remove(device_id)?;
 49→            result.is_some()
 50→        };
 51→        write_txn.commit()?;
 52→        Ok(removed)
 53→    }
 54→
 55→    #[instrument(skip_all)]
 56→    pub fn list_devices(&self) -> Result<Vec<DeviceData>> {
 57→        let read_txn = self.db.begin_read()?;
 58→        let table = read_txn.open_table(DEVICES)?;
 59→
 60→        let mut devices = Vec::new();
 61→        for result in table.iter()? {
 62→            let (_, value) = result?;
 63→            let device: DeviceData = bincode::deserialize(value.value())
 64→                .map_err(|e| ButlerError::Serialization(e.to_string()))?;
 65→            devices.push(device);
 66→        }
 67→        Ok(devices)
 68→    }
 69→
 70→    #[instrument(skip_all)]
 71→    pub fn get_current_device(&self) -> Result<Option<DeviceData>> {
 72→        let read_txn = self.db.begin_read()?;
 73→        let table = read_txn.open_table(DEVICES)?;
 74→
 75→        for result in table.iter()? {
 76→            let (_, value) = result?;
 77→            let device: DeviceData = bincode::deserialize(value.value())
 78→                .map_err(|e| ButlerError::Serialization(e.to_string()))?;
 79→            if device.is_current {
 80→                return Ok(Some(device));
 81→            }
 82→        }
 83→        Ok(None)
 84→    }
 85→
 86→    #[instrument(skip_all)]
 87→    pub fn get_node_device(&self) -> Result<Option<DeviceData>> {
 88→        let read_txn = self.db.begin_read()?;
 89→        let table = read_txn.open_table(DEVICES)?;
 90→
 91→        for result in table.iter()? {
 92→            let (_, value) = result?;
 93→            let device: DeviceData = bincode::deserialize(value.value())
 94→                .map_err(|e| ButlerError::Serialization(e.to_string()))?;
 95→            if device.is_node {
 96→                return Ok(Some(device));
 97→            }
 98→        }
 99→        Ok(None)
100→    }
101→
102→    // Contact Operations
103→    // Key: {user_did}
104→
105→    #[instrument(skip_all)]
106→    pub fn put_contact(&self, contact: &ContactData) -> Result<()> {
107→        let value =
108→            bincode::serialize(contact).map_err(|e| ButlerError::Serialization(e.to_string()))?;
109→
110→        let write_txn = self.db.begin_write()?;
111→        {
112→            let mut table = write_txn.open_table(CONTACTS)?;
113→            table.insert(contact.did.as_str(), value.as_slice())?;
114→        }
115→        write_txn.commit()?;
116→        Ok(())
117→    }
118→
119→    #[instrument(skip_all)]
120→    pub fn get_contact(&self, user_did: &str) -> Result<Option<ContactData>> {
121→        let read_txn = self.db.begin_read()?;
122→        let table = read_txn.open_table(CONTACTS)?;
