132→        }
133→    }
134→
135→    #[instrument(skip_all)]
136→    pub fn delete_contact(&self, user_did: &str) -> Result<bool> {
137→        let write_txn = self.db.begin_write()?;
138→        let removed = {
139→            let mut table = write_txn.open_table(CONTACTS)?;
