  1→//! Contacts API - Contact and device resolution operations
  2→
  3→use crate::{Butler, Result, ContactData, ConnectionDeviceInfo};
  4→use crate::services::{contact_service, node_service};
  5→
  6→/// Contacts API facade
  7→///
  8→/// Access via `butler.contacts()`
  9→pub struct ContactsApi<'a> {
 10→    pub(crate) butler: &'a Butler,
 11→}
 12→
 13→impl<'a> ContactsApi<'a> {
 14→
 15→    /// Get a contact by DID
 16→    pub fn get(&self, user_did: &str) -> Result<Option<ContactData>> {
 17→        contact_service::get_contact(self.butler.store(), user_did)
 18→    }
 19→
 20→    /// Create or update a contact
 21→    pub fn upsert(&self, contact: &ContactData) -> Result<()> {
 22→        contact_service::upsert_contact(self.butler.store(), contact)
 23→    }
 24→
 25→    /// List all contacts
 26→    pub fn list(&self) -> Result<Vec<ContactData>> {
 27→        contact_service::list_contacts(self.butler.store())
 28→    }
 29→
 30→    /// Add a node contact (viewer side - for tracking nodes viewer is subscribed to)
 31→    pub fn add_node(&self, did: &str, encryption_key: &str, name: &str, node_id: &str, permit: &str) -> Result<ContactData> {
 32→        contact_service::upsert_node_contact(self.butler.store(), did, encryption_key, name, node_id, permit)
 33→    }
 34→
 35→    /// List node contacts only (viewer side)
 36→    pub fn list_nodes(&self) -> Result<Vec<ContactData>> {
 37→        contact_service::list_node_contacts(self.butler.store())
 38→    }
 39→
 40→    /// Resolve user_did to device connection info.
 41→    ///
 42→    /// **Context**: Called by Coordinator when handling EnsureSync.
 43→    /// **We query**: Contact info for user, then connection permit.
 44→    /// **We return**: ConnectionDeviceInfo with node_id and permit.
 45→    pub fn resolve_device(&self, user_did: &str) -> Result<Option<ConnectionDeviceInfo>> {
 46→        // 1. Try contacts first (for viewer → node connections)
 47→        if let Some(contact) = contact_service::get_contact(self.butler.store(), user_did)? {
 48→            // Node type contacts have node_id and permit directly
 49→            if let (Some(node_id), Some(permit)) = (contact.node_id, contact.permit) {
 50→                return Ok(Some(ConnectionDeviceInfo { node_id, permit }));
 51→            }
 52→        }
 53→
 54→        // 2. Try sovereign nodes (for owner → node connections)
 55→        for node in node_service::list_sovereign_nodes(self.butler.store())? {
 56→            if node.did == user_did {
 57→                if let Some(permit) = node.permit {
 58→                    return Ok(Some(ConnectionDeviceInfo {
 59→                        node_id: node.node_id,
 60→                        permit,
 61→                    }));
 62→                }
 63→            }
 64→        }
 65→
 66→        Ok(None)
 67→    }
 68→
 69→    /// Store viewer-issued consent permits
 70→    ///
 71→    /// **Context**: Node receives SyncConsentGrant from viewer.
 72→    /// The permits are viewer-issued, expressing consent for receiving sync updates.
 73→    pub async fn store_viewer_consent(
 74→        &self,
 75→        viewer_did: &str,
 76→        space_id: &str,
 77→        space_consent_permit: &str,
 78→        page_consent_permits: &[(String, String)],
 79→    ) -> Result<()> {
 80→        // Store space consent (only if not empty)
 81→        if !space_consent_permit.is_empty() {
 82→            self.butler.store().put_viewer_space_consent(viewer_did, space_id, space_consent_permit)?;
 83→        }
 84→
 85→        // Store page consents
 86→        for (page_id, permit) in page_consent_permits {
 87→            self.butler.store().put_viewer_page_consent(viewer_did, page_id, permit)?;
 88→        }
 89→
 90→        Ok(())
 91→    }
 92→
 93→    /// Get viewer's space consent permit
 94→    ///
 95→    /// **Context**: Node needs consent permit to send sync updates
 96→    pub fn get_viewer_space_consent(&self, viewer_did: &str, space_id: &str) -> Result<Option<String>> {
 97→        self.butler.store().get_viewer_space_consent(viewer_did, space_id)
 98→    }
