289→    /// Handle broadcast received from Scribe - encrypt and send as SyncOffer
290→    ///
291→    /// **Context**: Scribe sent us an update to forward to this peer
292→    /// **We do**: ECDH encrypt with peer's key, send as SyncOffer
293→    /// **3-Step**: This initiates the sync protocol; we wait for SyncAccept
294→    #[instrument(skip(self, state, payload), fields(page_id = %payload.page_id, layer_name = %payload.layer_name))]
295→    pub(in crate::peer_actor) async fn handle_broadcast_received(
296→        &self,
297→        payload: butler::BroadcastPayload,
298→        state: &mut PeerActorState<C>,
299→    ) {
300→        let peer_did = match require_auth(&state.state) {
301→            Ok((did, _)) => did.to_string(),
302→            Err(_) => {
303→                warn!("Cannot send SyncOffer: peer not authenticated");
304→                return;
305→            }
306→        };
307→
308→        // Need peer's encryption key
309→        let peer_encryption_key = match state.peer_encryption_key {
310→            Some(key) => key,
311→            None => {
312→                warn!("Cannot send SyncOffer: peer encryption key not set");
313→                return;
314→            }
315→        };
316→
317→        // Encrypt update using ECDH
318→        let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
319→            &peer_encryption_key,
320→            &payload.update,
321→        ) {
322→            Ok(result) => result,
323→            Err(e) => {
324→                error!("Failed to encrypt update for SyncOffer: {}", e);
325→                return;
326→            }
327→        };
328→
329→        // Fire-and-forget: Don't track pending sync offers for real-time broadcasts.
330→        // Trust CRDTs to converge. This avoids false divergence detection when
331→        // rapid writes cause state vectors to advance before SyncAccept arrives.
332→
333→        let full_layer_name = if payload.layer_name.starts_with(&format!("{}/", payload.page_id)) {
334→            payload.layer_name.clone()
335→        } else {
336→            format!("{}/{}", payload.page_id, payload.layer_name)
337→        };
338→
339→        let authority_permit = match state
340→            .butler
341→            .permits()
342→            .get_layer_authority_permit(&payload.page_id, &full_layer_name, &peer_did)
343→        {
344→            Ok(Some((_version, permit))) => Some(permit),
345→            Ok(None) => None,
346→            Err(e) => {
347→                warn!(
348→                    page_id = %payload.page_id,
349→                    layer_name = %full_layer_name,
350→                    audience = %peer_did,
351→                    error = %e,
352→                    "Failed to look up layer authority permit for SyncOffer"
353→                );
354→                None
355→            }
356→        };
357→
358→        // Send SyncOffer with our state vector
359→        let msg = Message::SyncOffer(SyncOfferMsg {
360→            page_id: payload.page_id,
361→            layer_name: payload.layer_name.clone(),
362→            layer_type: LayerType::from_layer_name(&payload.layer_name),
363→            data: encrypted_data,
364→            state_vector: payload.state_vector,
365→            ephemeral_public,
366→            authority_permit,
367→        });
368→
369→        self.send_message(&msg, state).await;
370→        info!("Sent SyncOffer for layer {} to peer {}", payload.layer_name, self.node_id);
371→    }
372→}
