898→                self.on_space_request(&m.request_id, &m.space_id, &m.viewer_did, &m.viewer_public_key, &m.viewer_encryption_key, &m.viewer_permit, state).await;
899→            }

  1→//! Page Subscription
  2→//!
  3→//! Handles subscribing to Scribe for live sync broadcasts and forwarding
  4→//! broadcasts as SyncOffers to peers.
  5→
  6→use tracing::{debug, error, info, warn, instrument};
  7→
  8→use crate::message::*;
  9→use crate::CourierMode;
 10→use transport::Connection;
 11→
 12→use super::super::guards::require_auth;
 13→use super::super::{PeerActor, PeerActorState, PageSubscription, PeerMessage};
 14→
 15→impl<C: Connection> PeerActor<C> {
 16→
 17→    /// Subscribe to a page's Scribe for live sync broadcasts
 18→    ///
 19→    /// **Context**: After handshake, we subscribe to pages we want updates from
 20→    /// **We do**: Open page, subscribe to Scribe, spawn listener task
 21→    /// **Listener**: Forwards broadcasts as PeerMessage::BroadcastReceived
 22→    #[instrument(skip(self, myself, state, permit), fields(page_id = %page_id))]
 23→    pub(in crate::peer_actor) async fn subscribe_to_page(
 24→        &self,
 25→        myself: ractor::ActorRef<PeerMessage>,
 26→        page_id: &str,
 27→        permit: &str,
 28→        state: &mut PeerActorState<C>,
 29→    ) {
 30→        let (peer_did, _) = match require_auth(&state.state) {
 31→            Ok(info) => (info.0.to_string(), info.1.to_string()),
 32→            Err(_) => {
 33→                warn!("Cannot subscribe to page before authentication");
 34→                return;
 35→            }
 36→        };
 37→
 38→        // Check if already subscribed
 39→        if state.page_subscriptions.contains_key(page_id) {
 40→            debug!("Already subscribed to page {}", page_id);
 41→            return;
 42→        }
 43→
 44→        // Open the page (activates Scribe)
 45→        let scribe = match state.butler.open_page(page_id).await {
 46→            Ok(s) => s,
 47→            Err(e) => {
 48→                error!("Failed to open page {} for subscription: {}", page_id, e);
 49→                return;
 50→            }
 51→        };
 52→
 53→        // Determine subscription permit based on mode.
 54→        // The subscription controls what layers the peer can RECEIVE from broadcasts.
 55→        //
 56→        // **Node mode**: Look up the peer's stored page permit. The peer's permit (stored
 57→        // when they first received the page) defines what they can access. Consent permits
 58→        // from SyncOffer don't have layer definitions, so stored permit is preferred.
 59→        //
 60→        // **User mode**: Use our local permit. We sync to a single target (the node) which
 61→        // has owner-level permissions. What matters is what WE can SEND (sync=true layers).
 62→        // The local permit defines our sync capabilities.
 63→        let subscription_permit = match state.mode {
 64→            CourierMode::Node => {
 65→                // Node mode: Look up peer's stored page permit
 66→                match state.butler.permits().get_page_permit(page_id, &peer_did) {
 67→                    Ok(Some(stored_permit)) => {
 68→                        debug!("Node mode: Using stored page permit for peer {} (permit_len={})", peer_did, stored_permit.len());
 69→                        stored_permit
 70→                    }
 71→                    _ => {
 72→                        // No stored permit - try passed permit or local
 73→                        if !permit.is_empty() {
 74→                            debug!("Node mode: Using passed permit for peer {} (permit_len={})", peer_did, permit.len());
 75→                            permit.to_string()
 76→                        } else {
 77→                            match state.butler.pages().get(page_id) {
 78→                                Ok(Some(page_data)) => {
 79→                                    debug!("Node mode: Using local permit for peer {} (no stored permit)", peer_did);
 80→                                    page_data.permit.clone().unwrap_or_default()
 81→                                }
 82→                                _ => String::new()
 83→                            }
 84→                        }
 85→                    }
 86→                }
 87→            }
 88→            CourierMode::User => {
 89→                // User mode: Use our local permit - we control what we send
 90→                match state.butler.pages().get(page_id) {
 91→                    Ok(Some(page_data)) => {
 92→                        debug!("User mode: Using local permit for subscription (our sync capabilities)");
 93→                        page_data.permit.clone().unwrap_or_default()
 94→                    }
 95→                    _ => String::new()
 96→                }
 97→            }
 98→        };
 99→
100→        // Create CRDT broadcast channel
101→        let (tx, mut rx) = tokio::sync::mpsc::channel::<butler::BroadcastPayload>(32);
102→
103→        // Create ephemeral broadcast channel (for cursor/typing/presence)
104→        let (eph_tx, mut eph_rx) = tokio::sync::mpsc::channel::<butler::EphemeralOutbound>(64);
105→
106→        // Subscribe to Scribe with both CRDT and ephemeral channels
107→        let device_id = self.node_id.to_string();
108→        if let Err(e) = scribe.cast(butler::ScribeMessage::Subscribe {
109→            user_did: peer_did.clone(),
110→            device_id: device_id.clone(),
111→            broadcast_tx: tx,
112→            ephemeral_tx: Some(eph_tx),
113→            permit: subscription_permit,
114→        }) {
115→            error!("Failed to subscribe to Scribe for page {}: {}", page_id, e);
116→            return;
117→        }
118→
119→        info!("Subscribed to page {} for peer {} (with ephemeral channel)", page_id, peer_did);
120→
121→        // Spawn listener task that forwards CRDT broadcasts to this actor
122→        let actor_ref = myself.clone();
123→        let page_id_clone = page_id.to_string();
124→        let listener_handle = tokio::spawn(async move {
125→            while let Some(payload) = rx.recv().await {
126→                if let Err(_) = actor_ref.cast(PeerMessage::BroadcastReceived(payload)) {
127→                    // Actor stopped, exit loop
128→                    break;
129→                }
130→            }
131→            debug!("Broadcast listener stopped for page {}", page_id_clone);
132→        });
133→
134→        // Spawn ephemeral listener task that sends datagrams directly to peer
135→        let conn_for_eph = state.conn.clone();
136→        let page_id_for_eph = page_id.to_string();
137→        let node_id_for_eph = self.node_id;
138→        let ephemeral_listener_handle = tokio::spawn(async move {
139→            debug!(page_id = %page_id_for_eph, node_id = %node_id_for_eph, "Ephemeral listener started");
140→            while let Some(outbound) = eph_rx.recv().await {
141→                debug!(
142→                    page_id = %outbound.page_id,
143→                    node_id = %node_id_for_eph,
144→                    payload_len = outbound.payload.len(),
145→                    "PeerActor received ephemeral from Scribe, sending datagram"
146→                );
147→                // Create protocol-level EphemeralDatagram
148→                let datagram = crate::message::EphemeralDatagram {
149→                    page_id: outbound.page_id,
150→                    payload: outbound.payload,
151→                };
152→                if let Ok(data) = datagram.to_bytes() {
153→                    // send_datagram is sync (Result, not Future)
154→                    match conn_for_eph.send_datagram(&data) {
155→                        Ok(()) => {
156→                            debug!(node_id = %node_id_for_eph, datagram_len = data.len(), "Ephemeral datagram sent");
157→                        }
158→                        Err(e) => {
159→                            warn!(node_id = %node_id_for_eph, error = %e, "Failed to send ephemeral datagram");
160→                        }
161→                    }
162→                } else {
163→                    warn!(node_id = %node_id_for_eph, "Failed to serialize ephemeral datagram");
164→                }
165→            }
166→            debug!(page_id = %page_id_for_eph, "Ephemeral listener stopped");
167→        });
168→
169→        // Store full subscription info for cleanup on disconnect
170→        let subscription = PageSubscription {
171→            scribe: scribe.clone(),
172→            listener_handle,
173→            ephemeral_listener_handle,
174→            user_did: peer_did,
175→            device_id,
176→        };
177→        state.page_subscriptions.insert(page_id.to_string(), subscription);
178→
179→        // Register direct Scribe connection and flush any buffered messages
180→        // This implements the receiver-initiates pattern for reliable message delivery
181→        if let Some(buffered) = state.pending_scribe_messages.remove(page_id) {
182→            let count = buffered.len();
183→            info!(
184→                page_id = %page_id,
185→                buffered_count = count,
186→                "Flushing {} buffered messages to Scribe on subscription",
187→                count
188→            );
189→            for msg in buffered {
190→                if let Err(e) = scribe.cast(butler::ScribeMessage::RemoteEphemeral {
191→                    user_did: msg.user_did,
192→                    device_id: msg.device_id,
193→                    payload: msg.payload,
194→                }) {
195→                    warn!(page_id = %page_id, error = %e, "Failed to flush buffered message");
196→                } else {
197→                    debug!(page_id = %page_id, "Flushed buffered message to Scribe");
198→                }
199→            }
200→        }
201→        state.scribe_connections.insert(page_id.to_string(), scribe.clone());
202→    }
203→
204→    /// Subscribe this peer to all active Scribes they have access to
205→    ///
206→    /// **Context**: Called after handshake completes to auto-subscribe to open pages
207→    /// **We do**: Query Butler for active Scribes, subscribe to each
208→    #[instrument(skip(self, myself, state))]
209→    pub(in crate::peer_actor) async fn subscribe_to_active_scribes(
210→        &self,
211→        myself: ractor::ActorRef<PeerMessage>,
212→        state: &mut PeerActorState<C>,
213→    ) {
214→        let peer_did = match require_auth(&state.state) {
215→            Ok((did, _)) => did.to_string(),
216→            Err(_) => {
217→                warn!("Cannot subscribe to active scribes: peer not authenticated");
218→                return;
219→            }
220→        };
221→
222→        let active_pages = match state.butler.list_active_scribes_for_peer(&peer_did).await {
223→            Ok(pages) => pages,
224→            Err(e) => {
225→                warn!("Failed to list active scribes for peer {}: {}", peer_did, e);
226→                return;
227→            }
228→        };
229→
230→        if active_pages.is_empty() {
231→            debug!("No active scribes to subscribe peer {} to", peer_did);
232→            return;
233→        }
234→
235→        info!(
236→            "Auto-subscribing peer {} to {} active scribes",
237→            peer_did, active_pages.len()
238→        );
239→
240→        for (page_id, permit) in active_pages {
241→            self.subscribe_to_page(myself.clone(), &page_id, &permit, state).await;
242→        }
243→    }
244→
245→    /// Check subscription health and resubscribe to dead listeners
246→    ///
247→    /// **Context**: Periodic health check or after reconnection
248→    /// **We do**: Check if listener tasks are finished, resubscribe if dead
249→    /// **Design**: Fixes subscription loss after connection issues
250→    #[instrument(skip(self, myself, state))]
251→    pub(in crate::peer_actor) async fn check_subscription_health(
252→        &self,
253→        myself: ractor::ActorRef<PeerMessage>,
254→        state: &mut PeerActorState<C>,
255→    ) {
256→        let dead_subscriptions: Vec<String> = state.page_subscriptions
257→            .iter()
258→            .filter_map(|(page_id, sub)| {
259→                // Check if either listener has died
260→                if sub.listener_handle.is_finished() || sub.ephemeral_listener_handle.is_finished() {
261→                    warn!(page_id = %page_id, "Subscription listener died, will resubscribe");
262→                    Some(page_id.clone())
263→                } else {
264→                    None
265→                }
266→            })
267→            .collect();
268→
269→        // Resubscribe to dead subscriptions
270→        for page_id in dead_subscriptions {
271→            // Remove the dead subscription first
272→            if let Some(sub) = state.page_subscriptions.remove(&page_id) {
273→                // Abort any still-running handles to clean up
274→                sub.listener_handle.abort();
275→                sub.ephemeral_listener_handle.abort();
276→
277→                // Send unsubscribe to clean up Scribe state
278→                let _ = sub.scribe.cast(butler::ScribeMessage::Unsubscribe {
279→                    user_did: sub.user_did,
280→                    device_id: sub.device_id,
281→                });
282→            }
283→
284→            // Resubscribe (uses empty permit - will look up stored permit)
285→            self.subscribe_to_page(myself.clone(), &page_id, "", state).await;
286→        }
287→    }
288→
289→    /// Handle broadcast received from Scribe - encrypt and send as SyncOffer
290→    ///
291→    /// **Context**: Scribe sent us an update to forward to this peer
292→    /// **We do**: ECDH encrypt with peer's key, send as SyncOffer
293→    /// **3-Step**: This initiates the sync protocol; we wait for SyncAccept
294→    #[instrument(skip(self, state, payload), fields(page_id = %payload.page_id, layer_name = %payload.layer_name))]
295→    pub(in crate::peer_actor) async fn handle_broadcast_received(
296→        &self,
297→        payload: butler::BroadcastPayload,
298→        state: &mut PeerActorState<C>,
299→    ) {
300→        let peer_did = match require_auth(&state.state) {
301→            Ok((did, _)) => did.to_string(),
302→            Err(_) => {
303→                warn!("Cannot send SyncOffer: peer not authenticated");
304→                return;
305→            }
306→        };
307→
308→        // Need peer's encryption key
309→        let peer_encryption_key = match state.peer_encryption_key {
310→            Some(key) => key,
311→            None => {
312→                warn!("Cannot send SyncOffer: peer encryption key not set");
313→                return;
314→            }
315→        };
316→
317→        // Encrypt update using ECDH
318→        let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
319→            &peer_encryption_key,
320→            &payload.update,
321→        ) {
322→            Ok(result) => result,
323→            Err(e) => {
324→                error!("Failed to encrypt update for SyncOffer: {}", e);
325→                return;
326→            }
327→        };
328→
329→        // Fire-and-forget: Don't track pending sync offers for real-time broadcasts.
330→        // Trust CRDTs to converge. This avoids false divergence detection when
331→        // rapid writes cause state vectors to advance before SyncAccept arrives.
332→
333→        let full_layer_name = if payload.layer_name.starts_with(&format!("{}/", payload.page_id)) {
334→            payload.layer_name.clone()
335→        } else {
336→            format!("{}/{}", payload.page_id, payload.layer_name)
337→        };
338→
339→        let authority_permit = match state
340→            .butler
341→            .permits()
342→            .get_layer_authority_permit(&payload.page_id, &full_layer_name, &peer_did)
343→        {
344→            Ok(Some((_version, permit))) => Some(permit),
345→            Ok(None) => None,
346→            Err(e) => {
347→                warn!(
348→                    page_id = %payload.page_id,
349→                    layer_name = %full_layer_name,
350→                    audience = %peer_did,
351→                    error = %e,
352→                    "Failed to look up layer authority permit for SyncOffer"
353→                );
354→                None
355→            }
356→        };
357→
358→        // Send SyncOffer with our state vector
359→        let msg = Message::SyncOffer(SyncOfferMsg {
360→            page_id: payload.page_id,
361→            layer_name: payload.layer_name.clone(),
362→            layer_type: LayerType::from_layer_name(&payload.layer_name),
363→            data: encrypted_data,
364→            state_vector: payload.state_vector,
365→            ephemeral_public,
366→            authority_permit,
367→        });
368→
369→        self.send_message(&msg, state).await;
370→        info!("Sent SyncOffer for layer {} to peer {}", payload.layer_name, self.node_id);
371→    }
372→}
