pub fn process_creator_sync_meta(state: &mut ScribeState, creator_did: &str) {
    // 1. Read all entries from creator's __sync_meta (e.g., __sync_meta:did:key:alice)
    let entries = read_sync_meta_entries(state, creator_did);

    // 2. Get list of ALL other peers (exclude creator)
    let all_peer_dids: Vec<String> = { /* scan subscribers */ };

    // 3. For each entry in creator's __sync_meta:
    for entry in &entries {
        if is_protocol_layer(&entry.layer_name) { continue; }  // Skip protocol layers

        // Match against dynamic schemas (if any)
        let Some((_schema_key, schema, path_creator_did)) =
            find_matching_dynamic_schema(&our_permit, &entry.layer_name, &page_id)
        else {
            continue;
        };

        if path_creator_did != creator_did { continue; }  // Only process entries CREATED by this peer

        // 4. DISTRIBUTE based on grant type:
        match schema.grant {
            GrantType::Open => {
                // Write to ALL other peers' __sync_meta
                for peer_did in &all_peer_dids {
                    let peer_entries = read_sync_meta_entries(state, peer_did);
                    if !already_has {
                        pending_writes.push(PendingMetaWrite {
                            peer_did: peer_did.clone(),
                            layer_name: entry.layer_name.clone(),
                            synced: false,  // Mark as unsynced (peer needs to pull)
                        });
                    }
                }
                // Mark creator's entry as synced (they already have the data)
                pending_writes.push(PendingMetaWrite {
                    peer_did: creator_did.to_string(),
                    layer_name: entry.layer_name.clone(),
                    synced: true,
                });
            }
            GrantType::Explicit => {
                // Check issuer for permission, write to authorized peers only
                let full_layer_name = format!("{}/{}", page_id, entry.layer_name);
                for peer_did in &all_peer_dids {
                    let has_authority = issuer
                        .get_layer_authority_permit(peer_did, &full_layer_name)
                        .ok()
                        .flatten()
                        .is_some();

                    if has_authority {
                        pending_writes.push(PendingMetaWrite {
                            peer_did: peer_did.clone(),
                            layer_name: entry.layer_name.clone(),
                            synced: false,
                        });
                    }
                }
                // Mark creator's entry as synced
                pending_writes.push(PendingMetaWrite {
                    peer_did: creator_did.to_string(),
                    layer_name: entry.layer_name.clone(),
                    synced: true,
                });
            }
        }
    }

    // 5. Apply all pending writes (write to OTHER peers' __sync_meta)
    for write in pending_writes {
        write_sync_meta_entry(state, &write.peer_did, &write.layer_name, write.synced);
    }
}
```

**Key semantic**:
- **INPUT**: Creator's `__sync_meta:did:alice` contains `{ "messages": false, "reactions": false }`
- **PROCESSING**: Node reads these entries, checks permit schemas, determines distribution
- **OUTPUT**: Node writes entries to `__sync_meta:did:bob`, `__sync_meta:did:carol`, etc.
  - Open grant: write to all peers with `synced=false`
  - Explicit grant: write only to permitted peers with `synced=false`
  - Creator: mark their own entry as `synced=true`

