pub async fn broadcast_update(
    state: &mut ScribeState,
    layer_name: &str,
    from_peer: Option<&(String, String)>,
) {
    let Some(unit) = state.units.get(layer_name) else { return; };
    let current_vector = unit.layer().version_vector();

    // Iterate ALL subscribers for this layer (including __sync_meta)
    for (did, sub) in layer_subs.iter_mut() {
        if sender_did == Some(did.as_str()) { continue; }  // Skip sender
        if !sub.capabilities.read { continue; }             // Check read capability

        let update = if !sub.version_vector.is_empty() {
            layer.export_updates(&sub.version_vector)
        } else {
            layer.export_snapshot()
        };

        let payload = BroadcastPayload { ... };
        sub.broadcast_tx.try_send(payload)  // Send to subscriber
    }
}
```

