```rust
// ===== PEER SIDE (USER mode) =====
pub async fn check_sync_meta_and_subscribe(&self, page_id: &str, state: &mut PeerActorState<C>) {
    if require_user_mode(state.mode, "...").is_some() { return; }

    let scribe = state.butler.open_page(page_id).await?;

    // 1. Query Scribe for unsynced __sync_meta entries
    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
    scribe.cast(butler::ScribeMessage::GetUnsyncedSyncMeta { reply: reply_tx })?;

    let unsynced = reply_rx.await?;  // E.g., ["messages", "reactions"]

    if unsynced.is_empty() {
        debug!("No unsynced __sync_meta entries");
        return;
    }

    info!("Discovered {} unsynced layers, sending LayerSubscribe", unsynced.len());

    // 2. For each unsynced entry, send LayerSubscribe to node
    for layer_name in unsynced {
        let request_id = uuid::Uuid::new_v4().to_string();
        let msg = Message::LayerSubscribe(LayerSubscribeMsg {
            request_id,
            page_id: page_id.to_string(),
            layer_name: layer_name.clone(),  // E.g., "messages"
        });
        self.send_message(&msg, state).await;
        debug!("Sent LayerSubscribe for {}", layer_name);
    }
}

// ===== NODE SIDE (NODE mode) =====
pub async fn on_layer_subscribe(
    &self,
    request_id: &str,
    page_id: &str,
    layer_name: &str,  // E.g., "messages" (from __sync_meta entry)
    state: &mut PeerActorState<C>,
) {
    if require_node_mode(state.mode, "...").is_some() { return; }

    let (peer_did, _) = require_auth(&state.state)?;

    info!("LayerSubscribe: page={} layer={} from peer={}", page_id, layer_name, peer_did);

    // 1. Get Scribe
    let scribe = state.page_subscriptions.get(page_id)?.scribe.clone();

    // 2. Delegate to Scribe: issues permit, exports snapshot
    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
    scribe.cast(butler::ScribeMessage::HandleLayerSubscribe {
        layer_name: layer_name.to_string(),
        peer_did: peer_did.clone(),
        reply: reply_tx,
    })?;

    let (snapshot_data, state_vector, layer_permit) = reply_rx.await??;

    // 3. Encrypt snapshot for transfer
    let (ephemeral_public, encrypted_data) = herald::encrypt_for_transfer(
        &state.peer_encryption_key,
        &snapshot_data,
    )?;

    // *** KEY: Mark entry as synced in peer's __sync_meta on the node ***
    if let Some(sub) = state.page_subscriptions.get(page_id) {
        let meta_layer = format!("__sync_meta:{}", peer_did);
        sub.scribe.cast(butler::ScribeMessage::UpdateFromJson {
            layer_name: meta_layer,
            path: layer_name.to_string(),  // E.g., "messages"
            value: serde_json::json!(true),  // Mark as synced
            reply: None,
        })?;
    }

    // 4. Send LayerSubscribeAck with encrypted data
    let msg = Message::LayerSubscribeAck(LayerSubscribeAckMsg {
        request_id: request_id.to_string(),
        page_id: page_id.to_string(),
        layer_name: layer_name.to_string(),
        accepted: true,
        data: encrypted_data,
        state_vector,
        ephemeral_public,
        layer_permit,
    });
    self.send_message(&msg, state).await;
    info!("Sent LayerSubscribeAck");
}

// ===== PEER SIDE (USER mode) - Receive and Apply =====
pub async fn on_layer_subscribe_ack(
    &self,
    _request_id: &str,
    page_id: &str,
    layer_name: &str,  // E.g., "messages"
    accepted: bool,
    data: &[u8],
    ephemeral_public: &[u8; 32],
    layer_permit: &str,
    state: &mut PeerActorState<C>,
) {
    if require_user_mode(state.mode, "...").is_some() { return; }

    if !accepted { warn!("LayerSubscribeAck rejected"); return; }

    // 1. Decrypt data
    let our_secret = state.butler.encryption_key().await?;
    let decrypted_data = herald::decrypt_from_transfer(&our_secret, ephemeral_public, data)?;

    // 2. Store layer permit
    let full_layer_name = format!("{}/{}", page_id, layer_name);
    let our_did = state.butler.get_identity().await?.did().to_string();
    state.butler.permits().store_layer_permit(
        page_id, &our_did, &full_layer_name, layer_permit,
    )?;

    // 3. Apply data to Scribe
    if let Some(subscription) = state.page_subscriptions.get(page_id) {
        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
        subscription.scribe.cast(butler::ScribeMessage::ApplyUpdateWithResult {
            layer_name: layer_name.to_string(),
            update: decrypted_data,
            from_peer: Some((node_did.clone(), self.node_id.to_string())),
            permit: Some(layer_permit.to_string()),
            reply: reply_tx,
        })?;

        reply_rx.await??;  // Wait for apply
        info!("Applied LayerSubscribeAck data for layer={}", layer_name);
    }

    // 4. Mark __sync_meta entry as synced
    subscription.scribe.cast(butler::ScribeMessage::MarkSyncMetaSynced {
        layer_name: layer_name.to_string(),
    }).ok();
}
```

