//! Layer Subscribe Protocol (pull-based via __sync_meta)
//!
//! Handles the pull-based layer discovery and subscription flow:
//! 1. Peer detects new entries in their __sync_meta (via SyncOffer)
//! 2. Peer sends LayerSubscribe for each unsynced layer
//! 3. Node validates, exports snapshot, issues permit, responds with LayerSubscribeAck
//! 4. Peer decrypts data, stores permit, applies to Scribe, marks synced

use tracing::{debug, error, info, warn, instrument};

use crate::message::*;
use transport::Connection;

use super::guards::{require_node_mode, require_user_mode, require_auth};
use super::{PeerActor, PeerActorState};
use butler::ScribeMessage;

impl<C: Connection> PeerActor<C> {

    /// Detect __sync_meta updates and send LayerSubscribe for unsynced entries
    ///
    /// **Context**: PeerActor applied a SyncOffer for a __sync_meta layer
    /// **We do**: Query Scribe for unsynced entries, send LayerSubscribe for each
    #[instrument(skip(self, state), fields(node = %self.node_id, page_id = %page_id))]
    pub(in crate::peer_actor) async fn check_sync_meta_and_subscribe(
        &self,
        page_id: &str,
        state: &mut PeerActorState<C>,
    ) {
        // Only peer side (user mode) subscribes — node doesn't subscribe to layers
        if require_user_mode(state.mode, "check_sync_meta_and_subscribe").is_some() {
            return;
        }

        let scribe = match state.butler.open_page(page_id).await {
            Ok(s) => s,
            Err(e) => {
                error!("Failed to open page {} for sync_meta check: {}", page_id, e);
                return;
            }
        };

        // Query Scribe for unsynced __sync_meta entries
        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
        if let Err(e) = scribe.cast(ScribeMessage::GetUnsyncedSyncMeta { reply: reply_tx }) {
            error!("Failed to query unsynced sync_meta: {}", e);
            return;
        }

        let unsynced = match reply_rx.await {
            Ok(entries) => entries,
            Err(_) => {
                error!("GetUnsyncedSyncMeta reply channel dropped");
                return;
            }
        };

        if unsynced.is_empty() {
            debug!("No unsynced __sync_meta entries for page={}", page_id);
            return;
        }

        info!(
            page_id = %page_id,
            count = unsynced.len(),
            "Discovered {} unsynced layers via __sync_meta, sending LayerSubscribe",
            unsynced.len()
        );

        for layer_name in unsynced {
            let request_id = uuid::Uuid::new_v4().to_string();
            let msg = Message::LayerSubscribe(LayerSubscribeMsg {
                request_id,
                page_id: page_id.to_string(),
                layer_name: layer_name.clone(),
            });
            self.send_message(&msg, state).await;
            debug!(page_id = %page_id, layer = %layer_name, "Sent LayerSubscribe");
        }
    }

    /// Handle incoming LayerSubscribe from peer (Node-side handler)
    ///
    /// **Context**: Peer discovered a layer in __sync_meta, requests data + permit
    /// **We do**: Delegate to Scribe (which issues permit + exports snapshot), encrypt, respond
    #[instrument(skip(self, state), fields(page_id = %page_id, layer = %layer_name))]
    pub(in crate::peer_actor) async fn on_layer_subscribe(
        &self,
        request_id: &str,
        page_id: &str,
        layer_name: &str,
        state: &mut PeerActorState<C>,
    ) {
        if require_node_mode(state.mode, "on_layer_subscribe").is_some() {
            return;
        }

        let (peer_did, _) = match require_auth(&state.state) {
            Ok(info) => (info.0.to_string(), info.1.to_string()),
            Err(_) => {
                warn!("LayerSubscribe from unauthenticated peer: {}", self.node_id);
                return;
            }
        };

        info!(
            "LayerSubscribe: page={} layer={} from peer={}",
            page_id, layer_name, peer_did
        );

        // Get Scribe for this page
        let scribe = match state.page_subscriptions.get(page_id) {
            Some(sub) => sub.scribe.clone(),
            None => {
                warn!("LayerSubscribe: no page subscription for page={}", page_id);
                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "page not subscribed", state).await;
                return;
            }
        };

        // Delegate to Scribe: issues permit, adds subscriber, exports snapshot
        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
        if let Err(e) = scribe.cast(ScribeMessage::HandleLayerSubscribe {
            layer_name: layer_name.to_string(),
            peer_did: peer_did.clone(),
            reply: reply_tx,
        }) {
            error!("Failed to send HandleLayerSubscribe to Scribe: {}", e);
            self.send_layer_subscribe_reject(request_id, page_id, layer_name, "internal error", state).await;
            return;
        }

        let (snapshot_data, state_vector, layer_permit) = match reply_rx.await {
            Ok(Ok(result)) => result,
            Ok(Err(e)) => {
                warn!("HandleLayerSubscribe error for layer={}: {}", layer_name, e);
                self.send_layer_subscribe_reject(request_id, page_id, layer_name, &e, state).await;
                return;
            }
            Err(_) => {
                error!("HandleLayerSubscribe reply dropped for layer={}", layer_name);
                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "internal error", state).await;
                return;
            }
        };

        // Encrypt snapshot for transfer
        let peer_encryption_key = match state.peer_encryption_key {
            Some(key) => key,
            None => {
                warn!("Cannot send LayerSubscribeAck: peer encryption key not set");
                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "no encryption key", state).await;
                return;
            }
        };

        let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
            &peer_encryption_key,
            &snapshot_data,
        ) {
            Ok(result) => result,
            Err(e) => {
                error!("Failed to encrypt LayerSubscribeAck data: {}", e);
                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "encryption failed", state).await;
                return;
            }
        };

        // Mark the entry as synced in the peer's __sync_meta on the node
        if let Some(sub) = state.page_subscriptions.get(page_id) {
            let meta_layer = format!("__sync_meta:{}", peer_did);
            let _ = sub.scribe.cast(ScribeMessage::UpdateFromJson {
                layer_name: meta_layer,
                path: layer_name.to_string(),
                value: serde_json::json!(true),
                reply: None,
            });
        }

        let msg = Message::LayerSubscribeAck(LayerSubscribeAckMsg {
            request_id: request_id.to_string(),
            page_id: page_id.to_string(),
            layer_name: layer_name.to_string(),
            accepted: true,
            reason: None,
            data: encrypted_data,
            state_vector,
            ephemeral_public,
            layer_permit,
        });

        self.send_message(&msg, state).await;
        info!("Sent LayerSubscribeAck for page={} layer={} to peer={}", page_id, layer_name, peer_did);
    }

    /// Send a rejected LayerSubscribeAck
    async fn send_layer_subscribe_reject(
        &self,
        request_id: &str,
        page_id: &str,
        layer_name: &str,
        reason: &str,
        state: &PeerActorState<C>,
    ) {
        let msg = Message::LayerSubscribeAck(LayerSubscribeAckMsg {
            request_id: request_id.to_string(),
            page_id: page_id.to_string(),
            layer_name: layer_name.to_string(),
            accepted: false,
            reason: Some(reason.to_string()),
            data: Vec::new(),
            state_vector: Vec::new(),
            ephemeral_public: [0u8; 32],
            layer_permit: String::new(),
        });
        self.send_message(&msg, state).await;
    }

    /// Handle incoming LayerSubscribeAck from node (Peer-side handler)
    ///
    /// **Context**: Node processed our LayerSubscribe, sent data + permit
    /// **We do**: Decrypt data, store permit, apply to Scribe, authorize node, mark synced
    #[instrument(skip(self, state, data, _state_vector, ephemeral_public, layer_permit), fields(page_id = %page_id, layer = %layer_name))]
    pub(in crate::peer_actor) async fn on_layer_subscribe_ack(
        &self,
        _request_id: &str,
        page_id: &str,
        layer_name: &str,
        accepted: bool,
        reason: Option<&str>,
        data: &[u8],
        _state_vector: &[u8],
        ephemeral_public: &[u8; 32],
        layer_permit: &str,
        state: &mut PeerActorState<C>,
    ) {
        if require_user_mode(state.mode, "on_layer_subscribe_ack").is_some() {
            return;
        }

        let (node_did, _) = match require_auth(&state.state) {
            Ok(info) => (info.0.to_string(), info.1.to_string()),
            Err(_) => {
                warn!("LayerSubscribeAck from unauthenticated peer: {}", self.node_id);
                return;
            }
        };

        if !accepted {
            warn!(
                "LayerSubscribeAck rejected for page={} layer={}: {}",
                page_id, layer_name, reason.unwrap_or("unknown")
            );
            return;
        }

        info!(
            "LayerSubscribeAck: page={} layer={} from node={} data_len={}",
            page_id, layer_name, node_did, data.len()
        );

        // 1. Decrypt data
        let our_secret = match state.butler.encryption_key().await {
            Ok(key) => key,
            Err(e) => {
                error!("Failed to get encryption key for LayerSubscribeAck: {}", e);
                return;
            }
        };

        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
            Ok(plaintext) => plaintext,
            Err(e) => {
                error!("Failed to decrypt LayerSubscribeAck data: {}", e);
                return;
            }
        };

        // 2. Store layer permit
        let full_layer_name = format!("{}/{}", page_id, layer_name);
        let our_did = match state.butler.get_identity().await {
            Ok(identity) => identity.did().to_string(),
            Err(e) => {
                error!("Failed to get our identity: {}", e);
                return;
            }
        };

        if let Err(e) = state.butler.permits().store_layer_permit(
            page_id, &our_did, &full_layer_name, layer_permit,
        ) {
            error!("Failed to store layer permit: {}", e);
            return;
        }

        info!("Stored layer permit for layer={}", full_layer_name);

        // 3. Apply data to Scribe
        if let Some(subscription) = state.page_subscriptions.get(page_id) {
            let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
            if let Err(e) = subscription.scribe.cast(ScribeMessage::ApplyUpdateWithResult {
                layer_name: layer_name.to_string(),
                update: decrypted_data,
                from_peer: Some((node_did.clone(), self.node_id.to_string())),
                permit: Some(layer_permit.to_string()),
                reply: reply_tx,
            }) {
                error!("Failed to send ApplyUpdate for LayerSubscribeAck: {}", e);
                return;
            }

            match reply_rx.await {
                Ok(Ok(())) => {
                    info!("Applied LayerSubscribeAck data for layer={}", layer_name);
                }
                Ok(Err(e)) => {
                    warn!("Scribe rejected LayerSubscribeAck data for layer={}: {}", layer_name, e);
                }
                Err(_) => {
                    error!("ApplyUpdate reply dropped for layer={}", layer_name);
                    return;
                }
            }

            // 4. Authorize node as subscriber for bidirectional sync
            subscription.scribe.cast(ScribeMessage::AuthorizeLayerSubscriber {
                layer_name: layer_name.to_string(),
                subscriber_did: node_did.clone(),
            }).ok();
            info!("Authorized node {} on layer={}", node_did, layer_name);

            // 5. Mark __sync_meta entry as synced
            subscription.scribe.cast(ScribeMessage::MarkSyncMetaSynced {
                layer_name: layer_name.to_string(),
            }).ok();
        } else {
            warn!("No page subscription for page={}, cannot apply LayerSubscribeAck", page_id);
        }
    }
}

